Ceviri.ekle("uk","olay",{
"KRONOLOJI_COK_ARABISTAN2:1538-01-01:0":{"b": ["Хадрамаут стає османським санджаком — внутрішнє управління залишається за вождями Катірі", "d80f8d20"], "d": ["Хадрамаут, який перейшов під османське управління під час індійського походу Хадима Сулейман-паші, було організовано як санджак, підпорядкований Ємену. Проте всередині Хадрамауту фактичне управління тримали в руках вожді племені Катірі; османське панування обмежувалося узбережжям і податковим зв'язком.", "93dd8a13"]},
"KRONOLOJI_COK_ARABISTAN2:1659-01-01:0":{"b": ["Зейдитський імам аль-Мутаваккіль Аллах вторгся в Хадрамаут — султанат Катірі підпорядковано єменському імамату", "21ad9c85"], "d": ["Зейдитський імамат, посилившись після відходу османів з Ємену 1635 року, за часів імама аль-Мутаваккіля Аллаха послав військо, яке вторглося в Хадрамаут. Так влада Катірі у внутрішньому Хадрамауті майже пів століття залишалася підлеглою єменському імамату; коли в першій половині XVIII століття вплив імамів і Катірі ослаб, управління знову перейшло до місцевих племен.", "e5a06ff4"]},
"KRONOLOJI_COK_ARABISTAN2:1835-01-01:0":{"b": ["Абдуллах ібн Рашид відібрав емірат Хаїль у родини Ібн Алі — засновано емірат Шаммар (Рашидидів)", "357cc1a0"], "d": ["Абдуллах ібн Рашид із роду Абде, найбільшої гілки племені шаммар, разом із братом Убайдом 1835 року переміг у боротьбі, розпочатій проти родини Ібн Алі, яка правила Хаїлем, і захопив емірат. Завдяки розташуванню на торговельному шляху та шляху паломництва між Месопотамією і Хіджазом Хаїль став центром влади Рашидидів над Джебель-Шаммаром, яка тривала до 1921 року.", "dc0300b5"]},
"OLAYLAR:1299-01:0":{"b": ["Заснування Османського бейліку", "9f0b7c0a"], "d": ["Те, що Осман Газі з племені кайи почав діяти самостійно в околицях Сьогюта та Доманіча, вважають усталеною традиційною точкою відліку заснування Османської держави; деякі історики вважають справжнім переломним моментом перемогу під Бафеєм 1302 року. Завдяки своєму розташуванню на візантійському прикордонні бейлік швидко набирав силу через походи газі. У цих умовах, коли сельджуцька спадщина розпадалася, Осман Газі згуртував довкола себе ахі, газі та кочових туркменів; його зв'язок із шейхом Едебалі вважають основою духовної легітимності бейліку. Інші місця, приєднані тоді ж: Інеґьоль, Ярхісар.", "9d689d45"]},
"OLAYLAR:1326-04-06:0":{"b": ["Завоювання Бурси", "98c727fa"], "d": ["Бурса, яку роками тримали в блокаді, здалася Орхану Газі, що керував останнім етапом облоги; місто стало першою великою столицею бейліку. За переказом, звістку про завоювання донесли Осману Газі, який лежав на смертному одрі; згідно з його заповітом, Османа Газі поховали в Бурсі. Незабаром місто забудували мечетями, імаретами та медресе, і воно стало зразком раннього османського містобудування.", "9ede6ee9"]},
"OLAYLAR:1331-03-02:0":{"b": ["Завоювання Ізніка", "a846a811"], "d": ["Ізнік (Нікея), один із найважливіших візантійських центрів в Анатолії, після перемоги під Пелеканоном 1329 року втратив надію на опір і здався Орхану Газі. Тут було засновано перше османське медресе, і такі вчені, як Давуд аль-Кайсарі, почали викладати; місто стало центром науки раннього періоду. Церкву Святої Софії перетворили на мечеть, явивши ранній приклад завойовницької традиції.", "8fd3bfb5"]},
"OLAYLAR:1337-01-01:0":{"b": ["Завоювання Ізміта", "06a35035"], "d": ["З падінням Ізміта (Нікомедії) під османську владу перейшла й остання важлива візантійська фортеця на анатолійському боці; увесь півострів Коджаелі аж до протилежного від Константинополя берега став османською землею. Так бейлік, запанувавши над усім південним і східним узбережжям Мармурового моря, підготував підґрунтя для переходу в Румелію.", "f677745c"]},
"OLAYLAR:1352-03-01:0":{"b": ["Фортеця Чимпе — перехід у Румелію", "c2f0a07d"], "d": ["Сулейман-паша, син Орхана Газі, 1352 року зробив своєю базою фортецю Чимпе, віддану під час візантійської громадянської війни; після великого землетрусу в березні 1354 року, що зруйнував Галліполі, спорожнілі фортеці швидко укріпили, і півострів перетворили на постійний османський плацдарм. Цей крок, підкріплений переселенням туркменського населення з Анатолії, став початком присутності османів на європейському континенті, яка тривала понад 550 років.", "4857333a"]},
"OLAYLAR:1361-05-05:0":{"b": ["Завоювання Едірне", "2f54ebb0"], "d": ["Взяття Едірне (Адріанополя), ключового міста Фракії, визначило головну базу та напрямок балканських завоювань; дата завоювання в джерелах є предметом дискусій — між 1361 і 1369 роками. Невдовзі місто стало столицею, засвідчивши, що центр ваги держави перемістився в Румелію; воно залишалося престольним містом (пайтахтом) близько 90 років, аж до завоювання Константинополя.", "25bd644f"]},
"OLAYLAR:1362-03:0":{"b": ["Мурад I зійшов на престол", "f8d48a26"], "d": ["Мурад I (Худавендіґяр), який посів престол після смерті Орхана Газі, за 27 років правління перетворив державу з прикордонного бейліку на кістяк імперії. Запровадженням системи пенчик було закладено основу яничарського корпусу, поширено тімарну систему, засновано Румелійський бейлербейлік і зміцнено інститут візирату. За його правління балканські завоювання стали систематичною державною політикою.", "d463078a"]},
"OLAYLAR:1389-06-15:0":{"b": ["Перша Косовська битва — загибель Мурада I за віру", "10b8ddc9"], "d": ["Балканський союз на чолі з князем Лазарем зазнав вирішальної поразки на Косовому полі; Сербія перейшла під османський сюзеренітет. Мурада I, який оглядав поле бою, заколов кинджалом сербський шляхтич Милош Обилич, і султан загинув як шахід — це єдиний османський султан, який помер на полі бою. На його місце в таборі посадили Баязида Блискавичного (Йилдирима); його брата Якуба Челебі задушили, і це стало одним із перших відомих прикладів практики братовбивства.", "153449fe"]},
"OLAYLAR:1396-09-25:0":{"b": ["Перемога під Нікополем", "75716e96"], "d": ["Велике військо хрестоносців, зібране на заклик угорського короля Сигізмунда, до якого приєдналися й французькі та бургундські лицарі, Баязид Блискавичний вщент розгромив під Нікополем на березі Дунаю. Перемога остаточно закріпила османське панування над Болгарією; протягом цілого покоління в Європі не вдалося організувати великого хрестового походу.", "0d06e36c"]},
"OLAYLAR:1402-07-28:0":{"b": ["Анкарська битва — почалося Османське міжцарів'я", "b4a99d96"], "d": ["У тяжкій поразці від війська Тимура на Чубуцькій рівнині Баязид Блискавичний потрапив у полон і через кілька місяців помер у неволі. Тимур відродив анатолійські бейліки; османські землі поділили між собою сини Баязида, і почалася боротьба за престол, що тривала 11 років (міжцарів'я, Фетрет). Цей період, найтяжча криза держави від часу її заснування, закарбував в османській пам'яті важливість централізованого устрою. Інші поселення, втрачені тоді ж: Датча, Мармарис, Фетхіє (Макрі), Сьоке, Кютах'я, Афьон, Іспарта, Маніса, Айдин, Денізлі, Мугла, Анталія, Конья, Караман, Кайсері, Кастамону, Бартин, Сафранболу, Самсун, Сівас, Малатья, Бейшехір, Сіврігісар, Киршехір, Чорум, Чанкири, Єнішехір (Бурса), Інеґьоль, фортеця Айдос, Ґейве, Кьопрюхісар (Єнішехір), Мармараджик, Акхісар (Памукова), Мекедже, Кестель, Улубат, Харманкая, Акьязи, острів Імрали, Кандира, Муданья, Ялова, Карамюрсель, Армутлу, Гемлік (Кіос), Сьогют, Біледжик, Ескішехір, Бурса, Ізнік, Ізміт, Баликесір, Чанаккале, Берґама, Амасья, Токат, Чорлу, Люлебургаз, Малкара, Кешан, Іпсала, Кілітбахір, Чірмен, Стара Загора (Ескі Заґра), Татарпазарджик, Іхтіман, Кюстендил, Петрич, Неврокоп (Гоце Делчев), Драма, Галліполі, Чимпе, Едірне, Дімотіка, Киркларелі, Текірдаг, Пловдив, Софія, Ніш, Відін, Тирново, Варна, Шумен, Силістра, Нікополь, Русе, Салоніки, Серрес, Кавала, Скоп'є, Бітола, Охрид, Лариса (Єнішехір), Трикала, Ламія (Іздін), Плевен, Комотіні, Біга, Доманіч, Куладжахісар, Караджахісар, Ярхісар, Дімбос, Кіте (Кете), Лефке (Османелі), Леблебіджіхісар, Карачепюш, Каратігін, Абсу (Гіпсу), Адранос (Орханелі), Пелеканон (Ескіхісар), Ґебзе, Хереке, Самандира, Кірмасті (М. Кемальпаша), Міхаліч (Караджабей), Констанца, Ґьолязи (Аполлонія).", "d34e55d5"]},
"OLAYLAR:1413-07-05:0":{"b": ["Челебі Мехмед відновив єдність", "03413dfd"], "d": ["Мехмед I, перемігши Мусу Челебі під Чамурлу в останньому зведенні рахунків між братами, об'єднав землі країни під єдиною владою; тому його вважають «другим засновником держави». За його правління було відновлено розхитаний державний лад, врівноважено відносини з анатолійськими бейліками, а в Румелії провадилася обережна мирна політика. Інші поселення на карті, що тоді ж повернулися з періоду міжцарів'я під османське управління: Абсу (Гіпсу), Адранос (Орханелі), Акхісар (Памукова).", "45315d2d"]},
"OLAYLAR:1416-05-01:0":{"b": ["Повстання шейха Бедреддіна", "e0a072ca"], "d": ["Релігійно-суспільний рух, що розгорнувся навколо шейха Бедреддіна, великого правознавця та суфія, який під час міжцарів'я обіймав посаду казаскера, спалахнув одночасно з повстаннями Бьорклюдже Мустафи в Карабуруні та Торлака Кемаля в Манісі. Повстання криваво придушили; Бедреддіна схопили в Делі-Ормані та стратили в Серресі. Ця подія як найраніше велике суспільне й махдистське повстання в османській історії залишила глибокий слід у літературі та історіографії.", "1cf72ec4"]},
"OLAYLAR:1444-11-10:0":{"b": ["Перемога під Варною", "f739eedc"], "d": ["Угорсько-польське військо хрестоносців, яке, порушивши Сеґедський договір, вирушило на південь, знищив під Варною Мурад II, що після зречення престолу повернувся на чолі війська; молодий король Владислав III загинув на полі бою. Перемога усунула останній великий шанс зовнішнього втручання, спрямованого на ліквідацію османської присутності на Балканах, і убезпечила шлях до завоювання Константинополя.", "43adf0fb"]},
"OLAYLAR:1448-10-17:0":{"b": ["Друга Косовська битва", "ebe0b662"], "d": ["Військо Яноша Гуняді, який прагнув помститися за Варну, Мурад II остаточно розгромив у запеклій триденній битві. Це була остання велика польова битва хрестоносців проти османів на Балканах; завдяки перемозі османське панування на південь від Дунаю утвердилося вже незворотно.", "ea3ae23b"]},
"OLAYLAR:1453-05-29:0":{"b": ["Завоювання Константинополя", "583d5e3e"], "d": ["Після облоги, що тривала п'ятдесят чотири дні (6 квітня–29 травня 1453), уранці 29 травня османське військо подолало мури й увійшло в місто; останній імператор Костянтин XI загинув у боях, і Східна Римська імперія, що проіснувала 1100 років, відійшла в історію. Молодий султан прийняв титул «Фатіх» (Завойовник), зробив місто столицею і перетворив Святу Софію на мечеть; незабаром місто відродили заселенням і відбудовою. За TDV, Силіврі та Візе були остаточно завойовані лише 1453 року; за статтею TDV про Лемнос, острів перейшов під османське управління одразу після завоювання і був залишений родині Ґаттілузіо за умови сплати данини. В атласі Силіврі, Візе та Лемнос з цього дня позначені як такі, що перейшли від Візантії до османів (Лемнос — як данник). Відливання велетенських гармат, перетягування кораблів суходолом та облоговий лад перед мурами вважають вершиною тогочасної військової інженерії. В європейській історіографії це завоювання належить до символічних дат кінця Середньовіччя.", "d4b39486"]},
"OLAYLAR:1461-08-15:0":{"b": ["Завоювання Трапезунда", "15f52403"], "d": ["Наприкінці важкого чорноморського походу, який Фатіх вів одночасно силами війська й флоту, Трапезундська імперія здалася; з ліквідацією цього останнього уламка візантійського світу в Анатолії все південне узбережжя Чорного моря перейшло під османське панування. Припинення правління династії Комнінів зміцнило претензію Фатіха бути «володарем двох морів і двох суходолів». Інші місця, приєднані тоді ж: Ґіресун, Різе.", "ca6ead13"]},
"OLAYLAR:1473-01-01:0":{"b": ["Остаточне завоювання Силіфке — злам останнього опору Караманідів", "d988bee4"], "d": ["Фортеця Силіфке одного разу, 1472 року, здалася Ґедіку Ахмеду-паші, але того ж року караманський Касим-бей за допомоги флоту хрестоносців у Середземному морі повернув собі фортецю. Після перемоги при Отлукбелі Фатіх доручив своєму синові та Ґедіку Ахмеду-паші остаточно захопити край; за допомоги колишніх османських гармашів підпалили пороховий склад, і фортеця швидко впала. Так було зламано останній опір Караманідів у горах Ташелі-Ічель; ліквідацію бейліку буде завершено 1474 року.", "e9814184"]},
"OLAYLAR:1473-08-11:0":{"b": ["Битва при Отлукбелі", "42c7194e"], "d": ["Правитель Ак-Коюнлу Узун-Хасан, який став великою силою на Сході та уклав союз із Венецією, зазнав при Отлукбелі тяжкої поразки від озброєного вогнепальною зброєю війська Фатіха. Перемога остаточно закріпила османську перевагу в Анатолії; вона стала також раннім доказом переваги централізованого війська з гарматами й рушницями над класичним військом. За статтею TDV про Ґюмюшхане, місто від 1467 року перебувало під владою Ак-Коюнлу; ця влада скінчилася з поразкою при Отлукбелі, і Ґюмюшхане остаточно перейшло під османське панування.", "63e0811f"]},
"OLAYLAR:1475-06-06:0":{"b": ["Крим переходить під османський протекторат", "44e3f7c8"], "d": ["Флот під командуванням Ґедіка Ахмеда-паші завоював міста південного узбережжя Криму, насамперед Кафу, яка перебувала в руках генуезців; це узбережжя стало безпосередньо османським санджаком. Кримське ханство ж за Менґлі Ґерая стало привілейованою залежною державою, яка визнавала османський сюзеренітет, і впродовж трьох століть було наріжним каменем північної політики; Чорне море фактично перетворилося на внутрішнє море османів. Інші місця, приєднані тоді ж: Бахчисарай, Керч, Азов.", "a3448d71"]},
"OLAYLAR:1481-05-03:0":{"b": ["Смерть Фатіха — справа султана Джема", "190ecf01"], "d": ["Після раптової смерті Фатіха дорогою в похід на престол зійшов Баязид II; його брат султан Джем, претендуючи на султанат, наказав у Бурсі читати хутбу та карбувати монету на своє ім'я. Зазнавши поразки, він шукав притулку спершу в мамлюків, а потім у родоських лицарів; Джем, який у руках лицарів і папства став козирем у торгах європейської дипломатії, помер 1495 року в Неаполі. Ця справа змушувала османську зовнішню політику п'ятнадцять років діяти обережно.", "7e488d7b"]},
"OLAYLAR:1514-08-23:0":{"b": ["Чалдиранська перемога", "fea64ebb"], "d": ["Прагнучи в корені усунути загрозу, створену сефевідською пропагандою в Анатолії, султан Селім Явуз (Грізний) на Чалдиранській рівнині завдяки перевазі в гарматах і рушницях завдав тяжкої поразки війську шаха Ісмаїла. Османи вступили в Тебріз; Східну й Південно-Східну Анатолію та лінію Мосул—Діярбакир було приєднано до османського управління. Підпорядкування курдських беїв османам завдяки зусиллям Ідріса Бітлісі створило рамки східного кордону, що зберігалися століттями.", "67b03a64"]},
"OLAYLAR:1516-08-24:0":{"b": ["Перемога при Мардж-Дабіку", "07d254d3"], "d": ["Мамлюцьке військо було розбите за кілька годин при Мардж-Дабіку на північ від Алеппо; старий султан Кансух аль-Гаурі помер під час битви. Завдяки перемозі, що навстіж відчинила брами Алеппо й Дамаска, Сирія, Ліван і Палестина перейшли під османське управління; відкрився шлях до Єгипетського походу, який мав покласти край Мамлюцькій державі.", "c4b15f39"]},
"OLAYLAR:1517-01-22:0":{"b": ["Ріданія — завоювання Єгипту і халіфат", "caf378d6"], "d": ["Османське військо, швидко подолавши Синайську пустелю, прорвало оборонну лінію Туман-бея при Ріданії та вступило в Каїр; Туман-бея, який продовжував опір, схопили й стратили, а Мамлюцька держава відійшла в історію. Єгипет, Хіджаз і священні міста перейшли під османське управління; аббасидського халіфа та священні реліквії перевезли до Стамбула. З переходом халіфату до Османської династії султани взяли на себе претензію на провід ісламського світу; контроль над Шляхом прянощів також приніс імперії великі доходи. Інші місця, приєднані тоді ж: Акка, Маан, Сайда, Карак.", "a0cc8fdc"]},
"OLAYLAR:1520-09-30:0":{"b": ["Султан Сулейман Законодавець зійшов на престол", "f6512269"], "d": ["46-річне правління Сулеймана I, який після смерті Явуза зійшов на престол як його єдиний син чоловічої статі, вважають політичною, військовою, правовою та культурною вершиною імперії. Канун-наме, якими він систематизував звичаєве право, принесли йому титул «Кануні» (Законодавець); на Заході його називали «Пишним» (Magnificent). Символами цього періоду є твори архітектора Сінана, золота доба диванної літератури та перевага флоту в Середземному морі.", "cda7a2fb"]},
"OLAYLAR:1521-08-29:0":{"b": ["Завоювання Белграда", "59ef5cec"], "d": ["Белград, який Фатіх не зміг взяти 1456 року і який вважали «ключем до Центральної Європи», упав у першому поході Сулеймана Законодавця внаслідок облоги біля злиття Дунаю та Сави. Південна лінія оборони Угорщини завалилася; це завоювання відчинило двері для центральноєвропейської кампанії, що через п'ять років привела до Мохача, а через двадцять — до анексії Буди.", "69dbb7cc"]},
"OLAYLAR:1522-12-21:0":{"b": ["Завоювання Родосу", "807bbb1e"], "d": ["Родос, база лицарів-йоаннітів, які загрожували морським шляхам Східного Середземномор'я та шляху паломництва, після багатомісячної кривавої облоги здався на умовах капітуляції; лицарям дозволили вільно залишити острів (згодом вони осіли на Мальті). Безпеку анатолійського узбережжя було забезпечено, а морський шлях Стамбул—Єгипет перейшов під безперервний османський контроль.", "aeedfb16"]},
"OLAYLAR:1526-08-29:0":{"b": ["Битва під Мохачем", "f3418b0d"], "d": ["Угорське військо було знищене на Мохацькій рівнині приблизно за дві години гарматним вогнем і перевагою в маневрі; король Лайош II під час утечі загинув у болоті. Мохач, одна з найшвидше виграних великих польових битв в османській історії, фактично поклав край незалежному Угорському королівству й відкрив у Центральній Європі добу османо-габсбурзького суперництва.", "48967894"]},
"OLAYLAR:1529-09-27:0":{"b": ["Перша облога Відня", "dc49ea4f"], "d": ["У поході, організованому проти зазіхань Габсбургів на угорський престол, османське військо взяло в облогу Відень; через те, що важкі гармати довелося залишити в дорозі, ранню зиму та труднощі з постачанням облогу зняли через три тижні. Хоча місто взяти не вдалося, османський вплив в Угорщині зберігся; підступи до Відня позначили межу логістичної досяжності імперії в Центральній Європі.", "a49fc760"]},
"OLAYLAR:1534-12-04:0":{"b": ["Завоювання Багдада — похід на два Іраки", "897092c3"], "d": ["У поході на «два Іраки» (арабський Ірак і перський Ірак) османи спершу вступили в Тебріз, а потім без бою — в Багдад; взяття давньої столиці Аббасидів принесло османському правителю великий авторитет в ісламському світі. Було відновлено гробницю імама-і Азама Абу Ханіфи; з приєднанням Багдада й Басри османські землі сягнули Перської затоки. Інші місця, приєднані тоді ж: Кіркук, Кербела.", "f3f80434"]},
"OLAYLAR:1538-09-28:0":{"b": ["Морська перемога під Превезою", "30dc0f97"], "d": ["Флот хрестоносців, створений під проводом папи, попри чисельну перевагу, був розбитий поблизу Превези завдяки тактиці Барбароси, який майстерно використав вітер і узбережжя; Андреа Дорія залишив поле бою. Перемога встановила в Середземному морі незаперечну османську морську перевагу, що тривала близько 33 років; у турецькій морській традиції це символічна дата Дня флоту. Інші місця, приєднані тоді ж: Аден, Бендери.", "0411d92f"]},
"OLAYLAR:1541-08-29:0":{"b": ["Анексія Буди — Угорщина стає османською провінцією", "db53b244"], "d": ["Сулейман Законодавець, вирушивши в похід через габсбурзьку облогу Буди, визволив місто, а потім узяв Центральну Угорщину під пряме османське управління, заснувавши Будинський бейлербейлік; Трансильванію ж зробили автономним князівством, залежним від османів. Такий тричастинний устрій Угорщини тривав близько 150 років і становив постійний кістяк османського управління в Центральній Європі.", "1eb63e33"]},
"OLAYLAR:1555-05-29:0":{"b": ["Амасійський мир", "a5afe0d1"], "d": ["Це перший офіційний мирний договір, що завершив багаторічні османо-сефевідські війни. Багдад та Ірак залишилися за османами, кордон у Східній Анатолії вперше був взаємно визнаний; Сефевіди зобов'язалися припинити шиїтську пропаганду в османських володіннях, а османи — гарантувати безпечний прохід іранським паломникам. Договір став першим зразком правових рамок відносин між двома державами.", "220b198f"]},
"OLAYLAR:1566-09-07:0":{"b": ["Сігетвар — смерть Сулеймана Законодавця", "e2917ed2"], "d": ["72-річний Сулейман Законодавець помер у своєму шатрі за кілька годин до падіння фортеці Сігетвар, яку він обложив під час свого тринадцятого походу; Соколлу Мехмед-паша тижнями приховував смерть, щоб військо не розпалося. Фортецю взяли, але держава втратила свого найдовше правлячого й найблискучішого султана; на престол зійшов його син Селім II, і вага великих візирів в управлінні державою почала зростати.", "62c468a1"]},
"OLAYLAR:1571-08-01:0":{"b": ["Завоювання Кіпру", "e364a2b3"], "d": ["1570 року на Кіпрі, що перебував під венеційським управлінням, висадили десант; Нікосія впала швидко, а Фамагуста здалася лише після одинадцятимісячної облоги в серпні 1571 року. Острів, критично важливий для безпеки торговельних і паломницьких шляхів Східного Середземномор'я, організували як бейлербейлік і заселили людьми з Анатолії; це завоювання стало також приводом для великого союзу хрестоносців, що привів до Лепанто.", "6dcfdc0f"]},
"OLAYLAR:1571-10-07:0":{"b": ["Поразка під Лепанто", "6a1d44a9"], "d": ["Флот хрестоносців, об'єднаний після завоювання Кіпру, настиг османський флот у затоці Лепанто та знищив більшу його частину; капудан-паша (капудан-ї дер'я) Муезінзаде Алі-паша загинув як шахід, урятувалася лише ескадра Улуджа Алі. Після катастрофи великий візир Соколлу Мехмед-паша призначив Улуджа Алі-пашу капудан-пашею, доручивши йому зібрати розпорошений флот, і розпочав будівництво нового флоту на всіх верфях від Стамбула до Аланьї; проте абсолютна перевага в Середземному морі була психологічно підірвана.", "4cb5c93e"]},
"OLAYLAR:1596-10-26:0":{"b": ["Битва під Мезьокерестешем", "da308ec5"], "d": ["У найбільшій польовій битві Довгої війни (1593–1606) військо на чолі з самим Мехмедом III, опинившись на межі розпаду, згуртувалося завдяки умовлянням Ходжі Саадеддіна-ефенді й розгромило габсбурзьке військо. Її вважають останньою великою класичною польовою битвою, виграною османами; однак те, що вона не змінила загального перебігу війни, сприйняли також як ознаку зношеності військової системи.", "77f2a384"]},
"OLAYLAR:1606-11-11:0":{"b": ["Житваторокський мир", "39c01142"], "d": ["За договором, що завершив тринадцятирічну виснажливу війну, габсбурзького правителя вперше визнали рівним султанові з титулом «Римського імператора», а щорічну данину скасували. Територіальні втрати були майже нульові; проте ця зміна дипломатичної мови прочитується як символ кінця османської претензії на абсолютну перевагу над Європою.", "99a455e7"]},
"OLAYLAR:1639-05-17:0":{"b": ["Касрі-Ширінський договір", "c1acf3af"], "d": ["Договір, підписаний після того, як Мурад IV повернув Багдад (1638), поклав край османо-сефевідським війнам, що тривали понад сто років. Багдад та Ірак остаточно залишилися за османами, Реван було залишено Сефевідам; проведена лінія з незначними змінами стала основою нинішнього турецько-іранського кордону й вважається одним із найдовговічніших кордонів у світі. Договір залишив османам Бедре, Джессан, Менделі, Дертенг і Дерне; прикордонну фортецю Зенджір мали зруйнувати, села на захід від неї залишалися османам, а на схід — Ірану. Околиці фортеці Залім поблизу Шахрізора та Кизилджа-Кале залишилися за османами, Авроман і Міхрібан — за Іраном; фортеці Котур, Маку та Магазберд мали зруйнувати обидві сторони.", "c2d59f3f"]},
"OLAYLAR:1669-09-06:0":{"b": ["Завоювання Криту завершено", "e0d85604"], "d": ["Облога Кандії, остання дія Критської війни, що почалася 1645 року, завершилася завдяки рішучій трирічній операції Фазиля Ахмеда-паші; венеційський командувач Морозіні здав місто за договором. Боротьба, яка тривала близько чверті століття, увійшла в історію як найдовша облога в османській історії; остання велика латинська фортеця Східного Середземномор'я також перейшла під османське управління. Три невеликі скельні фортеці на північному узбережжі острова — Суда, Спіналонга та Грамвуса — ще залишалися за Венецією; оскільки вони збудовані на окремих острівцях, на карті їх неможливо показати окремо від решти Криту.", "314efa97"]},
"OLAYLAR:1672-10-18:0":{"b": ["Бучацький договір — найширші кордони", "b17b6e5a"], "d": ["За Бучацьким договором, підписаним після завоювання Кам'янця в польському поході, Поділля було приєднане до Османської держави, а частину України взято під протекторат. Так імперія досягла найширших своїх кордонів у Європі; цю точку вважають вершиною доби розширення й водночас її останньою ланкою.", "6d489670"]},
"OLAYLAR:1683-09-12:0":{"b": ["Розгром під час другої облоги Відня", "7d889252"], "d": ["Двомісячна облога Відня Мерзіфонлу Карою Мустафою-пашею обернулася розгромом через раптовий удар, якого завдав із висот Каленберґа польський король Ян Собеський; військо відступило, покинувши обози, а Мерзіфонлу стратили в Белграді. Війна зі Священною лігою, створеною після цієї перемоги, тривала 16 років; цей розгром називають моментом початку великого занепаду в османській історії.", "88ceb19f"]},
"OLAYLAR:1692-01-01:0":{"b": ["Завоювання фортеці Грамвуса — однієї зі скельних фортець Криту, що залишалися за Венецією", "3ddf9eeb"], "d": ["Хоча зі здачею Кандії 1669 року завоювання Криту вважали здебільшого завершеним, скельна острівна фортеця Грамвуса на північно-західному краю острова ще двадцять три роки залишалася в руках Венеції. Зі взяттям її 1692 року було ліквідовано один із трьох венеційських залишків на Криті; Суда та Спіналонга чекатимуть Морейського походу 1715 року.", "05e94fe9"]},
"OLAYLAR:1699-01-26:0":{"b": ["Карловицький мир — перша велика територіальна втрата", "8f7e2546"], "d": ["За Карловицьким миром, що завершив шістнадцятирічні війни Священної ліги, Угорщина й Трансильванія відійшли Австрії, Поділля — Польщі, Морея та далматинське узбережжя — Венеції. Уперше в османській історії землі такого масштабу втрачалися за столом переговорів і назавжди; договір вважають вихідним документом нової доби, коли імперія перейшла до оборони перед Європою, і він є також переломним моментом в історії османської дипломатії. Поселення, що того ж дня змінили власника в атласі: Костайниця та Ясеновац (від османів до Габсбургів; текст договору залишає Castanoviz у руках імператора, дня передання Ясеноваца в джерелі немає, записано день договору) та Превеза (від Венеції до османів; TDV karlofca: згідно з положенням, підписаним 24 раджаба 1110 / 26 січня 1699 року, венеційські окуповані місця на північ від затоки Лепанто було повернено). Крім того, атлас записує Костайницю та Ясеновац на габсбурзький бік, Умань і Вінницю на Правобережній Україні — від османів до Польщі (TDV merzifonlu-kara-mustafa-pasa; IEU Vinnytsia: турецька влада 1672-99), а Надін у Далмації — Венеції (дня передання саме цього поселення в джерелі немає, записано день договору; межі періоду Надіна не перевірені за джерелом — задекларована приблизність). Вониця на північ від затоки Лепанто також повертається від Венеції османам (TDV karlofca); у Далмації Врана (Урана) серед місць, що залишаються за Венецією (межу періоду не перевірено — задекларовано).", "0909e24e"]},
"OLAYLAR:1711-07-19:0":{"b": ["Прутська перемога", "2583572f"], "d": ["У війні, що спалахнула через справу шведського короля, який після поразки під Полтавою знайшов притулок в османів, військо царя Петра I було оточене на березі Пруту й змушене здатися. За підписаним договором було повернуто Азов; рішення ж не знищувати військо й відпустити царя увійшло в історію як таке, про яке сперечаються й донині.", "ce9c2996"]},
"OLAYLAR:1715-01-01:0":{"b": ["Завоювання фортець Суда та Спіналонга — стирання останнього венеційського сліду на Криті", "7261f7ba"], "d": ["Через двадцять три роки після падіння Грамвуси 1692 року в межах одного з відгалужень Морейського походу завоювали також фортеці Суда та Спіналонга — два останні опорні пункти Венеції на Криті. Так завоювання Криту, розпочате 1645 року, через сорок шість років було завершене до останнього клаптика острова.", "d2044cae"]},
"OLAYLAR:1730-09-25:0":{"b": ["Повстання Патрони Халіля", "100941a4"], "d": ["Невдачі на іранському фронті, податки та гнів на розкіш палацового оточення переросли у велике повстання під проводом лазневого банщика Патрони Халіля. Великого візира Ібрагіма-пашу вбили, Ахмеда III скинули з престолу, і Доба тюльпанів скінчилася; те, що повстанці місяцями панували в місті, разюче показало крихкість центральної влади.", "d87eea77"]},
"OLAYLAR:1739-09-18:0":{"b": ["Белградський мир — повернення Белграда, Смедерева та північної Сербії", "ba7f8e46"], "d": ["Наприкінці війни (1736–1739), яку вели на два фронти проти Австрії та Росії, було повернуто Белград і Північну Сербію; Росія погодилася демілітаризувати Азов і не тримати флоту на Чорному морі. Договір, який вважають останнім великим успіхом османської дипломатії та війська XVIII століття, подарував імперії чверть століття миру. Інші поселення, що того ж дня в атласі повертаються від Австрії османам: Хісарджик (Ґроцка) (ланцюг головного центру Белграда; TDV belgrad), Крайова, Римніку-Вилча та Турну-Северін (повернення Малої Волощини османам, у волоський васалітет). Босанський Брод і Босанська Дубиця в смузі вздовж Сави в атласі повертаються османам 28 вересня 1739 року (TDV bosna-hersek; TDV mahmud-i--osmanli: 28 вересня 1739). Тиргу-Жіу в Малій Волощині також того ж дня повертається османам.", "118d49db"]},
"OLAYLAR:1770-07-06:0":{"b": ["Чесменський погром", "840b30bd"], "d": ["Російський флот, що за британської підтримки вийшов у Середземне море, напав брандерами на османський флот у Чесменській гавані, де той укрився, і спалив його майже вщент. Росія вперше постала в Середземному морі як велика морська сила; ця катастрофа стала одним з ударів, що визначили долю війни, яка привела до Кючук-Кайнарджі 1774 року, і виявила потребу докорінної реформи флоту.", "5b133a56"]},
"OLAYLAR:1774-07-21:0":{"b": ["Кючук-Кайнарджійський мир", "2776dcdb"], "d": ["За Кючук-Кайнарджійським миром, що завершив війну 1768–1774 років і вважається одним із найтяжчих договорів в османській історії, Кримському ханству надали «незалежність» — фактично створивши сферу російського впливу. Росія утвердилася на чорноморському узбережжі, здобула для торгових суден право проходу через Протоки та постійне посольство в Стамбулі; туманне положення про протекцію над православними підданими прочинило двері приводам для втручання в наступному столітті. Уперше з-під османської влади виводили землю з мусульманським населенням.", "b677ebfc"]},
"OLAYLAR:1783-04-19:0":{"b": ["Анексія Криму Росією", "bdf6faa8"], "d": ["«Незалежний» Крим, створений Кючук-Кайнарджійським миром, анексувала Росія маніфестом Катерини II, скориставшись як приводом заворушеннями за останнього хана Шагіна Ґерая. Трьохсотлітнє османо-кримське партнерство скінчилося; втрата північних степів позбавила Стамбул стратегічної глибини оборони й спричинила першу велику хвилю переселення десятків тисяч кримських татар в османські землі. Цього дня Кримський півострів (Алушта, Кафа, Судак, Ялта, Балаклава, Інкерман, Мангуп, Арабат) приєднано до Росії; Тамань і Кубань також перейшли до Росії тією самою анексією (TDV, стаття «Крим»: 8 квітня 1783 за юліанським = 19 квітня за григоріанським календарем).", "aa59d3e1"]},
"OLAYLAR:1789-04-07:0":{"b": ["Селім III і Нізам-і Джедід", "d53aec21"], "d": ["Селім III, який зійшов на престол у розпал війни, зрозумівши, що поразки мають структурний характер, започаткував під назвою «Нізам-і Джедід» (Новий порядок) широку програму реформ: нове військо, вишколене за європейським зразком, окрему скарбницю для його фінансування (Ірад-і Джедід), зміцнення інженерних шкіл і перші постійні посольства в європейських столицях. Цю програму вважають початком модерної турецької реформаторської традиції; однак через опір військових корпусів та аянів 1807 року вона була повалена.", "87394990"]},
"OLAYLAR:1798-06-12:0":{"b": ["Ліквідація мальтійських лицарів — зупинка французького флоту дорогою", "d62f901d"], "d": ["Французький флот, що плив до Єгипту, дорогою зайшов на Мальту; лицарі святого Іоанна (мальтійські) здали острів без особливого опору. Так перестав існувати останній оплот лицарського ордену, вигнаного 1522 року з Родосу й осілого тут. Через два роки Мальта опиниться в руках британців, а Наполеон з острова вирушив просто до Александрії.", "aac1fe49"]},
"OLAYLAR:1798-07-01:0":{"b": ["Наполеонівське вторгнення до Єгипту", "93fede5f"], "d": ["Армія генерала Бонапарта висадилася в Александрії й окупувала Єгипет; цей похід, спрямований проти британського шляху до Індії, став першим прямим нападом європейської держави на центральні землі османів. Напад Нельсона під Абукіром та оборона Акки Джеззаром Ахмедом-пашею зламали французький наступ; окупація скінчилася 1801 року, але у вакуумі, який вона залишила, почалися піднесення Мехмеда Алі-паші з Кавали та доба «Східного питання».", "b1ca7226"]},
"OLAYLAR:1808-10-07:0":{"b": ["Сенед-і Іттіфак (Союзна грамота)", "cce49ef5"], "d": ["Документ, підписаний між палацом і могутніми провінційними родинами аянів за ініціативою Алемдара Мустафи-паші, аяна Рущука, який посадив на престол Махмуда II; аяни зобов'язувалися бути вірними султанові та надавати військову підтримку, а держава визнавала їхнє існування та права. Оскільки це був перший в османській історії приклад обмеження влади султана документом, деякі історики вважають його далеким початком конституційної традиції; фактично за кілька місяців він втратив чинність.", "2d97fdfe"]},
"OLAYLAR:1821-03-06:0":{"b": ["Почалося Грецьке повстання", "a7293715"], "d": ["Повстання, підготоване організацією «Філікі Етерія», спалахнуло спершу у Волощині, а потім головними силами — в Мореї; держава, зайнята клопотом з Алі-пашею Тепеленським, із першою реакцією запізнилася. Завдяки палким симпатіям до греків у європейській громадській думці (філеллінізму) повстання швидко перетворилося на міжнародну справу; так було запалено ґніт першого на османських землях успішного руху за незалежність доби націоналізму. Інші поселення, втрачені тоді ж: Афіни, Патри (Бальябадра), Фіви, Лівадія, Елевсін (Аттика), Месолонгіон.", "f11097ac"]},
"OLAYLAR:1821-04-02:0":{"b": ["Перше збройне повстання в Мореї", "77e6250f"], "d": ["Після переправи через Прут повстання перекинулося на Морею: за збройним виступом, що почався в Калавриті (21 березня за юліанським календарем), відбулися рухи в Патрах, Каламаті та Мані; Морея швидко перетворилася на осередок загального повстання, і османська адміністрація втратила більшу частину півострова. Інші поселення, втрачені тоді ж: Афіни, Патри (Бальябадра), Фіви, Лівадія, Елевсін (Аттика), Месолонгіон.", "143953b8"]},
"OLAYLAR:1826-06-15:0":{"b": ["Вак'а-і Хайрійє — скасування яничарського корпусу", "08c9372a"], "d": ["Яничарів, які перекинули казани на знак бунту проти вишколу новоствореного корпусу ешкінджі, було знищено гарматним вогнем заздалегідь підготованих Махмудом II вірних частин у їхніх казармах на Етмейдани; корпус скасували разом з усіма його підрозділами та пов'язаними з ним бекташійськими текіє. Ця операція, що увійшла в історію під назвою, яка означає «Щаслива подія», ліквідувавши чотиристолітню установу, відкрила шлях війську Асакір-і Мансуре-і Мухаммедійє та всім подальшим централізаторським реформам.", "9ee152dd"]},
"OLAYLAR:1827-10-20:0":{"b": ["Наваринський погром", "ee579e7f"], "d": ["Османо-єгипетський флот, який придушував грецьке повстання, спалила в Наварині об'єднана англо-франко-російська ескадра, що увійшла в гавань без оголошення війни; було втрачено майже шістдесят кораблів і тисячі моряків. Цей напад, який європейська дипломатія відмахнула як «прикрий інцидент», фактично гарантував незалежність Греції та відкрив шлях до османо-російської війни 1828–29 років.", "0d4b2c6f"]},
"OLAYLAR:1839-11-03:0":{"b": ["Ферман Танзімату", "5042ce7b"], "d": ["Хатт-і Хумаюном, зачитаним у Ґюльхане, держава взяла під гарантію безпеку життя, майна й честі всіх підданих незалежно від віри; було проголошено принципи справедливості в оподаткуванні, ладу у військовій службі та неможливості покарання без суду. Ферман, витвір Мустафи Решида-паші, вважають першим великим документом османської модернізації конституційного характеру, і він дав назву добі реформ — «Танзімат» (1839–1876); у цих рамках проводилася докорінна перебудова управління, права, освіти та фінансів.", "6ace4b82"]},
"OLAYLAR:1853-10-04:0":{"b": ["Почалася Кримська війна", "3b9ca3c8"], "d": ["Криза, що почалася з питання про святі місця та претензії Росії на протекцію над православними підданими, з оголошенням війни османами перейшла у відкритий конфлікт; після Синопського погрому на боці османів у війну вступили Британія та Франція (пізніше П'ємонт). Після висадки союзних армій у Криму та взяття Севастополя війну було виграно Паризьким договором 1856 року; проте перша зовнішня позика, взята в роки війни (1854), втягнула імперію в спіраль фінансової залежності, що тривала пів століття.", "bae16135"]},
"OLAYLAR:1856-02-18:0":{"b": ["Ферман про реформи (Іслахат Фермани)", "78ff234d"], "d": ["Ферман, проголошений перед Паризькими мирними переговорами, розширив принципи Танзімату й надав немусульманським підданим широкі права рівності, зокрема на державну службу, військову службу та відкриття шкіл; було перебудовано організацію релігійних громад. За Паризьким договором, підписаним згодом, Османську державу офіційно прийняли до сім'ї європейського міжнародного права, а її територіальну цілісність поставили під спільну гарантію великих держав — гарантію, яка на практиці стане новими дверима для втручань.", "cfe6d847"]},
"OLAYLAR:1876-12-23:0":{"b": ["Канун-і Есасі — Перша конституційна доба", "0fe052c1"], "d": ["У день відкриття міжнародної конференції, що зібралася в Стамбулі для обговорення Балканської кризи, під гарматний салют проголосили першу османську конституцію; Канун-і Есасі, витвір руху «Нових османів» на чолі з Мідхатом-пашею, запроваджував двопалатний парламент. Меджліс-і Мебусан відкрився в березні 1877 року; однак Абдул-Гамід II, посилаючись на Війну 93-го року, у лютому 1878 року на невизначений строк припинив засідання парламенту, і конституція тридцять років залишалася призупиненою.", "c0f01a41"]},
"OLAYLAR:1877-04-24:0":{"b": ["Війна 93-го року (османо-російська війна 1877–78)", "5bd96af7"], "d": ["У війні, яку називають «Війною 93-го року», оскільки вона припала на 1293 рік за румійським календарем, російські армії наступали на двох фронтах; хоч оборона Плевни Ґазі Османом-пашею та кавказькі битви Ахмеда Мухтара-паші стали легендами, фронт обвалився, і росіяни дійшли аж до Єшількьоя (Сан-Стефано). Війна спричинила великі хвилі переселення мусульман із Балкан і Кавказу в напрямку Стамбула, наслідки яких відчутні донині; демографічна та фінансова структура імперії вже ніколи не змогла повернутися до попереднього стану.", "3a2b2296"]},
"OLAYLAR:1878-07-13:0":{"b": ["Берлінський трактат", "47f76a49"], "d": ["Берлінський конгрес, який в ім'я рівноваги великих держав переглянув створену в Сан-Стефано «Велику Болгарію», все ж залишив тяжку картину: Сербія, Чорногорія та Румунія стали незалежними; було створено автономне Болгарське князівство; Боснію і Герцеговину віддали під австрійську окупацію, Кіпр — під британське управління, а Карс, Ардаган і Батум — Росії. П'ятсотлітній османський лад у Румелії значною мірою розпався; «східне питання» стало постійним пунктом порядку денного європейської дипломатії. Інші поселення, втрачені тоді ж: Пловдив, Відін, Тирново, Варна, Шумен, Силістра, Русе, Бухарест, Ясси, Констанца. Румунія в обмін на передання Бессарабії Росії отримала Тулчу та Добруджу: Тулча, Бабадаг, Мечин, Ісакча, Хиршова та Мангалія в Північній Добруджі перейшли до Румунії.", "5c7d5594"]},
"OLAYLAR:1881-05-12:0":{"b": ["Окупація Тунісу та Управління Османського державного боргу", "c7e25598"], "d": ["Скориставшись як приводом інцидентами на алжирському кордоні, Франція окупувала Туніс і за договором у Бардо взяла його під свій протекторат; османська присутність у Північній Африці звелася до Триполітанії. Виданим того ж року Мухарремським декретом для управління зовнішніми боргами, що збанкрутували, було створено Управління Османського державного боргу (Дююн-і Умумійє), в якому були представлені кредитори: основні доходи, як-от сіль, тютюн і шовк, були прямо підпорядковані цій іноземній адміністрації, а фінансовий суверенітет тяжко обмежено. Інші поселення, втрачені тоді ж: Кайруан, Габес, Сфакс, Джерба.", "64f23b86"]},
"OLAYLAR:1882-09-13:0":{"b": ["Британська окупація Єгипту", "f1269768"], "d": ["Рух Урабі-паші, що піднявся в Єгипті проти фінансового банкрутства та іноземного контролю, британська армія, яка висадилася після бомбардування Александрії, розгромила в переможній битві при Тель-ель-Кебірі, і Каїр було окуповано. Хоча юридично Єгипет і далі залишався пов'язаним з Османською державою, фактично він перейшов під британське управління; контроль над Суецьким каналом став осердям британської імперської стратегії.", "b7bcf2d2"]},
"OLAYLAR:1908-07-23:0":{"b": ["Проголошення Другої конституційної доби", "95ee2fd2"], "d": ["Перед рухом, що розрісся після того, як офіцери, пов'язані з комітетом «Єднання і поступ», пішли в гори в Македонії, Абдул-Гамід II відновив дію Канун-і Есасі; «проголошення свободи» зустріли з захватом, і було проведено вибори. Однак стабільність не настала: після придушення подій 31 березня (квітень 1909) Абдул-Гаміда скинули з престолу; у ці ж бурхливі місяці сталися проголошення незалежності Болгарії, анексія Боснії та поворот Криту до Греції.", "370f359f"]},
"OLAYLAR:1911-09-29:0":{"b": ["Триполітанська війна", "ed441994"], "d": ["Італія, шукаючи колоній, оголосила війну Триполітанії, останній османській землі в Північній Африці, і окупувала узбережжя; оскільки держава без флоту не могла надіслати регулярні війська, молоді офіцери, як-от Мустафа Кемаль та Енвер-бей, таємно пробралися в цей край і разом із сенуситськими племенами організували дієвий опір. За Ушійським договором, підписаним після вибуху Балканської війни (18 жовтня 1912), Лівію віддали Італії; крім того, Італія окупувала Родос і Додеканес.", "9820482a"]},
"OLAYLAR:1913-05-30:0":{"b": ["Лондонський договір — втрата Румелії", "f3f976df"], "d": ["За Лондонським договором, що завершив Першу балканську війну, було втрачено всі землі на захід від лінії Мідьє—Енез та егейські острови; Албанія стала незалежною. Від Румелії, яка понад п'ятсот років була демографічним, економічним і культурним центром ваги імперії, залишалася тільки Східна Фракія (Едірне повернули у Другій балканській війні); ця втрата докорінно посилила жорсткість воєнної та переселенської політики уряду йоніністів. Було втрачено такі місця на захід від лінії Мідьє—Енез: Скоп'є, Велес, Штип, Струмиця, Дойран, Гевгелія, Бітола, Охрид, Дебар (Дібра), Призрен, Приштина, Печ (Пея), Нові-Пазар, Косово Поле; Серрес, Драма, Кавала, Петрич, Неврокоп, Ксанті, Комотіні, Дедеагач, Дідімотіхо, Чірмен, Ферес, Софлі, Орестіада (Кумчіфтлігі), Правіште (Елефтеруполіс), Стерна, Таврі, Умур-Факіх (Факія), Малак-Дервент (Лалково); на Криті — Ханья, Кандія, Ретимно, Сітія та Сфакія.", "b193bdae"]},
"OLAYLAR:1914-11-01:0":{"b": ["Вступ у Першу світову війну", "05a0252e"], "d": ["Те, що лінійні кораблі «Ґебен» і «Бреслау», які втекли від британців, впустили через Протоки, видавши їх за куплені, крок за кроком втягувало державу на бік Німеччини; після того як флот під командуванням адмірала Сушона обстріляв російські порти (29 жовтня), війна фактично почалася, а взаємні оголошення надійшли на початку листопада. Попри проголошення Великого джихаду (Джихад-і Екбер), очікуваного ефекту не виникло; чотири роки імперія вела боротьбу за існування на п'яти окремих фронтах — від Кавказу до Палестини.", "a9f179e7"]},
"OLAYLAR:1915-03-18:0":{"b": ["Перемога під Чанаккале", "95d888e8"], "d": ["Армаду союзників, що мала на меті захопити Стамбул і дістатися до Росії, 18 березня відкинули від Проток вогонь мінних загороджень і фортів; лінія мін, поставлена мінним загороджувачем «Нусрет», визначила долю битви. Сухопутну Галліпольську операцію, що почалася в квітні, також зупинили під Анафарталаром і на Чонк-Баїрі; у січні 1916 року союзники повністю евакуювали півострів. На цьому фронті пролунало ім'я підполковника Мустафи Кемаля; перемогу, здобуту ціною близько чверті мільйона загиблих за віру та інших втрат, вважають місцем, де народилися кадри й дух Національної боротьби.", "005303c3"]},
"OLAYLAR:1916-06-10:0":{"b": ["Повстання шарифа Хусейна", "75f7c58c"], "d": ["Мекканський емір шариф Хусейн після таємного листування з британцями повстав під обіцянку незалежного арабського королівства; Хіджазька залізниця стала мішенню нападів. Хоч легендарна оборона Медини Фахреддіном-пашею, що тривала навіть після перемир'я, залишилася символом опору, повстання, поєднавшись із британським наступом на Палестинському фронті, прискорило розпад османського панування в арабських вілаєтах. Інші поселення, втрачені тоді ж: Хурма, Тураба.", "f7c6b3e9"]},
"OLAYLAR:1918-10-30:0":{"b": ["Мудроське перемир'я", "9e87c767"], "d": ["Османська держава, фронти якої через крах Болгарії виявилися відірваними один від одного, вийшла з війни за перемир'ям, підписаним на борту лінкора «Агамемнон». Відкриття Проток і особливо 7-ма стаття, яка давала змогу окупувати місця, де є загроза безпеці, незабаром стали юридичним прикриттям фактичного поділу: було окуповано Мосул, Александретту, а потім Ізмір і Стамбул. Перемир'я вважають документом фактичного кінця імперії. Інші поселення, втрачені тоді ж: Хама, Дамаск, Хомс.", "261b57f2"]},
"OLAYLAR:1919-05-19:0":{"b": ["Мустафа Кемаль у Самсуні — Національна боротьба", "09a8f784"], "d": ["В атмосфері обурення, спричиненого окупацією Ізміра, Мустафа Кемаль-паша, який висадився в Самсуні на посаді інспектора 9-ї армії, обернув свої офіційні обов'язки на організацію опору в Анатолії. Амасійський циркуляр та Ерзурумський і Сіваський конгреси стали продовженням цього виступу; принцип «незалежність нації врятують лише рішучість і воля самої нації» став ядром політичної програми Національної боротьби.", "330e4c51"]},
"OLAYLAR:1920-04-23:0":{"b": ["Відкриття Великих національних зборів Туреччини та Севр", "2008feec"], "d": ["Після офіційної окупації Стамбула та розгону Меджлісу-і Мебусан 23 квітня 1920 року в Анкарі відкрилися Великі національні збори; зібрання, яке зосередило в собі надзвичайні повноваження, стало ядром нової держави, що спиралася на національну волю. Севрський договір, підписаний у серпні стамбульським урядом, ділив Анатолію; Великі національні збори оголосили тих, хто підписав договір, зрадниками батьківщини, і Севр так і не був втілений.", "9b4f7c0b"]},
"OLAYLAR:1921-09-13:0":{"b": ["Битва на Сакарії", "f2f970a6"], "d": ["Грецький наступ, що наблизився до Анкари на 50 кілометрів, було зламано в битві, яка тривала 22 дні й 22 ночі й велася за наказом Мустафи Кемаля-паші, що перебрав повноваження головнокомандувача: «Немає лінії оборони, є поверхня оборони». Грецька армія вперше перейшла до стратегічної оборони; перемога принесла Мустафі Кемалю звання гази та чин маршала (мюшира) й відчинила двері Анкарській угоді з Францією та міжнародному визнанню.", "f3372310"]},
"OLAYLAR:1922-09-09:0":{"b": ["Великий наступ і визволення Ізміра", "172a50c4"], "d": ["Наступ, розпочатий уранці 26 серпня з Коджатепе, 30 серпня під Думлупинаром у Битві головнокомандувача привів до знищення головних грецьких сил; під час переслідування, що тривало за наказом «Арміє, твоя перша мета — Середземне море, вперед!», 9 вересня визволили Ізмір. За Муданійським перемир'ям (11 жовтня) Східну Фракію повернули без бою; військова перемога визначила силу за столом переговорів нової держави, яку мали утворити в Лозанні.", "02bd94a5"]},
"OLAYLAR:1922-11-01:0":{"b": ["Скасування султанату", "9f36a9f6"], "d": ["Коли на Лозаннські переговори запросили й стамбульський уряд, Великі національні збори 1 листопада 1922 року відокремили султанат від халіфату й скасували султанат; 623-річне правління Османської династії юридично скінчилося. Мехмед VI Вахідеддін 17 листопада залишив країну на борту британського лінкора; на посаду халіфа за рішенням Великих національних зборів поставили Абдул-Меджида-ефенді, а цю посаду також буде скасовано 3 березня 1924 року.", "910b763d"]},
"OLAYLAR:1923-07-24:0":{"b": ["Лозаннський договір", "38c27f7d"], "d": ["За Лозаннським мирним договором, підписаним після восьми місяців важких переговорів, кордони, повна незалежність і суверенітет нової турецької держави дістали міжнародне визнання; капітуляції було скасовано, Управління Османського державного боргу введено в процес ліквідації, врегульовано обмін населенням. Лозанну, яка фактично зробила Севр нікчемним, вважають дипломатичною перемогою Національної боротьби та засадничим зовнішнім документом Республіки.", "6d498c3f"]},
"OLAYLAR:1923-10-29:0":{"b": ["Проголошення Республіки", "d5bfcdfb"], "d": ["Республіку було проголошено, коли Великі національні збори конституційною поправкою ухвалили положення: «Форма правління Турецької держави — республіка»; Мустафу Кемаля-пашу обрали першим президентом. Так завершилася 624-річна османська епопея, що почалася 1299 року як прикордонний бейлік, а на спадщині імперії постала нова держава, у якій суверенітет безумовно належить нації.", "f5cabb8c"]},
"OLAYLAR_2S0920:0224-04-28:0":{"b": ["Битва при Ормізгані: Ардашир переміг парфянського царя Артабана V — Ісфаган увійшов до сасанідського ядра", "3689fd45"], "d": ["Місцевий правитель Парсу Ардашир при Ормізгані переміг парфянського царя Артабана V; парфянська (Аршакідська) династія впала, а піднеслася династія Сасанідів. Атлас від цього дня вважає Ісфаган сасанідською землею.", "3551fe9f"]},
"OLAYLAR_2S0920:1387-05-08:0":{"b": ["Караферьє (Верія) перейшла під османську владу", "b0ece3f3"], "d": ["Того самого 1387 року, коли здалися Салоніки, під османську владу перейшла й Караферьє у внутрішній частині Нижньої Македонії. Місто було вузловим пунктом дороги між Салоніками та Фессалією.", "4e571f7b"]},
"OLAYLAR_2S0920:1506-07-08:0":{"b": ["Альбрехт IV видав Віттельсбахський статут про первородство — баварські герцогства об'єдналися в одне неподільне герцогство", "86ee6f77"], "d": ["Після війни за Ландсгутську спадщину (1503-1505) герцог Альбрехт IV, який знову зібрав баварські герцогства в одних руках, 8 липня 1506 року видав статут про первородство, що передбачав неподільність країни та перехід престолу до найстаршого сина. Так закінчилися поділи Баварії, які тривали з 1255 року; Баварія з центром у Мюнхені й далі існувала серед німецьких держав як єдине неподільне герцогство.", "26058158"]},
"OLAYLAR_2S0920:1517-04-15:0":{"b": ["Амір II загинув поблизу Сани — кінець династії Тахіридів", "713ae406"], "d": ["Останній правитель Тахіридів Амір II у війні, що почалася через зіпсовані відносини з мамлюцьким флотом, коли єменські племена та зейдити підтримали мамлюків, спершу зазнав поразки поблизу Забіда (листопад 1516 року), а потім загинув у бою поблизу Сани. Так припинила існування династія Тахіридів, яка правила Єменом з 1454 року; міста династії (зокрема Таїз) більше не підпорядковувалися владі Тахіридів.", "4b9725ef"]},
"OLAYLAR_2S0920:1552-08-01:0":{"b": ["Завоювання фортець Лугож і Карансебеш — продовження темешварського походу", "1af5a2be"], "d": ["Фортеця Темешвар здалася 26 липня 1552 року після тритижневого опору. У серпні взяли також фортеці Лугож і Карансебеш; уздовж долини Муреша захопили п'ятнадцять фортець і утворили новий бейлербейлік із центром у Темешварі.", "ecd1e532"]},
"OLAYLAR_2S0920:1723-11-18:0":{"b": ["Засновано Єкатеринбурзький залізоробний завод-фортецю — центр уральського гірничого краю", "c416e12e"], "d": ["На обраному Татіщевим місці на річці Ісеть запрацювали молотові стани залізоробного заводу, будівництво якого завершив де Геннін; Єкатеринбург відлічує свою історію від цього дня. Поселення, яке мало стати центром уральського гірничого й залізного краю, стало брамою Московського царства на сибірський шлях.", "8d081bcf"]},
"OLAYLAR_2S0920:1902-03-01:0":{"b": ["Зарія (Заззау) перейшла під британський адміністративний контроль — зарійський емірат халіфату Сокото приєднано до протекторату Північна Нігерія", "c2e4131e"], "d": ["Підпорядкований халіфату Сокото зарійський емірат у березні 1902 року взяли під британське управління Північної Нігерії; британці розмістили в Зарії резидента й гарнізон. Емір Квасау здався в липні 1902 року, а у вересні його усунули з посади.", "d2ce29e8"]},
"OLAYLAR_2S0920:1903-02-01:0":{"b": ["Британці взяли Кано — найбільший емірат халіфату Сокото перейшов до протекторату Північна Нігерія", "0484009d"], "d": ["Загін полковника Морленда, підлеглого верховного комісара Північної Нігерії Лугарда, вирушив із Зарії та в лютому 1903 року захопив Кано; підпорядкований халіфату Сокото емірат Кано перейшов під британське управління. Сокото взяли через місяць, 15 березня 1903 року.", "33350275"]},
"OLAYLAR_2S0920:1912-10-22:0":{"b": ["Приштина переходить до рук сербської армії", "2ef111c0"], "d": ["Сербська армія, увійшовши в Косово під час Першої Балканської війни, взяла Приштину, і в місті почалася політика повторної сербізації. Падіння Приштини — одна з перших ланок розпаду османського опору в Косовському вілаєті.", "96fc25ba"]},
"OLAYLAR_2S0920:1912-11-18:0":{"b": ["Окупація Монастира (Бітоли) сербськими силами", "db9b3353"], "d": ["Під час Першої Балканської війни Монастир, один із найважливіших адміністративних і військових центрів Македонії, після п'ятиденних боїв перейшов до рук сербських сил. Втрата міста означала фактичне припинення присутності Османської держави в Македонії.", "84736d79"]},
"OLAYLAR_2S0920:1912-11-28:0":{"b": ["Проголошення незалежності Албанії — Ісмаїл Кемалі у Влорі", "2cdbd4d9"], "d": ["Коли армії Балканської війни входили в албанські вілаєти, Ісмаїл Кемалі проголосив у Влорі незалежність Албанії. Так прибережна та внутрішня смуга, що простягалася від Дурреса, Ельбасана, Берата, Гірокастри та Круї до Саранди, вийшла з-під османського управління й утворила ядро нової албанської держави.", "bc8dc97c"]},
"OLAYLAR_2S0920:1912-11-29:0":{"b": ["Кінець османської влади в Охриді та Дебарі", "5273f1ec"], "d": ["Через одинадцять днів після падіння Монастира сербська армія увійшла в озерний край Західної Македонії; в Охриді припинилася п'ятсотрічна османська влада, а Дебар на півночі також було втрачено під час тієї самої операції.", "7cabdd2f"]},
"OLAYLAR_2S0920:1913-04-23:0":{"b": ["Окупація Шкодера чорногорцями", "db704247"], "d": ["Одна з найдовших облог Першої Балканської війни відбулася під Шкодером; після багатомісячного опору місто залишили чорногорським силам. Шкодер був однією з останніх османських фортець, що протрималися до кінця війни.", "418ed9d4"]},
"OLAYLAR_2S0920:1913-05-14:0":{"b": ["Чорногорія залишила Шкодер; у місто увійшов міжнародний корпус великих держав", "8a6593e9"], "d": ["Під тиском великих держав Чорногорія 14 травня 1913 року залишила Шкодер, який узяла 23 квітня 1913 року; у місто увійшов міжнародний корпус, і воно стало частиною установчої адміністрації Албанії.", "5ef15370"]},
"OLAYLAR_2S0920:1913-07-08:0":{"b": ["Ібн Сауд узяв Ахсу — кінець османської влади на узбережжі Перської затоки", "505f26d5"], "d": ["Емір Неджду Абдул-Азіз ібн Сауд, вигнавши османський гарнізон, захопив область Ахса й оселився в її центрі Хуфуфі. Разом із пристанями Катіф та Укайр західне узбережжя затоки перейшло під управління Саудів; п'ятдесятирічне управління Османської держави в області припинилося.", "8ec53ab2"]},
"OLAYLAR_2S0920:1913-08-10:0":{"b": ["Бухарестський договір — Західна Фракія та басейн Кавали перейшли від Болгарії до Греції", "56123a58"], "d": ["Друга Балканська війна завершилася Бухарестським договором, підписаним між Болгарією та Сербією, Грецією й Чорногорією. Басейн Кавали, Драми та Серреса, який у першій війні перейшов до Болгарії, за цим договором залишили Греції. За цим договором Тутракан (Туртукая) перейшов до Румунії.", "dd427970"]},
"OLAYLAR_2S0920:1914-11-22:0":{"b": ["Висадка в Шатт-ель-Арабі — падіння Басри та відкриття іракського фронту", "c0a87d5d"], "d": ["На початку Першої світової війни британський експедиційний корпус, що прибув з Індії, висадився у Фао в гирлі Шатт-ель-Арабу й невдовзі взяв Басру. Падіння міста означало відкриття іракського фронту та перехід північного краю затоки під британський контроль.", "3b98576d"]},
"OLAYLAR_2S0920:1918-05-26:0":{"b": ["Грузія проголосила незалежність — Закавказький сейм розпався", "6c79a8c7"], "d": ["Грузія, вийшовши із Закавказького сейму, створеного після Брест-Литовська, проголосила незалежність, і була заснована Грузинська Демократична Республіка. Разом із Кутаїсі під управління цієї нової держави перейшла Західна Грузія. Унаслідок цього проголошення Сухумі, Поті, Зугдіді, Горі, Телаві та Душеті перейшли до Грузинської Демократичної Республіки.", "5500d335"]},
"OLAYLAR_2S0920:1918-05-28:0":{"b": ["Проголошено Азербайджанську Демократичну Республіку", "8baecec3"], "d": ["Через два дні після виходу Грузії проголосили Азербайджанську Демократичну Республіку; першим центром стала Гянджа. Того самого дня в Єревані заснували також Республіку Вірменія, і Закавказзя поділилося на три окремі держави. Унаслідок цього проголошення Шемаха, Габала, Ереш, Шабран, Сальян, Губа, Шекі та Барда перейшли до Азербайджанської Демократичної Республіки.", "474c35d5"]},
"OLAYLAR_2S0920:1918-10-27:0":{"b": ["Окупація Алеппо арабськими та британськими силами", "00efb2da"], "d": ["Після розвалу палестинського фронту сили, що наступали на північ, увійшли в Алеппо; місто спершу перейшло до рук арабських, а потім британських частин. Ця окупація, що відбулася за три дні до Мудроського перемир'я, фактично поклала край чотиристолітньому управлінню Османської держави в Сирії.", "38b8fc55"]},
"OLAYLAR_2S0920:1920-04-27:0":{"b": ["Червона армія окупувала Азербайджан — кінець Демократичної Республіки", "ebbb4566"], "d": ["Червона армія увійшла в Азербайджан і розпустила парламент та уряд; дворічна Азербайджанська Демократична Республіка припинила існування. Так нафтовий басейн Баку та Гянджа перейшли під радянське управління. Унаслідок цієї окупації Шемаха, Габала, Ереш, Шабран, Сальян, Губа, Шекі та Барда перейшли під контроль Радянської Росії.", "e475b579"]},
"OLAYLAR_2S0920:1920-07-24:0":{"b": ["Хан-Майсалун — доба Фейсала закінчилася, Сирія перейшла під французький мандат", "80a932b0"], "d": ["Біля Хан-Майсалуна на дорозі Бейрут—Дамаск французи завдали тяжкої поразки сирійським силам, і Арабське королівство Фейсала в Дамаску припинило існування. Франція фактично реалізувала мандатні повноваження, надані їй у Сан-Ремо; область від Алеппо до Дамаска та від Александретти до Дейр-ез-Зора підпорядкували французькій мандатній адміністрації.", "81c76451"]},
"OLAYLAR_2S0920:1921-02-01:0":{"b": ["Засновано Емірат Трансйорданія — Абдалла ібн Хусейн проголосив себе еміром", "5ef520c2"], "d": ["Абдалла, син шерифа Хусейна, прийшовши на північ через Маан, проголосив емірат Трансйорданія; Британія невдовзі визнала цю владу в межах мандата. Амман став центром емірату, а Трансйорданське плато, зокрема Керак, приєднали до цієї нової адміністрації.", "113f01ba"]},
"OLAYLAR_2S0920:1941-05-03:0":{"b": ["Італія анексувала провінцію Любляна до королівства — Любляна відірвалася від Югославії", "c451f492"], "d": ["Італія, яка з крахом Югославії у квітні 1941 року окупувала Любляну та західну половину Словенії, декретом від 3 травня 1941 року анексувала цю область до королівства під назвою провінція Любляна; верховним комісаром став Граціолі. Любляна вийшла зі складу Югославії й перейшла під італійське управління (до вересня 1943 року).", "894bdb8c"]},
"OLAYLAR_2S0920:1941-05-05:0":{"b": ["Хайле Селассіє повернувся в Аддис-Абебу — Ефіопія відокремилася від Італійської Східної Африки", "42470af3"], "d": ["Після того як на початку квітня британсько-ефіопські сили взяли Аддис-Абебу, імператор Хайле Селассіє 5 травня 1941 року переможцем повернувся до столиці; цей день вважають офіційним кінцем італійської окупації (1936-41). Атлас використовує цей день як межу повернення Ефіопії з Італійської Східної Африки.", "b9c24f62"]},
"OLAYLAR_2S0920:1942-01-01:0":{"b": ["Японські сили окупували незахищений острів Лабуан — Британська Малайя (Стрейтс-Сетлментс) втратила свій острів на півночі Борнео", "a946e926"], "d": ["Під час борнейської операції невеликий японський загін висадився на незахищеному острові Лабуан і захопив його; з січня 1942 року до вересня 1945 року острів залишався під японською військовою окупацією. День у джерелах варіюється — 1 або 3 січня (див. ic_not).", "f83ac693"]},
"OLAYLAR_2S0920:1955-11-23:0":{"b": ["Кокосові (Кілінґ) острови вилучено з колонії Сінгапур і передано Австралії", "5c2d70c7"], "d": ["23 листопада 1955 року, в день проголошення (Proclamation) указу в раді, виданого на підставі британського Закону про Кокосові острови 1955 року, та австралійського Cocos (Keeling) Islands Act 1955, острови перестали бути частиною колонії Сінгапур і перейшли під юрисдикцію Австралійського Союзу. Гоум-Айленд (маєток родини Клуніс-Росс і кокосово-малайське поселення) від цього дня перебуває під австралійським управлінням.", "0edcf278"]},
"OLAYLAR_2S0920:1958-10-01:0":{"b": ["Острів Різдва передано Британією Австралії", "c971c518"], "d": ["1 жовтня 1958 року набув чинності британський указ у раді про Острів Різдва (передачу Австралії) 1958 року; суверенітет над островом перейшов від британської колонії Сінгапур до Австралійського Союзу. Флаїнг-Фіш-Коув є населеним і портовим центром острова.", "7c935123"]},
"OLAYLAR_2S0920:1991-11-18:0":{"b": ["Вуковар упав — Югославська народна армія та сербські частини захопили місто після тримісячної облоги", "30db2698"], "d": ["Останні хорватські захисники обложеного Вуковара здалися 18 листопада 1991 року; місто перейшло до рук Югославської народної армії та сербських сил. Згодом місто пройшло через період Тимчасової адміністрації ООН у Східній Славонії (UNTAES).", "09aa356a"]},
"OLAYLAR_2S_0918:1284-01-01:0":{"b": ["Угорський король передав Белград і Мачву Драгутинові", "a4c2c535"], "d": ["Угорський король 1284 року передав управління Мачвою та Белградом сербському королю Стефанові Драгутину, який 1282 року зрікся престолу; Белград понад тридцять років залишався в руках Драгутина (Сремське королівство під угорським сюзеренітетом).", "2fb699cd"]},
"OLAYLAR_2S_0918:1293-01-01:0":{"b": ["Аланья (Аляїє) у постсельджуцький період перейшла під контроль місцевого бейліку", "7b1489b3"], "d": ["З фактичним розпадом Анатолійської Сельджуцької держави в 1290-х роках середземноморський порт Аляїє (Аланья) став незалежним від центральної влади й перейшов під контроль бейліків регіону (в цей період — у сфері впливу Караманідів); точна дата й те, який саме бейлік безпосередньо ним правив, у джерелах не ясні.", "78a4ff46"]},
"OLAYLAR_2S_0918:1319-01-01:0":{"b": ["Угорці повернули Белград від Милутина", "16d254a2"], "d": ["Після смерті Драгутина 1316 року Сербія хотіла утримати Белград, а Угорщина вимагала його повернення; 1319 року угорці напали, після багатомісячних боїв сербське військо відступило, а зруйноване місто приєднали до угорської Мачванської бановини. Белград залишався під угорським управлінням, доки 1403-04 року його не залишили Стефанові Лазаревичу.", "feb8ea91"]},
"OLAYLAR_2S_0918:1322-01-01:0":{"b": ["Сіноп захопив Газі Челебі, і місто потрапило під вплив Джандаридів", "f107586a"], "d": ["З ослабленням влади Хулагуїдів Газі Челебі з родини засновників бейліку Джандариди (Ісфендіяриди), який посилився в області Кастамону та Сінопа, близько 1322 року захопив Сіноп і зробив місто портовим центром бейліку.", "35c2fa9c"]},
"OLAYLAR_2S_0918:1322-03-01:0":{"b": ["Шибеник, опинившись між графами Шубичами та Венецією, приєднався до Венеції", "99b341e0"], "d": ["Шибеник, опинившись між хорватськими магнатами — графами Шубичами з Брибіра — та Венецією, 1 березня 1322 року віддався Венеції й залишався під венеційським управлінням до 1357 року.", "120581de"]},
"OLAYLAR_2S_0918:1322-04-17:0":{"b": ["Трогір приєднався до Венеції проти брибірських князів", "4ccf9ce4"], "d": ["Трогір, на який тиснули графи Шубичі з Брибіра, щоб зберегти свої вольності, 17 квітня 1322 року віддався Венеції й залишався під її протекторатом до 1357 року.", "e69237c1"]},
"OLAYLAR_2S_0918:1327-09-18:0":{"b": ["У Спліті закінчилося угорське панування — почалося венеційське управління", "4b04ca1a"], "d": ["Угорське панування в комуні Спліта, що тривало з 1133 року, закінчилося 18 вересня 1327 року; місто перейшло під венеційське управління й залишалося під ним до 1357 року.", "75ef7dfc"]},
"OLAYLAR_2S_0918:1357-01-01:0":{"b": ["У Спліті закінчилося венеційське управління — угорська влада відновилася", "e99628fc"], "d": ["Венеційське управління в Спліті, що почалося 1327 року, закінчилося 1357 року; місто знову перейшло під безпосередню угорську владу (до 1420 року).", "84447172"]},
"OLAYLAR_2S_0918:1357-07-09:0":{"b": ["Трогір вийшов з-під венеційського протекторату — угорська влада відновилася", "7f112aa8"], "d": ["Трогір залишався під протекторатом і управлінням Венеції до 9 липня 1357 року; коли Людовік Анжуйський почав відривати Далмацію від Венеції, місто вийшло з-під цього протекторату й повернулося під суверенітет хорватсько-угорського королівства.", "6a7c7a44"]},
"OLAYLAR_2S_0918:1357-12-14:0":{"b": ["Шибеник відокремився від Венеції — перейшов під угорську владу", "adb9d6ca"], "d": ["Шибеник 14 грудня 1357 року, коли Людовік Анжуйський відривав Далмацію від Венеції, відокремився від Венеції й перейшов під угорську владу.", "7af69a3b"]},
"OLAYLAR_2S_0918:1358-02-18:0":{"b": ["Задарський договір — Дубровник перейшов від Венеції під угорський протекторат", "57fb81f9"], "d": ["Задарський договір, підписаний 18 лютого 1358 року, поклав край 150-річному пануванню Венеції в Далмації; так Дубровник (Рагуза) вийшов з-під венеційського управління й здобув статус напівавтономної республіки під протекторатом угорського короля Людовіка I.", "e207c893"]},
"OLAYLAR_2S_0918:1358-05-27:0":{"b": ["Вишеградський привілей — Дубровник приєднався до угорського короля Людовіка I", "9d3d02a8"], "d": ["Коли за Задарським миром (лютий 1358 року) Венеція відмовилася від прав на Далмацію, Дубровник провів окремі переговори з королем Людовіком I; у травні 1358 року Вишеградським привілеєм його приєднали до угорської корони (вірність в обмін на захист, щорічна данина та воїни).", "d37ccc8a"]},
"OLAYLAR_2S_0918:1390-06-01:0":{"b": ["Твртко I здобув владу над далматинськими прибережними містами (зокрема Шибеником)", "c53aad4d"], "d": ["Боснійський король Твртко I 1390 року здобув владу над далматинськими прибережними містами, крім Задара; Шибеник також вийшов з-під угорської влади й визнав зверхність боснійського короля.", "dfb86467"]},
"OLAYLAR_2S_0918:1391-01-01:0":{"b": ["Смерть Твртка I; Шибеник повернувся під угорську владу", "ef2d3b2f"], "d": ["Зі смертю боснійського короля Твртка I 1391 року боснійська зверхність над Шибеником припинилася; місто перейшло під владу угорського короля Сигізмунда (1391-1402).", "0f8c4ab3"]},
"OLAYLAR_2S_0918:1408-01-01:0":{"b": ["Область Ерзурума й Ашкале перейшла з рук у руки в суперництві Кара-Коюнлу та Тимуридів", "ca64775a"], "d": ["У порожнечі влади, що виникла після смерті Тимура 1405 року, правитель Кара-Коюнлу Кара Юсуф у 1406-1408 роках виступив проти тимуридських намісників у Східній Анатолії; Ерзурум і сусіднє Ашкале в цій боротьбі вийшли з-під контролю Тимуридів і потрапили під вплив Кара-Коюнлу.", "10b1b07c"]},
"OLAYLAR_2S_0918:1409-07-31:0":{"b": ["Задар перейшов під венеційське управління — Санта Інтрада", "820c9276"], "d": ["Після того як неаполітанський король Владислав продав Далмацію Венеції, мешканці Задара вигнали з міста неаполітанських солдатів; 31 липня 1409 року венеційські проведитори увійшли в місто й запровадили венеційське управління, яке тривало до 1797 року.", "06e4d6fa"]},
"OLAYLAR_2S_0918:1420-06-22:0":{"b": ["Трогір перейшов під венеційське управління", "fbca501f"], "d": ["Під час війни Венеції з Угорщиною з прибуттям флоту генерал-капітана П'єтро Лоредана Трогір 22 червня 1420 року перейшов під венеційське управління; останнє з далматинських міст, що приєдналося до Венеції, воно залишалося під венеційським прапором до 1797 року.", "8ebaf8eb"]},
"OLAYLAR_2S_0918:1462-01-01:0":{"b": ["Ак-коюнлуський Узун-Хасан ліквідував аюбідську гілку Хасанкейфа", "2b464a1f"], "d": ["Хасанкейф і Сіїрт на Верхньому Тигрі, що належали одній з двох останніх уцілілих гілок династії Аюбідів (другою була гілка в Хамі), 1462 року анексував правитель Ак-Коюнлу Узун-Хасан, поклавши край владі Аюбідів.", "8bf494b3"]},
"OLAYLAR_2S_0918:1515-04-01:0":{"b": ["Португалія завершила встановлення панування на берегах Ормузької протоки", "bef031f0"], "d": ["Похід у Перську затоку, розпочатий Афонсу де Албукерке 1507 року, 1515 року завершився тим, що охопив острів Ормуз, а на протилежному березі — Кешм і Бураймі; залежне від Ірану Ормузьке королівство фактично опинилося під португальським протекторатом, а Португалія захопила контроль над торгівлею в затоці.", "117a5c7e"]},
"OLAYLAR_2S_0918:1569-07-01:0":{"b": ["Люблінська унія — українські землі перейшли від Литви до Польщі", "1881ceff"], "d": ["Люблінська унія, підписана 1 липня 1569 року, об'єднала Велике князівство Литовське та Королівство Польське в одну державу (Річ Посполиту). За умовами угоди Поділля, Волинь і Київську землю (зокрема Бар, Бердичів, Білосток і Брацлав) в адміністративному плані передали від Литви безпосередньо Королівству Польському.", "184b03dd"]},
"OLAYLAR_2S_0918:1776-02-14:0":{"b": ["Управління Фіуме передано Хорватії, приєднаній до угорської корони", "dfedccf8"], "d": ["Імператриця Марія Терезія указом від 14 лютого 1776 року передала управління Фіуме Угорщині через Загребську раду; диплом 1779 року зробив місто окремим тілом (corpus separatum), безпосередньо приєднаним до угорської корони.", "bbf160dd"]},
"OLAYLAR_2S_0918:1809-10-14:0":{"b": ["Фіуме за Шенбруннським миром передано Франції (Іллірійські провінції)", "16bf1fca"], "d": ["За Шенбруннським миром від 14 жовтня 1809 року Фіуме перейшов від Австрії до Франції й до 1813 року був частиною наполеонівських Іллірійських провінцій.", "417a8ae7"]},
"OLAYLAR_2S_0918:1813-01-01:0":{"b": ["Повернення Фіуме від французького іллірійського управління до Габсбургів", "1b5b9954"], "d": ["1813 року, після поразки Наполеона в Росії, Фіуме вийшов зі складу Іллірійських провінцій і повернувся до Австрійської імперії.", "5db16c92"]},
"OLAYLAR_2S_0918:1822-10-15:0":{"b": ["Фіуме повернено Угорському королівству", "aafdd0ee"], "d": ["Після рішення Франца I від 5 липня 1822 року граф Дєрдь Майлат 15 жовтня 1822 року від імені угорського уряду прийняв місто; Фіуме повернувся до Угорського королівства.", "e30af380"]},
"OLAYLAR_2S_0918:1841-10-01:0":{"b": ["Єгипетські війська відійшли з області Ахса (Лахса)", "5ea75c8d"], "d": ["Єгипетські війська Мехмеда Алі-паші 1836 року окупували Неджд і Східну Аравію (зокрема Ахсу, Катіф, Укайр і Джубайль); коли Лондонська конвенція про Протоки 1840 року змусила Єгипет відмовитися від завоювань на Аравійському півострові, 1841 року війська відійшли з регіону, а управління повернулося до місцевих сил (вплив Саудитів і Аль Халіфа).", "99ff8f81"]},
"OLAYLAR_2S_0918:1853-07-28:0":{"b": ["Фортецю Ак-Мечеть узято російськими силами — сирдар'їнська лінія Кокандського ханства впала", "e9f9a9c7"], "d": ["Російські сили під проводом генерала Василя Перовського в липні 1853 року після тривалої облоги захопили фортецю Ак-Мечеть на березі Сирдар'ї, що належала Кокандському ханству; згодом фортеця під назвою Перовськ стала передовим постом Російського Туркестану.", "9e64a219"]},
"OLAYLAR_2S_0918:1881-01-24:0":{"b": ["Битва за Геок-Тепе — туркмени ахал-теке зазнали поразки від Росії", "76c7a102"], "d": ["Російські війська під проводом генерала Михайла Скобелєва, взявши 24 січня 1881 року фортецю Геок-Тепе, зламали опір туркменів ахал-теке; закаспійська туркменська область, зокрема Дехістанська рівнина, Абівард і Ниса, увійшла в процес приєднання до Російської імперії (Закаспійську область створено 1881 року). Унаслідок цієї події Кизил-Арват і Ашгабат (землі ахалських туркменів) перейшли до Росії.", "f294fbe6"]},
"OLAYLAR_2S_0918:1881-03-26:0":{"b": ["Проголошено Румунське королівство — князівство стало королівством", "4d413f0c"], "d": ["Румунське князівство, незалежність якого визнали на Берлінському конгресі після російсько-турецької війни 1877-78 років, 26 березня 1881 року (14 березня за юліанським календарем) з коронацією короля Кароля I було перетворено на королівство; уся країна, зокрема Бабадаг, Бирлад, Бузеу та столиця Бухарест, в адміністративному плані стала частиною нового королівства. З проголошенням королівства вся Румунія (Ясси, Галац, Бреїла, Констанца, Тулча, Калафат та інші міста) стала Румунським королівством.", "fbab3abf"]},
"OLAYLAR_2S_0918:1889-01-01:0":{"b": ["Італія анексувала Еритрейське нагір'я з Асмарою та Кереном", "31308dc8"], "d": ["Скориставшись порожнечею влади, що виникла після смерті абіссінського імператора Йоганнеса II 1889 року, Італія після Уччальського договору (2 травня 1889 року) фактично анексувала Еритрейське нагір'я з Асмарою та Кереном; 1 січня 1890 року офіційно проголосили колонію під назвою «Еритрея». Унаслідок цієї події Керен перейшов під італійське управління.", "b6bbb0a5"]},
"OLAYLAR_2S_0918:1895-07-01:0":{"b": ["Північно-східну область Кенії (лінію Гарісса—Марсабіт) приєднано до Британського Східноафриканського протекторату", "e45c6d43"], "d": ["Британський Східноафриканський протекторат, створений 1895 року після передачі концесії Британської Східноафриканської компанії Короні, розширився, охопивши й північно-східні області, такі як Гарісса, Кітуї, Марсабіт і Ваджір; взяття цих внутрішніх областей під фактичне управління розтяглося на другу половину 1890-х років.", "8cf3e473"]},
"OLAYLAR_2S_0918:1897-02-16:0":{"b": ["Емірат Ілорін захоплено силами Королівської нігерської компанії", "b111cb7d"], "d": ["Емірат Ілорін, залежний від халіфату Сокото, був захоплений у лютневому поході 1897 року силами Королівської нігерської компанії під проводом сера Джорджа Голді; військову силу емірату зламали, і область фактично опинилася під британським впливом (офіційна анексія завершилася зі створенням протекторату Північна Нігерія 1900 року).", "95f49872"]},
"OLAYLAR_2S_0918:1899-04-09:0":{"b": ["Короля Буньоро Кабалегу взято в полон, королівство приєднано до Британського протекторату Уганда", "62bc7c64"], "d": ["Король Буньоро Кабалега, який з 1894 року чинив опір британським силам, 9 квітня 1899 року був схоплений в області Ланго (поблизу Доколо) й відправлений у вигнання на Сейшели; землі королівства, зокрема столицю Хойму та Масінді, приєднали до Британського протекторату Уганда.", "87bc3dd6"]},
"OLAYLAR_2S_0918:1900-06-26:0":{"b": ["Торійська угода — королівство Торо стало автономною частиною Британського протекторату Уганда", "c55340a2"], "d": ["Після падіння Буньоро 1899 року сусіднє королівство Торо оформило британський протекторат, під яким перебувало з 1896 року, в межах Угандійської угоди 1900 року; королівство зі столицею Форт-Портал здобуло статус автономної місцевої адміністрації в складі Британського протекторату Уганда.", "8459a73a"]},
"OLAYLAR_2S_0918:1901-09-02:0":{"b": ["Емірат Адамава поділено між Німеччиною та Британією", "b9230d3d"], "d": ["Емірат Адамава (Фомбіна), залежний від халіфату Сокото, внаслідок походів німецьких і британських колоніальних сил 1899-1901 років було поділено надвоє: східну частину (зокрема Гаруа, Баньйо, Маруа, Нгаундере) приєднали до Німецького Камеруну, а західну (зі столицею Йола) — до Британської Північної Нігерії; еміра Зубайра відправили у вигнання. Унаслідок цієї події Рей-Буба (німецька частка Адамави) перейшов під управління Німецького Камеруну.", "e3ebfafa"]},
"OLAYLAR_2S_0918:1902-05-07:0":{"b": ["Битва під Тітом — туареги Ахаггару зазнали поразки від французьких сил", "831143d6"], "d": ["У битві поблизу оази Тіт, що відбулася 7 травня 1902 року під час походу Коттенеста, французькі сили остаточно розбили туарегів кель-ахаггар; ця внутрішня область Сахари, зокрема центр Ахаггару Абалесса та Ідельс, перейшла під контроль Французького Алжиру.", "5c1e86d4"]},
"OLAYLAR_2S_0918:1903-01-01:0":{"b": ["Французькі війська захопили внутрішні райони Убангі-Шарі (лінію Бамбарі—Бріа)", "0b9a9f72"], "d": ["Північні походи Французького Конго на початку 1900-х років поставили під фактичний контроль внутрішню область Убангі-Шарі, що охоплювала Бамбарі, Батангафо, Босангоа та Бріа; 29 грудня 1903 року область офіційно організували як колонію Убангі-Шарі (частину Французької Екваторіальної Африки).", "ebbd38e7"]},
"OLAYLAR_2S_0918:1911-01-12:0":{"b": ["Французькі війська ліквідували султанат Дар-ель-Куті султана Мохаммеда ас-Сенуссі", "644b2c3f"], "d": ["Султанат Дар-ель-Куті зі столицею в Нделе, заснований на работоргівлі, який 1897 року перейшов під французький протекторат, фактично ліквідували походом, організованим 1911 року, оскільки султан Мохаммед ас-Сенуссі й далі чинив опір французькій владі; Сенуссі загинув у бою, а 1912 року султанат офіційно скасували.", "3f913340"]},
"OLAYLAR_2S_0919:1328-01-01:0":{"b": ["Лівонський орден передав землі Клайпеди (Мемеля) пруській гілці Тевтонського ордену", "e61e5d50"], "d": ["Лівонський орден поступився пруській гілці Тевтонського ордену фортецею Клайпеда (Мемель) у гирлі Німану та навколишніми землями; курляндський єпископ 1392 року також передав свою частку тій самій гілці. Клайпеда залишалася за Орденом за Торунським миром 1411 року та Мельнським миром 1422 року, а 1525 року перейшла до герцогства Пруссія.", "cad2853d"]},
"OLAYLAR_2S_0919:1329-01-01:0":{"b": ["Умур-бей відібрав у генуезців портову фортецю Ізміра", "ab92d96e"], "d": ["Айдиногли Умур-бей два з половиною роки тримав в облозі портову фортецю Ізміра, яка залишалася в руках латинян. Генуезький управитель фортеці Мартіно Дзаккарія здав її й вирушив на Хіос.", "1bec5de9"]},
"OLAYLAR_2S_0919:1343-01-01:0":{"b": ["Ібрагім-шах із Сутаїдів опанував Діярбекір", "179196cf"], "d": ["Після розпаду держави Хулагуїдів Діярбекірську область, яка стала ареною боротьби між Джалаїридами та Чобанідами, опанував Ібрагім-шах із Сутаїдів; його влада тривала до 1353 року.", "6143de93"]},
"OLAYLAR_2S_0919:1343-01-01:1":{"b": ["Берат перейшов від Візантії до сербів — завоювання Албанії Стефаном Душаном", "1eba202e"], "d": ["Фортеця Берат, яка 1281 року відбила анжуйську облогу й відтоді була центром останньої візантійської провінції на Адріатиці, під час просування Стефана Душана в Албанію, коли тривала візантійська громадянська війна, перейшла до рук сербів. Після того як у травні або червні 1343 року здалася Круя, упродовж двох років Берат, Каніна та Авлона стали сербськими; на чолі провінції поставили шурина Душана Іоанна Комніна Асеня.", "21876887"]},
"OLAYLAR_2S_0919:1348-01-01:0":{"b": ["Абдальвадиди (Заяніди) звільнилися в Тлемсені від влади Маринідів", "a4aa9573"], "d": ["Абдальвадиди в Тлемсені під проводом Усмана II та його брата Абу Сабіта звільнилися від влади Маринідів. Ця незалежність тривала недовго.", "0afdf111"]},
"OLAYLAR_2S_0919:1351-01-01:0":{"b": ["Байрам-ходжа здобув незалежність — народження бейліку Кара-Коюнлу", "37964815"], "d": ["Байрам-ходжа, якого вважають першим беєм Кара-Коюнлу, здобув незалежність, убивши правителя Сутаїдів Акчасакала Хюсейн-бея. Він узяв Мосул і передав управління ним своєму братові Бірді-ходжі.", "892dced7"]},
"OLAYLAR_2S_0919:1353-01-01:0":{"b": ["Зі смертю Ібрагім-шаха Діярбекір перейшов під управління Джалаїридів", "11c338ef"], "d": ["Після смерті Ібрагім-шаха з Сутаїдів, який з 1343 року панував у Діярбекірській області, вона перейшла під управління Джалаїридів.", "155719ec"]},
"OLAYLAR_2S_0919:1355-01-01:0":{"b": ["Енез перейшов під генуезьке управління (родина Гаттілузіо)", "5dc12940"], "d": ["Енез, важливе портове місто за візантійських часів, 1355 року перейшов під генуезьке управління, і ним правила родина Гаттілузіо.", "33faefdd"]},
"OLAYLAR_2S_0919:1356-01-01:0":{"b": ["Великий князь литовський Ольгерд узяв Брянськ", "3cad9caf"], "d": ["Військо великого князя литовського Ольгерда взяло Брянськ. Місто залишалося під владою Великого князівства Литовського до 1500 року.", "03107c6d"]},
"OLAYLAR_2S_0919:1368-01-01:0":{"b": ["Інанчогуллари визнали зверхність Ґерміяніди", "0679db27"], "d": ["Бейлік Інанчогуллари, що правив в околицях Денізлі, ймовірно, 1368 року визнав зверхність Ґерміяніди.", "55ce9f1f"]},
"OLAYLAR_2S_0919:1371-11-01:0":{"b": ["Деспот Фессалонік Мануїл узяв область Серреса та Драми під візантійське управління", "abb99c3e"], "d": ["Зі смертю короля Вукашина та серреського деспота Углєші під Чирменом (26 вересня 1371 року) сербське управління в області Серреса припинилося. Візантійський принц Мануїл II Палеолог, який правив у Фессалоніках, у листопаді 1371 року взяв Серрес і область, що включала Драму, під візантійське управління. У вересні 1383 року область перейшла до османів.", "b0802648"]},
"OLAYLAR_2S_0919:1378-01-01:0":{"b": ["Зі смертю Пір Хюсейн-бея Ерзінджан і Байбурт перейшли до Мутаххартена", "3269e55d"], "d": ["Після смерті еміра Ерзінджана Пір Хюсейн-бея Ерзінджан і Байбурт перейшли до рук Мутаххартена, одного з емірів Еретни; Мутаххартен став еміром Ерзінджана.", "4993bac9"]},
"OLAYLAR_2S_0919:1379-01-01:0":{"b": ["Таджеддін-бей розбив військо Еретни під Ніксаром і став діяти незалежно", "42982ea7"], "d": ["Навесні 1379 року Таджеддін-бей розбив сили Каді Бурханеддіна та бея Еретни Алаеддіна Алі, які напали на Ніксар. Він припинив платити податки бейліку Еретни й від 781 (1379) року діяв незалежно.", "5d809820"]},
"OLAYLAR_2S_0919:1379-01-01:1":{"b": ["Тимур остаточно захопив Хорезм", "ef76d2c9"], "d": ["Після першого хорезмського походу 1371 року Тимур здійснив іще три. У поході 1379 року він остаточно захопив область, пограбував її й повернувся з рясною здобиччю.", "f2ebd27a"]},
"OLAYLAR_2S_0919:1382-01-01:0":{"b": ["Боснійський король Твртко I заснував Герцег-Новий", "1628221a"], "d": ["Боснійський король Твртко I, щоб скласти конкуренцію Дубровнику в торгівлі сіллю, заснував нове містечко в бухті Топла; пізніше його називали Нові (Герцег-Новий).", "b970dc7f"]},
"OLAYLAR_2S_0919:1383-01-01:0":{"b": ["Тимур узяв Кандагар у Куртів і віддав його своєму онукові Пір Мухаммаду", "84760f70"], "d": ["Кандагар, яким з 1281 року володіли гератські Курти, васали Хулагуїдів, захопили під час хорасанських походів Тимура й віддали його онукові Пір Мухаммаду; відтоді містом управляли тимуридські намісники.", "c2470eb5"]},
"OLAYLAR_2S_0919:1384-01-01:0":{"b": ["Дулкадироглу Халіль-бей повернув Ельбістан від мамлюків", "ee3da686"], "d": ["Ельбістан, який 1381 року перейшов до рук мамлюків, Дулкадироглу Халіль-бей повернув 1384 року.", "104e231d"]},
"OLAYLAR_2S_0919:1394-04-25:0":{"b": ["Тимур захопив і пограбував Діярбекір (Амід)", "f8d200a8"], "d": ["25 або 26 квітня 1394 року Тимур захопив Діярбекір і пограбував місто.", "b1186b21"]},
"OLAYLAR_2S_0919:1399-02-13:0":{"b": ["Герардо Аппіані поступився Пізою Вісконті й заснував синьйорію Пйомбіно", "ac45a9dd"], "d": ["Синьйор Пізи Герардо Аппіані за 200 000 флоринів поступився містом правителю Мілана Джан Галеаццо Вісконті. Собі він залишив синьйорію Пйомбіно, що складалася з Пйомбіно, Суверето, Скарліно та островів Ельба, Піаноза й Монтекрісто.", "68084c1c"]},
"OLAYLAR_2S_0919:1401-01-01:0":{"b": ["Діярбекір віддано Кара-Юлюк Осман-бею — почалася влада Ак-Коюнлу", "38262401"], "d": ["Діярбекір, який Тимур захопив 1394 року, 1401 року віддали Кара-Юлюк Осман-бею, і так у цій області почалася влада Ак-Коюнлу.", "de407b9c"]},
"OLAYLAR_2S_0919:1410-01-01:0":{"b": ["Ерзінджан перейшов під владу Кара-Коюнлу", "5729a50b"], "d": ["Після Мутаххартена Ерзінджан перейшов до рук правителя Кара-Коюнлу Кара Юсуфа. Кара Юсуф спершу призначив намісником міста Пір Омара, одного зі своїх довірених людей.", "69ef181d"]},
"OLAYLAR_2S_0919:1494-01-01:0":{"b": ["Аскія Мухаммад узяв Загу (Дію)", "24561a8c"], "d": ["Аскія Мухаммад, який зійшов на сонгайський престол, наприкінці 899 року за хіджрою за допомогою свого брата курміна-фарі Амара Комзаґо захопив місто Заґа (Дія) на заході внутрішньої дельти Нігеру.", "f6d242d2"]},
"OLAYLAR_2S_0919:1500-01-01:0":{"b": ["Шейбані-хан узяв Бухару та Самарканд", "8f8f40eb"], "d": ["Мухаммад Шейбані-хан, скориставшись безладом серед Тимуридів, узяв Бухару та Самарканд і заснував династію Шейбанідів (узбеків). У 1500-1507 роках він захопив майже всі міста Мавераннахру, Хорезму та Хорасану.", "0e64ecae"]},
"OLAYLAR_2S_0919:1510-01-01:0":{"b": ["Іспанці окупували Беджаю", "8faa0133"], "d": ["Іспанське військо на 8000 осіб, прибувши кораблями, окупувало Беджаю; жителі міста, охоплені панікою, покинули рідні місця.", "364b6234"]},
"OLAYLAR_2S_0919:1515-01-01:0":{"b": ["Агадес підпорядковано Сонгаю", "997362b0"], "d": ["Центр області Аїр Агадес сонгайський султан Аскія Мухаммад підпорядкував Гао; місто залишалося в цій залежності до падіння Сонгаю під Тондібі 1591 року.", "b2b437a3"]},
"OLAYLAR_2S_0919:1522-01-01:0":{"b": ["Засновано султанат Багірмі", "03829f94"], "d": ["Плем'я кенга під проводом Бірні Бесе заснувало на схід від озера Чад сильну державу з центром у Массенья. Заснування династії Багірмі традиційно датують 1522 роком.", "2bd4497c"]},
"OLAYLAR_2S_0919:1535-11-01:0":{"b": ["Помер останній герцог Сфорца, Мілан перейшов до Карла V", "53230b5c"], "d": ["Герцог Мілана Франческо II Сфорца в ніч з 1 на 2 листопада 1535 року помер бездітним. Герцогство перейшло до імператора Карла V, і ним став управляти іспанський намісник.", "03b908c5"]},
"OLAYLAR_2S_0919:1544-01-01:0":{"b": ["Генуезці оселилися на острові Табарка", "0cb474f8"], "d": ["За угодою Карла V з правителем Тунісу, яка дозволяла збудувати фортецю на узбережжі та ловити корали, на острові Табарка поселили генуезьку громаду з Пельї. Острів став торговельною базою під управлінням родини Ломелліні.", "74c7ab83"]},
"OLAYLAR_2S_0919:1556-01-01:0":{"b": ["Після смерті Хумаюна Сефевіди відібрали Кандагар у Великих Моголів", "318eabc8"], "d": ["Після смерті Хумаюна в Делі 1556 року шах Тахмасп скористався суперечкою між могольськими намісниками Кандагара та Замін-Давара; сефевідський загін, що прибув на запрошення намісника Замін-Давара, увійшов до Кандагара, і Тахмасп призначив намісником міста свого двоюрідного брата султана Хусейна-мірзу. Місто залишалося в руках Сефевідів до 1595 року.", "87ac27f5"]},
"OLAYLAR_2S_0919:1558-01-01:0":{"b": ["Росія вторглася в Лівонію, Дерпт упав", "dcb46a8a"], "d": ["Іван IV, щоб здобути вихід до Балтики, вторгся в Лівонію й почав Лівонську війну; він захопив Нарву та Дерпт (Тарту) й обложив Ревель.", "37f1dd66"]},
"OLAYLAR_2S_0919:1579-07-13:0":{"b": ["Засновано фортецю Карловац", "9b28e6ad"], "d": ["Щоб захистити Хорватію та спадкові австрійські землі від османів, у заплаві між Купою та Кораною заснували фортецю Карловац; її наказав збудувати ерцгерцог Карл II, командувач Хорватського військового кордону.", "edc1a0fd"]},
"OLAYLAR_2S_0919:1580-04-10:0":{"b": ["Грамота про заснування (локацію) Замостя", "e1157f3b"], "d": ["Великий канцлер коронний Речі Посполитої Ян Замойський видав грамоту про заснування (локацію) міста Замостя.", "90df0b1c"]},
"OLAYLAR_2S_0919:1582-01-15:0":{"b": ["Ям-Запольське перемир'я — Лівонія та Дерпт перейшли до Речі Посполитої", "7d02d8ad"], "d": ["Між Річчю Посполитою та Росією підписали Ям-Запольське перемир'я; Москва відмовилася від претензій на Лівонію й повернула полоцькі землі. Дерпт (Тарту) з 1582 року залишався в руках Речі Посполитої.", "3aa35e5c"]},
"OLAYLAR_2S_0919:1589-07-02:0":{"b": ["Фортецю Царицин уперше згадано в документі", "ddf65b06"], "d": ["Указ царя Федора Івановича від 2 липня 1589 року згадує фортецю Царицин, засновану для захисту південного кордону на Волзі; цю дату вважають днем заснування міста.", "fd3ba360"]},
"OLAYLAR_2S_0919:1590-07-12:0":{"b": ["Засновано фортецю Саратов", "a3ca702c"], "d": ["Саратов заснував князь Засєкін як фортецю-сторожовий пост, щоб захищати волзький шлях і східні кордони держави від набігів кочовиків.", "07dcdc66"]},
"OLAYLAR_2S_0919:1593-01-01:0":{"b": ["Засновано фортецю Пелим", "baf3e7eb"], "d": ["Воєвода Петро Горчаков заснував Пелим на березі річки Тавди; фортеця стала одним з опорних пунктів російського просування в Західному Сибіру.", "7511aeab"]},
"OLAYLAR_2S_0919:1598-01-01:0":{"b": ["Засновано фортецю Верхотур'є", "81be29bb"], "d": ["На березі Тури, на місці давнього поселення Неромкар, заснували укріплений пункт Верхотур'є; його заснування пов'язане з пошуком коротшого шляху до Сибіру.", "ac40c773"]},
"OLAYLAR_2S_0919:1600-01-01:0":{"b": ["На Турі засновано фортецю Туринськ", "c1d8534e"], "d": ["1600 року в районі нинішнього Туринська заснували російський козацький ясачний острог Туринськ; фортеця належить до придорожніх укріплень російського просування в Західному Сибіру.", "82075fd3"]},
"OLAYLAR_2S_0919:1611-01-01:0":{"b": ["Шах Аббас I заснував у Мазендерані місто Ферахабад", "cab4d0fe"], "d": ["Сефевідський правитель Аббас I наказав заснувати в Мазендерані, неподалік узбережжя Каспію, місто Ферахабад і переселив туди людей з усіх куточків країни. Будівництво почалося 1020/1611 року.", "cc05c705"]},
"OLAYLAR_2S_0919:1631-01-01:0":{"b": ["На Ангарі засновано російську Братську фортецю", "e7b4be59"], "d": ["Під час російського просування у Східний Сибір на річці Ангарі заснували Братську фортецю.", "eb1a1abd"]},
"OLAYLAR_2S_0919:1658-03-08:0":{"b": ["Роскілльський договір — Сконе, Галланд, Блекінге та Борнгольм перейшли до Швеції", "afcae41b"], "d": ["Підписано Роскілльський договір, який завершив Першу Північну війну Карла X Густава; Данія-Норвегія поступилася Швеції Сконе, Галландом, Блекінге та Борнгольмом.", "ac397fd6"]},
"OLAYLAR_2S_0919:1663-01-01:0":{"b": ["Росія заснувала на Сурі фортецю Пенза", "49e8d90b"], "d": ["Пензу заснували як велику фортецю в місці злиття річок Пензи та Сури; після 1684 року вона утворювала західний край Сизранської оборонної лінії.", "afba0eaa"]},
"OLAYLAR_2S_0919:1668-01-01:0":{"b": ["Маркетт заснував французьку місію в Со-Сент-Марі", "86612bcd"], "d": ["Єзуїт Жак Маркетт заснував місію біля початку порогів Со-Сент-Марі між озерами Верхнім і Гурон.", "e90cdea2"]},
"OLAYLAR_2S_0919:1668-01-01:1":{"b": ["Засновано першу факторію Компанії Гудзонової затоки (Васкаганіш)", "07b32d57"], "d": ["У гирлі річки Руперт у затоці Джеймс Медар Шуар де Грозельє заснував поселення, яке згодом вважали першою факторією Компанії Гудзонової затоки.", "790b2f93"]},
"OLAYLAR_2S_0919:1700-01-01:0":{"b": ["Іспанська колоніальна адміністрація заснувала Пітік (Ермосільйо)", "11e5cc04"], "d": ["Іспанська колоніальна адміністрація заснувала містечко на місці давнього індіанського поселення; 1828 року містечко отримало ім'я Хосе Марії Гонсалеса де Ермосільйо.", "4724e13c"]},
"OLAYLAR_2S_0919:1716-01-01:0":{"b": ["У місці злиття Іртиша та Омі засновано російську фортецю Омськ", "13dcce5e"], "d": ["Омськ заснували як фортецю на східному краї Ішимської укріпленої лінії між Тоболом та Іртишем; 1804 року він став містом.", "45facb52"]},
"OLAYLAR_2S_0919:1717-11-30:0":{"b": ["Джунгари захопили Лхасу — Лазанг-хана вбито, Тибет опинився під джунгарською окупацією", "65beea29"], "d": ["Джунгарське військо під проводом Церінга Дондупа після півночі з усіх боків напало на Лхасу, яку обороняв хошутський правитель Лазанг-хан; знайшовши підтримку зсередини, джунгари захопили й пограбували місто, розорили також Поталу. Лазанг-хана вбили під час втечі; джунгари утворили маріонетковий тибетський уряд на чолі зі sTag-rtse-pa.", "b6dcede2"]},
"OLAYLAR_2S_0919:1720-09-24:0":{"b": ["Цінське військо увійшло до Лхаси — джунгарська окупація закінчилася, почався цінський протекторат", "083358c1"], "d": ["З двох армій, які Кансі послав до Тибету, сичуанська колона під проводом Галбі після важкого переходу дісталася Лхаси та без опору взяла місто; усі свої сили джунгари зосередили в Дамі проти кукунорської армії, що йшла з півночі. Після відходу джунгарів з Тибету Цін запровадили в Лхасі тривалий протекторатний лад.", "e5c9dcf8"]},
"OLAYLAR_2S_0919:1721-01-01:0":{"b": ["Експедиція Агуайо заснувала пресидію Лос-Адаес", "2031793a"], "d": ["Експедиція маркіза де Агуайо заснувала в Лос-Адаесі пресидію (військовий пост) і заново заселила місію; пост став східнотехаським прикордонним пунктом Нової Іспанії проти Французької Луїзіани.", "6ccb0ff2"]},
"OLAYLAR_2S_0919:1722-01-01:0":{"b": ["У Барабинському степу засновано російський пост Каїнськ", "b14552a8"], "d": ["З трьох постійних російських укріплень (пасів), заснованих у Барабинському степу, Каїнський пас виник у середній течії річки Омі, там, де в неї впадає річка Каїнка.", "17a78ef2"]},
"OLAYLAR_2S_0919:1743-01-01:0":{"b": ["На річці Уй засновано російську фортецю Троїцьк", "623d75f2"], "d": ["Троїцьк заснували як фортецю там, де в річку Уй впадає Увелька, а 1784 року він отримав міську грамоту.", "49367d34"]},
"OLAYLAR_2S_0919:1749-12-15:0":{"b": ["Указом Єлизавети в гирлі Дону засновано Темерницьку митницю (ядро Ростова)", "46519168"], "d": ["Імператриця Єлизавета Петрівна видала указ про заснування митниці на Дону в гирлі річки Темернік; Темерницька митниця є початком ранньої історії міста Ростова-на-Дону.", "51a82ea9"]},
"OLAYLAR_2S_0919:1750-01-01:0":{"b": ["Французи заснували торговельний пост на річці Гамбер у Торонто", "18975f4c"], "d": ["Французи заснували другий пост на річці Гамбер; наступного року вони збудували форт Руйє на місці нинішньої Ексгібішн-Плейс.", "66aeb450"]},
"OLAYLAR_2S_0919:1750-01-01:1":{"b": ["Каджар Мухаммед Хасан-хан проголосив незалежність; узяв Мазендеран і Гілян", "42fc62e8"], "d": ["Після повалення афшарського Сулейман-шаха вождь каджарів в Астрабаді Мухаммед Хасан-хан проголосив незалежність; крім Астрабада та Горгана, він також узяв під своє управління Мазендеран і Гілян.", "f5398386"]},
"OLAYLAR_2S_0919:1751-01-01:0":{"b": ["Ахмад-шах Дуррані приєднав Балх до своєї держави", "12c6bbf1"], "d": ["Афганський правитель Ахмад-шах Дуррані включив Балх до сфери свого панування.", "e3ef9016"]},
"OLAYLAR_2S_0919:1751-01-01:1":{"b": ["Карім-хан Зенд опанував Ісфаган — афшарське панування в Ірані поступилося управлінню Зендів", "73cdc1e8"], "d": ["Після смерті Надір-шаха (1747) Ісфаганом і Перським Іраком правили від імені афшарських шахів Аділ-шаха (6 липня 1747 року) та Ібрагім-шаха (8 грудня 1748 року). У січні 1751 року Карім-хан Зенд повернувся до Ісфагана й опанував становище. Хорасан під управлінням Шахруха залишився в Афшарів.", "daab8159"]},
"OLAYLAR_2S_0919:1752-01-01:0":{"b": ["На Ішимі засновано російську фортецю Петропавловськ", "5d16ef42"], "d": ["Петропавловськ заснували як російську фортецю, і невдовзі він став важливим центром торгівлі між Росією та Центральною Азією й казахським степом.", "f0724528"]},
"OLAYLAR_2S_0919:1759-01-01:0":{"b": ["Туареги Агадеса відібрали в Канем-Борну соляні копальні Більми", "1a563a74"], "d": ["Канем-Борну, яке у XVIII столітті занепадало, втратило багато поселень у Сахарі, коли 1759 року туареги Агадеса відібрали в нього соляні копальні Більми.", "ebfc53c3"]},
"OLAYLAR_2S_0919:1759-02-13:0":{"b": ["Каджар Мухаммед Хасан-хан зазнав поразки від війська Карім-хана Зенда й був убитий; Астрабад, Мазендеран і Гілян перейшли під управління Зендів", "38f0a375"], "d": ["Військо Карім-хана завдало Каджарам тяжкої поразки; Мухаммеда Хасан-хана вбили під час втечі, а його сина Агу Мухаммеда відвезли до Шираза. Прикаспійські землі Каджарського володіння перейшли під управління Зендів.", "aa7e4a1e"]},
"OLAYLAR_2S_0919:1806-01-01:0":{"b": ["Військо джигаду Усмана дан Фодіо взяло Зарію", "41279ca7"], "d": ["Під час джигаду, розпочатого Усманом дан Фодіо, перший напад на столицю Гобіра Алкалаву виявився невдалим, проте 1806 року захопили Зарію.", "680cebf3"]},
"OLAYLAR_2S_0919:1808-01-01:0":{"b": ["Засновано місто Султанабад (Ерак)", "674237a0"], "d": ["За доби Каджарів генерал Юсуф-хан Гурджі заснував нинішнє місто Ерак і дав йому назву Султанабад.", "6ff3f6de"]},
"OLAYLAR_2S_0919:1818-01-01:0":{"b": ["Засновано містечко Бофорт (Бофорт-Вест)", "c5cb1776"], "d": ["У британській Капській колонії на фермі Гойфлакте в Кару заснували містечко Бофорт.", "70ea5620"]},
"OLAYLAR_2S_0919:1826-01-01:0":{"b": ["Балх зазнав окупації бухарського еміра", "cd255a5d"], "d": ["Балх, який перебував під владою афганців Дуррані, 1826 року окупував бухарський емір; 1841 року афганці повернули місто.", "a3ecb1be"]},
"OLAYLAR_2S_0919:1830-01-01:0":{"b": ["Росія заснувала на Ішимі фортецю Акмола", "6c727ca9"], "d": ["Збудувавши в Караоткелі на річці Ішим фортецю Акмола, Росія зробила її центральним містечком країни сибірських киргизів (казахів).", "9e7d586f"]},
"OLAYLAR_2S_0919:1847-01-01:0":{"b": ["Засновано Копальське укріплення — Північне Семиріччя почало приєднуватися до Росії", "8d4c24c6"], "d": ["На прохання казахів Старшого жуза Росія заснувала Копальське укріплення біля підніжжя Семиріченського Алатау. За джерелом, це полегшило приєднання Північного Семиріччя аж до річки Ілі до Росії.", "ebe25fc6"]},
"OLAYLAR_2S_0919:1852-01-01:0":{"b": ["Прибережні купці оселилися в Казе (Табора)", "173223b0"], "d": ["Після конфлікту з місцевим правителем купці зі східноафриканського узбережжя переселилися на південь; вождь Уньяньембе Фундікіра дав їм місце для поселення біля свого центру в Ітетемії. Це поселення стало ядром караванного центру Табора.", "1261b92f"]},
"OLAYLAR_2S_0919:1861-01-01:0":{"b": ["Фульбе аль-Хадж Умара взяли Дженне", "aa4e37f8"], "d": ["Дженне, де держава Масіна тримала гарнізон, 1861 року перейшло до рук фульбе під проводом аль-Хадж Умара.", "bfbc8ebe"]},
"OLAYLAR_2S_0919:1862-05-16:0":{"b": ["Аль-Хадж Умар узяв Хамдуллахі — кінець держави Масіна", "542f1c0d"], "d": ["Союзні війська Масіни, де знайшов притулок утікач із Сегу Біна Алі, зазнали поразки; центр Масіни Хамдуллахі перейшов до рук аль-Хадж Умара, а Біну Алі та Амаду Амаду стратили.", "213cc232"]},
"OLAYLAR_2S_0919:1880-06-13:0":{"b": ["Бразза заснував Франсвіль", "d28410d7"], "d": ["П'єр Саворньян де Бразза заснував від імені Франції пост Франсвіль на скелястому виступі над річкою Мпасса.", "c23dd54e"]},
"OLAYLAR_2S_0919:1885-02-14:0":{"b": ["Прикордонна конвенція між Вільною державою Конго та Португалією — південний берег гирла Конго за Португалією", "08a16627"], "d": ["За конвенцією, підписаною під час Берлінської конференції, кордон між Вільною державою Конго та Португалією провели самою річкою Конго (Заїр) від гирла до струмка Уанго-Уанго; південний берег, де лежить Сойо, залишився за Португалією, а також Кабінда на північ від річки залишилася за Португалією.", "947cb572"]},
"OLAYLAR_2S_0919:1888-05-01:0":{"b": ["Узбережжя Хадрамауту (Мукалла) перейшло під британський протекторат", "dc824725"], "d": ["Між Британією та яфіїтами (Куайті), які панували на узбережжі Хадрамауту, зокрема в Шихрі та Мукаллі, підписали договір про протекторат; британці повністю взяли на себе зовнішні зносини яфіїтської адміністрації на узбережжі.", "98bd94ee"]},
"OLAYLAR_2S_0919:1890-01-01:0":{"b": ["Французи опанували весь Джолоф", "c6d28eaa"], "d": ["Французи, які колонізували область за допомогою угод із племінними вождями, 1890 року опанували весь Джолоф.", "15595659"]},
"OLAYLAR_2S_0919:1893-01-01:0":{"b": ["Французи окупували Дженне", "b207bf62"], "d": ["Дженне, яке перебувало в руках держави, заснованої аль-Хадж Умаром, 1893 року окупували французькі сили й приєднали до Французького Судану.", "5739cdc4"]},
"OLAYLAR_2S_0919:1894-01-01:0":{"b": ["Гверу засновано як військовий пост", "bd37b323"], "d": ["Місто Гверу в центральній частині нинішнього Зімбабве заснували як військовий пост; згодом воно стало сільськогосподарським центром, а 1914 року отримало статус муніципалітету.", "a8f323b9"]},
"OLAYLAR_2S_0919:1897-01-01:0":{"b": ["Султанат Багірмі перейшов під французький протекторат", "59f20c32"], "d": ["Перед загрозою з боку Рабіха правитель Багірмі Гауранг мусив укласти з Францією договір про протекторат. Коли Рабіх у відповідь пішов окуповувати Багірмі, Гауранг власноруч спалив столицю Массенья.", "fcb0958f"]},
"OLAYLAR_2S_0919:1897-10-01:0":{"b": ["Королівство Каффа приєднано до Абіссінії — останній король Гакі Шерочо потрапив у полон", "c03c44c5"], "d": ["Сили Менеліка II під проводом раса Вольде Гіоргіса в березні 1897 року увійшли в Каффу. Після тяжких боїв Каффу завоювали; останнього короля Гакі Шерочо в жовтні 1897 року схопили, і він здався.", "a434cc44"]},
"OLAYLAR_2S_0919:1898-01-01:0":{"b": ["Французи окупували Гао", "01eabb4c"], "d": ["Гао, давню столицю Сонгаю на Нігері, 1898 року окупували французи; після окупації місто знову розрослося й стало центром області.", "653ce49b"]},
"OLAYLAR_2S_0919:1899-01-01:0":{"b": ["Засновано склад постачання Угандійської залізниці в Найробі", "a3ce3389"], "d": ["На місці нинішнього Найробі, яке доти було переважно безлюдною болотистою місцевістю, британці облаштували склад постачання Угандійської залізниці, що з'єднувала Момбасу з Угандою.", "467c7577"]},
"OLAYLAR_2S_0919:1901-01-01:0":{"b": ["Адамаву поділено — Йола залишилася в Британській Північній Нігерії", "11104686"], "d": ["Адамаву поділили між британською Північною Нігерією та німецьким Камеруном; Боббо Амаду, четвертий син Адами, став еміром Йоли в британській зоні.", "aabd087e"]},
"OLAYLAR_2S_0919:1903-07-27:0":{"b": ["Битва під Бурмі — політична влада халіфату Сокото припинилася", "c7d87e2c"], "d": ["Халіф Мухаммад Тахір, який утік після окупації Сокото британцями, загинув у новому бою з ними; політична влада халіфату Сокото, що тривала близько століття, припинилася.", "b37ec3fb"]},
"OLAYLAR_2S_0919:1904-01-01:0":{"b": ["Накуру офіційно засновано як містечко", "d82a2d76"], "d": ["Завдяки розташуванню на Угандійській залізниці Накуру офіційно заснували як містечко, і воно стало центром сільськогосподарської продукції області.", "bf30445b"]},
"OLAYLAR_2S_0919:1905-01-01:0":{"b": ["На залізниці Оренбург—Ташкент відкрито станцію Аральське море — засновано поселення Аральськ", "85803dcb"], "d": ["Там, де залізниця Російської імперії, що з'єднувала Оренбург із Ташкентом, проходила повз північно-східний край Аральського моря, на березі відкрили станцію «Аральское море»; біля станції виникло рибальське поселення. 1938 року воно отримало статус міста й назву Аральськ.", "99e15bce"]},
"OLAYLAR_2S_0919:1909-06-02:0":{"b": ["Французи взяли Абеше — кінець султанату Вадаї", "3c9b117b"], "d": ["Продовжуючи просування на схід, французи захопили столицю Вадаї Абеше (Абешр) і поклали край султанату Вадаї; останній султан відійшов, не зумівши врятувати столицю.", "1f305da8"]},
"OLAYLAR_2S_0919:1910-05-31:0":{"b": ["Засновано Південно-Африканський Союз", "7434a47f"], "d": ["Згідно із Законом про Південну Африку 1909 року Капська колонія, Наталь, Трансвааль і колонія Оранжевої річки 31 травня 1910 року об'єдналися під назвою Південно-Африканський Союз у складі Британської імперії; центром виконавчої влади стала Преторія, а законодавчої — Кейптаун. Унаслідок цього об'єднання міста Капської, Натальської, Трансваальської та Оранжевої колоній (Кімберлі, Дурбан, Пітермаріцбург, Потчефструм, Порт-Елізабет та ін.) перейшли до Південно-Африканського Союзу.", "7fc35ce0"]},
"OLAYLAR_2S_0919:1911-01-01:0":{"b": ["Французи окупували Джанет", "f32997c8"], "d": ["Джанет, османську нахію, підпорядковану Гату, 1911 року окупували французи. Начальник нахії шейх Амуд до цієї дати отримував платню від Османської держави.", "7075093e"]},
"OLAYLAR_2S_0919:1915-01-01:0":{"b": ["Анкоридж засновано як центр Аляскинської залізниці", "f5014711"], "d": ["Після того як 12 березня 1914 року Конгрес ухвалив Закон про Аляскинську залізницю, навесні 1915 року Аляскинська інженерна комісія облаштувала в Шип-Крік табір будівельників залізниці; на узбережжі виникло наметове місто, а у квітні 1915 року поштове відомство дало новому містечку назву Анкоридж. Місто стало центром Аляскинської залізниці, що простяглася на північ до Фербанкса.", "ffe4cba5"]},
"OLAYLAR_7A4170:1856-01-01:0":{"b": ["Включення Джаґбуба, пустельного центру сенусійї, в османський лад — фірман Абдул-Меджида про пільги", "039fce6d"], "d": ["Мухаммад ібн Алі ас-Сенусі, який багато років жив у Мецці, повернувшись до Триполітанії, оселився в оазі Джаґбуб на єгипетському кордоні та наказав збудувати на панівній скелі велику завію; місцина з кількох хатин незабаром перетворилася на місто. 1856 року фірманом султана Абдул-Меджида майно членів тарикату звільнили від податків, а мюридам надали право збирати закят. Цей фірман зробив оазу на караванному шляху, що зв'язував Західну Африку й Судан із Каїром, частиною османського фінансового та адміністративного ладу й зміцнив Джаґбуб як торговельний центр. Відданість місцевого населення халіфові підтверджує й подорожній щоденник полковника Садика аль-Муайяда, який відвідував ці місця в 1884 та 1893 роках.", "dbe926fd"]},
"OLAYLAR_7A4170:1859-04-25:0":{"b": ["Початок копання Суецького каналу та заснування Порт-Саїда", "cef0be8d"], "d": ["Земляні роботи за проєктом Лессепса, який Висока Порта схвалила 5 січня 1856 року, почалися 25 квітня 1859 року; канал завершили через десять років, 16 листопада 1869 року. На середземноморському кінці робіт, на прибережній косі між озером Манзала та морем, селище з п'яти бараків, збудованих для робітників, стало ядром Порт-Саїда. 1860 року посадовці компанії каналу дали місту цю назву — у значенні «порт Саїда» — на честь тодішнього правителя Єгипту Саїда-паші. Так на османській карті на прибережній смузі, де раніше не було жодного поселення, народився новий порт.", "3e95556e"]},
"OLAYLAR_7A4170:1863-04-03:0":{"b": ["Візит султана Абдул-Азіза до Єгипту та заснування Ісмаїлії на Суецькому перешийку", "bcfacf38"], "d": ["Султан Абдул-Азіз за заохоченням великого візира Юсуфа Кяміля-паші 3 квітня 1863 року вирушив до Єгипту, де його зустріли бурхливими вітаннями; метою було зміцнити прив'язаність до центру вілаєту, який із часів повстання Мехмеда Алі-паші з Кавали фактично почав перетворюватися на окрему державу. Того самого року на перешийку, на пагорбах Тілаль аль-Джіср на березі озера Тімсах, влаштували адміністративний центр компанії каналу: спочатку для інженерів заснували село Карьят ат-Тімсах, а потім для робітників — село Карьят аль-Араб. Коли хедив Ісмаїл-паша, пильно цікавлячись каналом прісної води, збудував собі на цьому пагорбі павільйон, поселення стали називати на його честь Ісмаїлією. Заснування міста датують 1863 роком; точний день невідомий.", "bab96585"]},
"OLAYLAR_7A4170:1869-01-01:0":{"b": ["Намісництво Мідхата-паші в Багдаді та осадження племен — заснування Рамаді та Насірії", "0fa98f06"], "d": ["Мідхат-паша, якого зняли з посади голови Державної ради й віддалили зі Стамбула, у 1869-1872 роках із широкими повноваженнями, обіймаючи також командування Шостою армією, управляв Багдадським вілаєтом, що охоплював і Мосул та Басру. Застосувавши тут Земельне уложення та новий закон про вілаєти, він роздав землі за тапу (свідоцтвами на власність) і прив'язав кочові племена до осілого ладу та державної влади. Як наслідок цієї політики осадження 1869 року на Євфраті для племені дулайм заснували Рамаді, а на півдні руками мутасаррифа Мунтафіка Насіра-паші ас-Саадуна — Насірію; обидва міста постали там, де досі не було поселень, і вперше з'явилися на карті в цей час.", "7babb36f"]},
"OLAYLAR_AMERIKA0920:1511-08-15:0":{"b": ["Засновано Баракоа — перше містечко іспанського завоювання Куби", "8c033cf1"], "d": ["Дієго Веласкес де Куельяр 1511 року із силами, переправленими з Еспаньйоли, почав завоювання Куби й заснував перше іспанське містечко на острові — Нуестра-Сеньйора-де-ла-Асунсьйон-де-Баракоа. У наступні двадцять років Баракоа було опорною областю для експедицій, спрямованих до Мексики (Ернандес де Кордова, Гріхальва, Кортес).", "e3cd5e94"]},
"OLAYLAR_AMERIKA0920:1519-03-25:0":{"b": ["Битва під Сентлою — майянське вождівство Потончан упало, засновано Санта-Марія-де-ла-Вікторію", "8489a7d8"], "d": ["Флот Кортеса, що вирушив з Куби, пристав біля Потончана, міста чонтальських майя в гирлі річки Гріхальва. Іспанці, які перемогли в битві на рівнині Сентла завдяки перевазі в кінноті та вогнепальній зброї, заснували на місці міста містечко Санта-Марія-де-ла-Вікторія. Це було перше постійне іспанське поселення на мексиканському материку; серед подарунків, піднесених тут, була Малінцин (донья Марина), яка стане перекладачкою Кортеса.", "8bbece52"]},
"OLAYLAR_AMERIKA0920:1519-08-15:0":{"b": ["Засновано Панаму — перше європейське місто на тихоокеанському узбережжі", "c0d86c22"], "d": ["Губернатор Дарьєна Педраріас Давіла заснував на тихоокеанському боці перешийка місто Панаму й переніс туди колоніальну адміністрацію з карибського узбережжя. Місто стало портом відправлення розвідувальних і завойовницьких експедицій на південь; звідси споряджали перуанські походи Франсиско Пісарро.", "ce7e51d9"]},
"OLAYLAR_AMERIKA0920:1520-09-04:0":{"b": ["Узяття Тепеаки — перше завоювання Кортеса після Ночі печалі", "a9c27711"], "d": ["Кортес, який у ніч на 30 червня 1520 року (Ніч печалі) з тяжкими втратами відступив з Теночтітлана, знайшовши притулок у Тласкалі, першим ударом напав на вождівство Тепеака, пов'язане з Потрійним союзом. Він узяв місто й заснував іспанське містечко під назвою Сегура-де-ла-Фронтера; так убезпечили дорогу між узбережжям Веракрусу та Тласкалою й підготували базу для другого походу на столицю.", "a7a4b070"]},
"OLAYLAR_AMERIKA0920:1523-07-25:0":{"b": ["Засновано Сан-Себастьян-де-Коліму — Нова Іспанія виходить на тихоокеанське узбережжя", "30332cab"], "d": ["Гонсало де Сандоваль, один із полководців Кортеса, підкорив долину Коліма на заході Мексики й заснував містечко Сан-Себастьян-де-Коліма. Містечко стало однією з перших баз Нової Іспанії на тихоокеанському узбережжі, а в наступні роки живило верфі розвідувальних експедицій Південного моря.", "f5225860"]},
"OLAYLAR_AMERIKA0920:1534-12-06:0":{"b": ["Засновано Сан-Франсиско-де-Кіто — іспанський лад у північній інкській столиці", "7bb9f316"], "d": ["Інкський полководець Руміньяуї спалив північну столицю Кіто, перш ніж залишити її іспанцям. Себастьян де Белалькасар заснував на руїнах Сан-Франсиско-де-Кіто; так після Куско під іспанське управління потрапив і другий центр інкської держави, а завоювання Північних Анд велося звідси.", "569e8d50"]},
"OLAYLAR_AMERIKA0920:1535-01-18:0":{"b": ["Засновано Ліму — столиця Іспанського Перу переїхала в долину Римака", "1f15658c"], "d": ["Оскільки гірське Куско лежало далеко від морського зв'язку з Іспанією, Франсиско Пісарро заснував у прибережній долині Римака Сьюдад-де-лос-Реєс (Ліму). Невдовзі місто стало столицею віцекоролівства Перу та центром іспанського управління в Південній Америці.", "97bcf9d0"]},
"OLAYLAR_AMERIKA0920:1537-01-13:0":{"b": ["Засновано Попаян — міст між Кіто та країною муїсків", "bf451979"], "d": ["Белалькасар, рушивши з Кіто на північ, заснував у долині Кауки Попаян. Місто стало північним краєм іспанського просування з Перу й відкрило шлях, який наступного року привів його до зустрічі з Кесадою в країні муїсків.", "fe54a6a7"]},
"OLAYLAR_AMERIKA0920:1537-08-01:0":{"b": ["Узяття Хунси — поразка саке Кемуенчаточі", "e8c1b661"], "d": ["Гонсало Хіменес де Кесада, піднявшись від річки Магдалени на плоскогір'я, напав на Хунсу, центр сакасґо — одного з двох очільництв конфедерації муїсків, і взяв у полон саке Кемуенчаточу. Захоплене в місті золото стало тією справжньою здобиччю, яка живила чутки про Ельдорадо; так північна половина країни муїсків перейшла під іспанську владу.", "78bf5be1"]},
"OLAYLAR_AMERIKA0920:1537-08-15:0":{"b": ["Засновано Асунсьйон — іспанську базу на річці Парагвай", "9a6dfa42"], "d": ["Оскільки експедиція Ріо-де-ла-Плати не змогла закріпитися в Буенос-Айресі, іспанці відійшли вгору по річці, і Хуан де Саласар де Еспіноса, спираючись на союз із громадами гуарані, заснував Нуестра-Сеньйора-де-ла-Асунсьйон. Упродовж століття містечко залишалося центром іспанського управління в басейні Ріо-де-ла-Плати.", "451f5b55"]},
"OLAYLAR_AMERIKA0920:1538-08-06:0":{"b": ["Засновано Санта-Фе-де-Боготу — іспанську столицю в країні муїсків", "3ed6c301"], "d": ["Кесада заснував Санта-Фе-де-Боготу поруч із Бакатою, центром сіпи. Одразу після заснування на тому самому плоскогір'ї зустрілися завойовницькі колони, що прийшли з трьох різних боків, — Кесади, Белалькасара та німецького командира Федермана — і домовилися вирішити свої претензії в Іспанії. Місто стало столицею королівства Нова Гранада.", "cd8c76fd"]},
"OLAYLAR_AMERIKA0920:1539-01-09:0":{"b": ["Засновано Сан-Хуан-де-ла-Фронтера-де-Уамангу — замок на дорозі Ліма—Куско", "3f1cfdbf"], "d": ["Опір, який Манко Інка вів із Вількабамби, перерізав дорогу між Лімою та Куско. Щоб убезпечити цю дорогу, Франсиско Пісарро заснував Сан-Хуан-де-ла-Фронтера-де-Уамангу посередині між двома столицями; слово «frontera» (прикордоння) в назві містечка прямо говорить про мету заснування.", "fcd683ec"]},
"OLAYLAR_AMERIKA0920:1539-08-06:0":{"b": ["Тунху повторно засновано як іспанське місто", "c3a12867"], "d": ["Після повернення Кесади до Іспанії Гонсало Суарес Рендон повторно заснував за іспанським зразком місто Тунха на місці Хунси, центру саке. Так північна половина країни муїсків, подібно до боготської, потрапила в тривалу систему муніципалітетів та енкоменд.", "fdbb81cc"]},
"OLAYLAR_AMERIKA0920:1540-10-04:0":{"b": ["Засновано Сан-Франсиско-де-Кампече — третя й тривала спроба завоювання Юкатану", "62af9901"], "d": ["Після двох невдалих експедицій, щоб узяти Юкатан, Франсиско де Монтехо (син) заснував на місці майянського міста Кан-Печ містечко Сан-Франсиско-де-Кампече. Цей порт став базою постачання для сил, які мали йти вглиб півострова, і вихідним пунктом походу, що через два роки завершився заснуванням Меріди.", "079bb50a"]},
"OLAYLAR_AMERIKA0920:1541-02-12:0":{"b": ["Засновано Сантьяго-дель-Нуево-Екстремо — почалося завоювання Чилі", "04cd7c3b"], "d": ["Педро де Вальдивія, рушивши з Перу на південь, заснував у долині Мапочо Сантьяго-дель-Нуево-Екстремо. У вересні того самого року містечко спалили під час нападу корінних мешканців під проводом Мічімалонко, і його заснували знову; попри це, іспанське завоювання Чилі велося саме звідси.", "7cfe7c18"]},
"OLAYLAR_AMERIKA0920:1545-01-01:0":{"b": ["Вождівство Кокомів у Сотуті перейшло під іспанську владу", "db6a6487"], "d": ["Сотута, одне з найсильніших майянських вождівств у глибині Юкатану, під династією Кокомів довго чинила опір іспанському просуванню. У роки після заснування Меріди 1542 року вождівство визнало іспанську владу; ця залежність стала тривалою після придушення великого східного повстання 1546-47 років.", "461a3b98"]},
"OLAYLAR_AMERIKA0920:1571-08-15:0":{"b": ["Засновано Вілья-де-Оропесу — заселення зернової долини, яка годуватиме Потосі", "d6821cbf"], "d": ["За наказом віцекороля Франсиско де Толедо в долині Кочабамби заснували Вілья-де-Оропесу. Родючу землю долини організували як зерновий край, що мав годувати численну робочу силу срібних копалень Потосі; містечко стало житницею колоніального Верхнього Перу.", "52cdfafe"]},
"OLAYLAR_AMERIKA0920:1572-06-24:0":{"b": ["Падіння Вількабамби — кінець незалежної інкської держави", "31b5a95d"], "d": ["Після падіння Куско 1533 року Манко Інка та його наступники сорок років зберігали в горах Вількабамби незалежну інкську державу. Похід, організований віцекоролем Франсиско де Толедо, захопив покинуту столицю; останнього правителя, Тупака Амару, який утік, схопили, привезли до Куско й там стратили. Так припинилося політичне існування чотиристолітньої інкської династії в андському світі.", "957d76a8"]},
"OLAYLAR_AMERIKA0920:1596-09-20:0":{"b": ["Засновано Монтеррей — столицю Нуево-Леона", "ec6e44bc"], "d": ["Після двох невдалих спроб Дієго де Монтемайор заснував біля витоку джерела Санта-Лусія місто Сьюдад-Метрополітана-де-Нуестра-Сеньйора-де-Монтеррей. Це поселення на північному прикордонні стало опорним пунктом тривалого розширення Нової Іспанії на північний схід (Нуево-Леон).", "6bfa991f"]},
"OLAYLAR_AMERIKA0920:1619-01-01:0":{"b": ["Засновано Сан-Франсиско-де-Борху — іспанська влада в Майнасі", "7ee32d19"], "d": ["Дієго Вака де Вега, заснувавши Сан-Франсиско-де-Борху нижче ущелини Понго-де-Мансерічі на річці Мараньйон, підпорядкував область Майнас іспанському управлінню. Містечко стало вихідним пунктом мережі єзуїтських місій у верхів'ях Амазонки, яка проіснувала все наступне століття.", "83ae5281"]},
"OLAYLAR_AMERIKA0920:1718-05-01:0":{"b": ["Засновано місію Сан-Антоніо-де-Валеро — ядро Іспанського Техасу", "ca9bd147"], "d": ["У відповідь на проникнення французів з Луїзіани на захід Іспанія вирішила створити в Техасі постійну проміжну базу. Отець Оліварес заснував на березі річки Сан-Антоніо місію Сан-Антоніо-де-Валеро; через кілька днів губернатор Аларкон розмістив поруч пресидію Сан-Антоніо-де-Бехар. Згодом будівлю місії називатимуть Аламо.", "74e48544"]},
"OLAYLAR_AMERIKA0920:1774-01-01:0":{"b": ["Засновано Рефухіо (нинішній Матаморос) — заселення гирла Ріо-Гранде", "f3b86da7"], "d": ["Програма заселення Нуево-Сантандера, яку Хосе де Ескандон здійснював з 1740-х років, наповнила нижній басейн Ріо-Гранде ранчо та містечками. Нуестра-Сеньйора-дель-Рефухіо-де-лос-Естерос заснували на південному березі річки як одну з останніх ланок цієї програми; у XIX столітті поселення дістало назву Матаморос.", "913bb307"]},
"OLAYLAR_AMERIKA0920:1821-09-15:0":{"b": ["Акт про незалежність Центральної Америки — генерал-капітанство Гватемала відокремилося від Іспанії", "f998089a"], "d": ["Після мексиканського Ігуальського плану збори, що зібралися в Гватемалі, проголосили незалежність генерал-капітанства від Іспанії; генерал-капітан Габіно Гаїнса залишився на чолі перехідного уряду. Так іспанська влада припинилася на землях нинішніх Гватемали, Сальвадору, Гондурасу, Нікарагуа та Коста-Рики. Після нетривалого приєднання до Мексиканської імперії область 1823 року утворила Сполучені провінції Центральної Америки.", "c4e39cd1"]},
"OLAYLAR_AMERIKA0920:1839-01-01:0":{"b": ["Засновано Нуева-Гельвецію — Мексика відкрила долину Сакраменто для заселення", "067a1f2a"], "d": ["Швейцарський переселенець Джон Саттер з дозволу та за земельним наділом від мексиканської влади заснував Нуева-Гельвецію в місці злиття річок Сакраменто та Американ. Укріплене ранчо стало найдальшим передовим постом Мексики в глибині Верхньої Каліфорнії; після відкриття золота 1848 року воно перетвориться на центр каліфорнійської міграції.", "1c5eab3d"]},
"OLAYLAR_EK10:1402-07-28:0":{"b": ["Після ангорського розгрому волоський господар Мірча знову взяв Добруджу — Силістру, Констанцу, Бабадаг, Ісакчу", "5eaefc68"], "d": ["Поразка Баязида Блискавичного від Тимура під Анкарою похитнула османську владу вздовж Дунаю. Волоський господар Мірча, скориставшись цим вакуумом, знову увійшов у Добруджу; Силістра, Констанца, околиці Бабадага та Ісакча на дунайському березі залишалися в його руках усі роки міжцарів'я. Мірча підтримував Мусу Челебі проти Челебі Мехмеда. Силістру він тримав до своєї смерті 1418 року.", "58dabbe8"]},
"OLAYLAR_EK10:1416-01-01:0":{"b": ["Перехід Бабадага з околицями до османів — Мірчу та його сина Михаїла розбито", "bfda2c60"], "d": ["Челебі Мехмед, розбивши волоського господаря Мірчу та його сина Михаїла, узяв під османську владу Бабадаг із околицями в Північній Добруджі. Бабадаг був містечком, що носило ім'я Салтука Баби й було засноване туркменським поселенням XIII століття. Силістра, Констанца та інші добруджанські фортеці в околицях залишалися за Волощиною до 1419 року; тобто Бабадаг три роки виглядає островом (ексклавом), відірваним від османської землі.", "b1e2339a"]},
"OLAYLAR_EK10:1419-01-01:0":{"b": ["Повернення Силістри та Добруджі — після смерті Мірчі", "73eb6ae9"], "d": ["Смута, що виникла у Волощині після смерті волоського господаря Мірчі 1418 року, дала Челебі Султанові Мехмеду нагоду повернути Силістру та Добруджу. Навесні 1419 року Силістра, Констанца та більша частина Добруджі знову перейшли під османське управління; фортеці Енісала (Єнісале) та Ісакчу відремонтували й зробили прикордонними (серхат); відтоді Добруджа залишалася османською до 1878 року.", "a2a9ad4e"]},
"OLAYLAR_EK10:1420-01-01:0":{"b": ["Замикання Нижнього Дунаю — приєднання Джурджу, Турну та Оршови", "331a0b68"], "d": ["Після закінчення міжцарів'я захід Челебі Мехмеда з упорядкування дунайської лінії дав плоди 1420 року. Фортеця Джурджу, яку волоський господар Мірча Старий збудував на власній землі, покриваючи видатки продажем солі, того року перейшла в османські руки (Добруджу повернули роком раніше, навесні 1419 року — TDV silistre), а Турну (Куле / Холовник) на правому березі Дунаю та Оршову — пізніше Фетхюлісслам — приєднали. Так під контроль узяли обидва береги ріки водночас. Значення Джурджу випливає з його географії: це османська фортеця на лівому, тобто волоському, березі Дунаю, яка разом із Русе на протилежному березі тримає два кінці однієї переправи. Османські документи прямо фіксують цю двоїстість — для Русе пишуть «Єрґьогю по цей бік», а для Джурджу — «Єрґьогю по той бік». 1427 року фортецю відіб'ють волохи, 1449 року вона знову перейде під османський контроль, а каза Джурджу, підпорядкована Нікопольському санджаку, стане островом прямого управління всередині воєводства. Тут починається відповідь на те, чому на карті волоська смуга вздовж Дунаю темного кольору.", "4c3c95d4"]},
"OLAYLAR_EK10:1433-01-01:0":{"b": ["Область Топлиця (Куршумлія, Прокуп'є) перейшла під османську владу", "e22e690d"], "d": ["Вважають імовірним, що під час заручин Мурада II з Марою Бранкович область Дубочиця та Топлиця (околиці Лесковаця, Куршумлії та Прокуп'є) перейшла під османську владу; запис тахриру 1445-1447 років показує, що цю область віддали османським сипахам як тімари. На карті Куршумлія та Прокуп'є з цього року перебувають під османським управлінням.", "335352f1"]},
"OLAYLAR_EK10:1448-01-01:0":{"b": ["Приєднання Сараєвської рівнини — створення османського форпосту всередині Боснії", "be5c0f00"], "d": ["Після того як 1428-1429 років боснійських королів обклали даниною, османи почали надовго закріплюватися всередині королівства. У 1428-1435 роках узяли містечко Ходидєд; 852 (1448) року вілаєт Ходидєд разом із Сараєвською рівниною повністю перейшов під османське управління. Це була прикордонна область (уч), створена посеред королівства за п'ятнадцять років до завоювання Боснії, і управляв нею скопський бей Іса-бей, що мав титул воєводи, — оскільки навколо ще залишалися залежні від османів боснійські пани, область була під двостороннім контролем. У цей період народилося й саме місто: до 1462 року Ісхак-бей або його син Іса-бей заснували перший мусульманський квартал, 862 (1458) року на ім'я Фатіха збудували мечеть Хюнкяр, а після забудови орних земель села Бродець постало містечко Сарай (Сараєво). Завоювання 1463 року ліквідувало Боснійське королівство; а Сараєвська рівнина на той час уже п'ятнадцять років була османською землею.", "df377352"]},
"OLAYLAR_EK10:1457-01-01:0":{"b": ["Приєднання Подгориці до османських земель — взяття під контроль Зетської рівнини", "46e401c5"], "d": ["Містечко на рівнині за двадцять кілометрів на північ від Шкодерського озера, де зливаються води Морачі та Рибниці, у джерелах уперше згадується 1216 року під назвою Рибниця, а 1326 року — Подгориця. 1457 року його приєднали до османських земель, і так контроль над Зетською рівниною вийшов із рук династій Балшичів і Црноєвичів. Фатіх Султан Мехмед у 1474-1478 роках наказав збудувати фортецю та мечеть на стрімких скелях біля злиття двох річок; після завоювання Шкодера 1479 року область підпорядкували новоствореному Шкодерському санджаку. Подгориця, яка в тахрирі 1485 року була християнським містечком із сорока дворів, 1529-1530 років досягла 800 осіб і гарнізону з тридцяти двох осіб під командуванням диздара у фортеці, а 1582 року — 322 дворів. 1662 року Евлія Челебі нарахував у Фортеці Фатіха триста будинків, комори, склади зброї та сімсот захисників. Ці записи показують і різницю між рівниною та горами Зети: рівнина — це перелічена, оподаткована османська каза з гарнізоном, тоді як у XVIII столітті місто доведеться укріплювати мурами з шістьма бастіонами та трьома брамами, щоб запобігти набігам племен із чорногорських гір. Подгориця наприкінці війни 1876-1878 років перейшла до Чорногорії і за Берлінським договором залишилася за нею.", "d0b08ff8"]},
"OLAYLAR_EK10:1465-01-01:0":{"b": ["Взяття Фочі — відкриття першого входу в герцогство Герцеговина", "f098a9e6"], "d": ["Після ліквідації Боснійського королівства 1463 року настала черга земель Стефана Вукчича-Косачі, який відокремився від королівства й заснував власне герцогство. Фоча в долині Дрини, на перехресті торговельного шляху, що з'єднував Стамбул із Дубровником, 1465 року перейшла під османське управління. Значення міста зрозуміли відразу: 1470 року його зробили центром новоствореного санджаку Герсек — тобто адміністративне ядро Герцеговини було закладено в Фочі ще до падіння самого герцогства. Приєднання всього герцогства тривало до 1483 року. Відтоді завдяки сприятливому клімату та розташуванню на перехресті шляхів Фоча розвивалася як торговельний і адміністративний центр. На карті ця дата — день, коли після завоювання Боснії почалася друга хвиля на південь.", "9acfcdda"]},
"OLAYLAR_EK10:1469-01-01:0":{"b": ["Остаточне приєднання Лівна та західної Боснії — встановлення венеційського кордону", "c14d4283"], "d": ["Фортеця на плато, що панує над Лівненською рівниною, у 1448-1454 роках перебувала в руках засновника герцогства Герцеговина Стефана Вукчича-Косачі. Під час боснійського походу 1463 року османські сили ненадовго її зайняли, але того самого року її відбили; 1466 року володарем міста був Іваніш Влаткович. За висловом TDV, остаточна османська влада встановилася, найімовірніше, у 1468-1469 роках, і тахрир 1485 року вже фіксує Лівно як османську землю. Це закриття західного краю завоювання Боснії: Лівно стало небезпечним прикордонним містечком, сусіднім із венеційськими землями, що лежали по рівнині лише за тридцять шість кілометрів, і зберігало це становище до 1521-1522 років, коли намісник Боснії Ґазі Хюсрев-бей узяв венеційські фортеці.", "8e012cb5"]},
"OLAYLAR_EK10:1476-02-01:0":{"b": ["Втрата Беюрделена (Шабаца) на користь угорців — перша пробоїна в савській лінії", "129fe8f2"], "d": ["У місцині, що раніше називалася Заслон і за доби Фатіха Султана Мехмеда перейшла до османських рук, 1471 року збудували дерев'яно-земляну фортецю. Оскільки вона стояла в пункті, що загрожував Белграду, і звідси легко було робити набіги на південні області Угорщини та Австрії, фортеця дістала й назву від цієї функції — Беюрделен означає «бастіон, що б'є збоку». Угорський король Матяш Корвін наприкінці 1475 року обложив фортецю й у лютому 1476 року захопив її. Угорська поема «Szabács viadala», яка розповідає про облогу, є одним із найдовших зразків угорської історичної поезії XV століття, текст яких зберігся донині. Угорці створили в області банат і, наново укріпивши фортецю з каменю, зробили її ланкою ланцюга прикордонних фортець. 1492 року османи спробували повернути її, але не змогли; сорок п'ять років фортеця залишалася в угорських руках.", "87ae8b15"]},
"OLAYLAR_EK10:1479-08-01:0":{"b": ["Завоювання Іонічних островів — кінець герцогства Токко: Лефкада, Кефалонія, Закінф, Ітака", "07b27251"], "d": ["Константинопольський (Стамбульський) мир, підписаний із Венецією в січні того самого року, залишив за османами Шкодер і албанське узбережжя; а Іонічні острови перебували під управлінням не Венеції, а родини Токко, яка тримала графство Кефалонія — Закінф, і їх узяли окремою операцією. За статтею TDV «Аямавра» (Лефкада), останній герцог Леонардо Токко спочатку зберігав вірність, одружившись із родичкою Фатіха Міліцею Бранкович, але коли 1464 року дружина померла, 1477 року, одружившись із Франческою Марцано з неаполітанської династії, образив падишаха. Через два роки флот під командуванням бея Вльори Ґедіка Ахмеда-паші захопив Лефкаду разом із Кефалонією на південь від неї; Леонардо та Франческа втекли в Італію. Стаття «Ґедік Ахмед-паша» повідомляє, що під час тієї самої операції взяли також Закінф (Занте); підпорядкована графству Кефалонія Ітака також тоді перейшла під османське управління. Так морський шлях від гирла Адріатики до Мореї опинився цілком під контролем. З-поміж островів Закінф за три роки залишать Венеції, Кефалонію та Ітаку втратять 1500 року, і тільки Лефкада залишиться в османів на двісті років.", "725a61d9"]},
"OLAYLAR_EK10:1482-01-01:0":{"b": ["Васальна залежність Зети Црноєвичів і перетворення Цетинє на центр", "59d20267"], "d": ["Оскільки 1479 року Шкодер залишився в османів, у межі імперії потрапила й гірська область Зета в його тилу. Родина Црноєвичів, яка тримала область, визнала владу Баязида II, що посів престол після смерті Фатіха, і, обкладена даниною, залишилася вільною у внутрішніх справах; Іван Црноєвич переніс свій центр із рівнини в Цетинє біля підніжжя гори Ловчен і заснував місто. Монастир, який він збудував тут через два роки, став релігійним центром області. Так Чорногорія постає на карті не як пряма османська земля, а як васальна область світлого тону. Стаття TDV «Чорногорія» згадує династію та Цетинську єпархію і пише, що 1514 року владу через Іскендер-бея (з роду Црноєвичів, вихованого при османському дворі) перетворили на окремий санджак; 1482 рік у TDV не згадано, це дата чорногорської історіографії. Через суворість географії управління тут ніколи не діяло так жорстко, як на рівнинах.", "c61bf059"]},
"OLAYLAR_EK10:1484-07-15:0":{"b": ["Завоювання фортеці Кілія — замка гирла Дунаю", "ef4eca73"], "d": ["Молдавія з вересня 1455 року була васальним воєводством, що щороку платило данину в дві тисячі золотих, але два її порти з виходом до Чорного моря все ще були в руках господаря, і торгівля з Дунаю йшла через них. Баязид II перший великий похід свого правління спрямував саме на ці два порти. Коменданта фортеці Кілія, яку десять днів вдень і вночі обстрілювали з гармат, було змушено здатися. Фортецю взяли під пряме османське управління й перетворили на санджакбейство; у другій половині XVI століття через козацьку загрозу її зробили казою й підпорядкували Аккерманському санджаку бейлербейства Румелії. Відтоді Молдавія на карті постає двоярусною: усередині воєводство стоїть як васальна земля світлого тону, а два прибережні порти — це прямі османські санджаки темного тону. Стаття TDV «Молдавія» називає ці два порти «ключами та воротами Молдавії» й пише, що область остаточно підпорядкували османам за Баязида II.", "8b039ea4"]},
"OLAYLAR_EK10:1484-08-04:0":{"b": ["Завоювання Аккермана — гирло Дністра та закриття чорноморських воріт Молдавії", "7cb20feb"], "d": ["Через двадцять днів після капітуляції Кілії військо підійшло до Аккермана в гирлі Дністра, і 4 серпня фортецю взяли. Місто було найжвавішим портом Молдавії; коли за доби Фатіха господар Петро III 1455 року визнав османську владу, аккерманським купцям дозволили торгувати, а тепер порт перейшов безпосередньо до держави. Аккерман, після завоювання перетворений на санджак бейлербейства Румелії, 1593 року приєднали до новоствореного еялету Озі. Так зовнішня оболонка Молдавії, оточена з півночі Хотином, а з півдня Кілією та Аккерманом, почала переходити під прямий османський контроль; воєводство залишалося вільним у внутрішніх справах, але втратило вихід до моря. На карті між ними немає порожньої області — портові санджаки темного тону та землі воєводства світлого тону торкаються одне одного; буджацький степ між ними до 1538 року все ще є частиною воєводства.", "23705829"]},
"OLAYLAR_EK10:1499-08-26:0":{"b": ["Капітуляція Лепанто — гирло Коринфської затоки відбирають у Венеції", "2cfe0777"], "d": ["Лепанто з 1407 року було в руках Венеції й тримало гирло Коринфської затоки; усе узбережжя всередині затоки залежало від досяжності цієї фортеці. У поході 1499 року фортецю обложили з суходолу, а османський флот, що біля Лепанто бився з венеційським флотом, допомагав силам облоги з моря. 26 серпня венеційці у фортеці здали містечко османам. Відтоді місто сто вісімдесят вісім років залишалося в османів, 1687 року з утратою Мореї знову перейшло до Венеції, а 1715 року його повернули. Морська битва того самого літа та ця капітуляція — дві окремі події: бій флотів відбувся на західному краю Мореї, у водах Сапієнци — Зонкьйо; Лепанто ж упало внаслідок суходільної облоги в гирлі Коринфської затоки.", "49c0fbd8"]},
"OLAYLAR_EK10:1512-01-01:0":{"b": ["Приєднання Сребреницького банату — перший злам угорської лінії в північній Боснії", "6d98c725"], "d": ["Після падіння Боснійського королівства 1463 року Матяш Корвін перейшов у контрнаступ і створив на півночі королівства два банати, які зупинили просування османів: на заході Яйце, на північному сході Сребреник. Це була передова оборонна лінія Угорщини в Боснії, що закривала коридор між Савою та Босною. 1512 року Сребреницький банат захопили; так обвалився східний фланг лінії, і Зворницький санджак зміг розширитися на північ. Яйце ж на західному фланзі протрималося ще шістнадцять років, і взяти його вдалося лише 1528 року, після Мохача.", "0d4ad0e7"]},
"OLAYLAR_EK10:1521-07-07:0":{"b": ["Завоювання Беюрделена — перша фортеця, взята Сулейманом Законодавцем, і місце рішення щодо Белграда", "85177a90"], "d": ["Під час першого угорського походу Султана Сулеймана Законодавця сили бейлербея Румелії Ахмеда-паші, надіслані в цю область, після запеклої облоги 7 липня 1521 року взяли фортецю. Беюрделен — перша фортеця, завойована за правління Сулеймана Законодавця. Після завоювання падишах особисто увійшов у фортецю та наказав розбудувати місто; тут же ухвалили й рішення про завоювання Белграда — тобто план щодо Белграда, який упаде 29 серпня 1521 року, склали саме в Беюрделені. Відтоді фортеця майже двісті років залишалася в османських руках; спочатку її підпорядкували еялету Румелії, з 1580 року — еялету Боснія, потім ненадовго Смедерівському, а зрештою Зворницькому санджаку. На карті ця дата — день, коли савська лінія зімкнулася на користь османів.", "8c0178ad"]},
"OLAYLAR_EK10:1594-08-28:0":{"b": ["Починається повстання трьох воєводств — Трансильванія перейшла до Священної ліги, проосманських бояр заарештовано", "68a33800"], "d": ["На другому році Довгої війни османський васальний пояс у Центральній Європі раптово розпався. Наприкінці літа до Священної ліги, створеної під патронатом папи Климента VIII, приєдналися Молдавія та Трансильванія: молдавський господар Арон Воде 16 серпня 1594 року документально оформив свій перехід на християнський бік, а князь Трансильванії Жигмонд Баторі 28 серпня 1594 року зламав внутрішню опозицію, розправившись із проосманськими вельможами, які виступали проти війни. Волоський господар Михай Хоробрий приєднався до союзу восени того самого року. Так три васальні князівства османів на північ від Дунаю — три воєводства, що сто п'ятдесят років платили данину й господарів яких затверджував Стамбул, — тієї самої осені разом перейшли на протилежний бік. Рішення оформили договором, підписаним у Празі 28 січня 1595 року. Це був найтяжчий удар, якого зазнала османська система непрямого управління на північ від Балкан; повстання придушать, але вірність трьох князівств ніколи вже не буде такою міцною, як у 1526-1593 роках.", "32a29f3a"]},
"OLAYLAR_EK10:1594-11-01:0":{"b": ["Бухарестське повстання та напад на дунайські фортеці", "18971100"], "d": ["Рішення про перехід до Священної ліги через місяць виконали кров'ю: Михай Хоробрий у Бухаресті вирубав османський гарнізон і левантійських кредиторів у місті. Тієї самої зими повстання поширилося на дунайську лінію; волоські сили напали на Джурджу, Браїлу, Хиршову та Силістру, а на молдавському боці Арон Воде так само напав на османський гарнізон у Бендерах. Вибір місць удару не випадковий: усе це були не землі воєводств, а фортеці та кази вздовж Дунаю під прямим османським управлінням — каза Джурджу була підпорядкована Нікопольському санджакбейству, Браїла з 1538 року — безпосередньо державі, а Бендери також з 1538 року — Буджацькому санджаку. Тобто повстання вдарило не по внутрішній васальній області, а по прямій османській оболонці, що її оточувала. Не пробивши цієї оболонки, трикутник Трансильванія — Волощина — Молдавія не можна було приєднати до габсбурзького фронту.", "95f2286f"]},
"OLAYLAR_EK10:1595-08-23:0":{"b": ["Битва під Келугерені — волоський похід Коджі Сінана-паші", "201210a1"], "d": ["Коли всі три воєводства разом вийшли з рук, великий візир Коджа Сінан-паша з великим військом перейшов Дунай і вирушив, щоб знову привести Волощину до покори. Михай Хоробрий, знаючи, що у відкритому бою не зможе чинити опір, чекав на військо під Келугерені, біля болотистої переправи через Няжлов, і несподівано напав на сили, затиснуті на вузькій місцевості. Не маючи змоги встояти проти чисельно переважаючої османської армії після нападу, він відступив на північ, у гори; Сінан-паша зайняв Бухарест і Тирговіште й спробував перевести Волощину під пряме управління. Тому Келугерені було для османів не поразкою, а засідкою, яка затримала завершення походу; але те, що Михай зміг зберегти своє військо, дало йому змогу за кілька тижнів, за допомогою з Трансильванії, перейти в контрнаступ.", "a2263c60"]},
"OLAYLAR_EK10:1595-10-01:0":{"b": ["Відхід із Волощини та напад біля Джурджу — каральний похід залишився без результату", "118806e1"], "d": ["Унаслідок контрнаступу Михая Хороброго, що об'єднався з силами трансильванського князя, Сінан-паша залишив Тирговіште та Бухарест і відступив до Дунаю. Найдорожча мить відходу сталася біля переправи: у жовтні 1595 року акинджі, які йшли слідом за військом, що поверталося з Волощини, потрапили біля Джурджу в засідку Михая. Так похід закінчився, не досягнувши мети перевести Волощину під пряме управління, і воєводство фактично залишилося втраченим. Османську владу в цьому трикутнику вдалося відновити лише з роками й частинами; повернення Трансильванії до покори чекало повстання Бочкаї 1604 року, а повне закриття фронту — Житваторокського договору 1606 року.", "ab33575c"]},
"OLAYLAR_EK10:1713-06-24:0":{"b": ["Відокремлення Хотина від Молдавії — прямий османський санджак посеред воєводства", "947517cb"], "d": ["Перехід молдавського господаря Дмитра Кантеміра на бік Росії під час Прутського походу показав, що північний кордон воєводства більше не можна залишати господареві. Тому після 1711 року Хотин забрали в Молдавії та перевели під пряме османське управління; спочатку йому надали статус нахії, потім санджаку. Після тимчасової російської окупації 1713 року фортецю відремонтували й розширили під наглядом османсько-французької технічної комісії, надісланої зі Стамбула, і вона стала наймогутнішим османським укріпленням на північ від Дунаю. Те, що від цього часу на карті Хотин виходить із тону васального воєводства й переходить у прямий османський колір, стоячи посеред васальної Молдавії наче самотній острів, є саме відповідником цього адміністративного відокремлення — це не помилка креслення. Така сама структура вже існувала в Буджаку з 1538 року, а в Кілії та Аккермані — з 1484 року: воєводство вільне у внутрішніх справах, прикордонні фортеці належать державі.", "7c5d350f"]},
"OLAYLAR_EK10:1788-04-24:0":{"b": ["Друга австрійська окупація Беюрделена — відкриття савського фронту", "063b3ad0"], "d": ["Після вступу Австрії 9 лютого 1788 року у війну на боці Росії савська лінія знову стала фронтом, і 24 квітня 1788 року Беюрделен перейшов під австрійську владу. Раніше, 17 серпня 1717 року, фортецю без бою залишили Австрії, і вона тримала її до Белградського миру (1739); тоді населення так зменшилося, що в місті залишилося тридцять чотири християнські доми й жодного мусульманина. За османської доби 1739-1788 років населення знову зросло до 1500-2000. Друга окупація закінчилася Свіштовським миром (4 серпня 1791), і фортецю повернули османам.", "de07456b"]},
"OLAYLAR_EK10:1806-01-26:0":{"b": ["Передання Беюрделена Карагеоргію — перша фортеця в Першому сербському повстанні", "5c913eb4"], "d": ["Під час першої сербської революції, яка почалася 1804 року як відповідь на гніт даіїв і ямаків у Белграді, а згодом набула національного характеру, фортецю Беюрделен 26 січня 1806 року здали Карагеоргію. Ця фортеця на Саві була першим великим османським укріпленням, захопленим повстанцями, і провіщала падіння Белграда. Коли 1813 року повстання придушили й повернули Белград, фортеця теж повернулася під османське управління; проте за гарнізонною умовою фірману 1830 року Беюрделен разом із Белградом, Смедеревом і Фетхюлісслам (Кладово) визначили як одну з чотирьох фортець в автономній Сербії, де залишалося османське військо, і в цьому статусі вона перебувала, доки 1867 року гарнізон не вивели.", "092a75b8"]},
"OLAYLAR_EK10:1832-01-01:0":{"b": ["Ламія (Іздін) залишилася в межах Греції — лінія Арта — Волос", "930f63b8"], "d": ["1832 року північний кордон незалежної грецької держави провели по лінії від Артської до Волоської затоки. Іздін (Ламія), який за османської доби (1424-1832) був центром кази, підпорядкованої Евбейському (Негропонтському) санджаку, перейшов до Греції, бо залишався на південь від цієї лінії; решта Фессалії (Лариса, або Єнішехір, і Трикала) залишалася османською до 1881 року.", "577080e0"]},
"OLAYLAR_EK10:1877-04-24:0":{"b": ["Оголошення Росією війни — початок «Війни 93-го року» (російсько-турецької 1877-1878)", "ac548ab8"], "d": ["Придушення болгарського повстання 1876 року викликало в європейській громадській думці велике обурення, і Росія повною мірою використала це, щоб ізолювати Високу Порту. Коли Османська держава відхилила пропозицію Стамбульської (Константинопольської) конференції про поділ Болгарії на дві автономні провінції, а потім і Лондонський протокол від 31 березня 1877 року, Росія 24 квітня 1877 року оголосила війну, і її армія увійшла на землі князівства Румунія, яке вона схилила на свій бік (від цього моменту до Адріанопольського перемир'я карта показує Волощину та Молдавію під заштрихованим покривом російського наступу). Оскільки війна припала на 1293 рік за румійським календарем, її називають «Війною 93-го року». Бойові дії йшли на двох фронтах — дунайському та східноанатолійському: на Дунаї османська армія в 180 000 осіб вважала лівий берег річки першою лінією оборони, а Балканські гори — другою; на сході 55 000 воїнів Ахмеда Мухтара-паші зайняли позиції між Ардаганом і Догубаязитом. На карті ця війна — подія, що започаткувала крах османської Румелії: сучасні кордони Болгарії, Сербії, Чорногорії та Румунії всі є плодом цих п'ятнадцяти місяців.", "a71008f1"]},
"OLAYLAR_EK10:1877-05-21:0":{"b": ["Проголошення незалежності Румунії — кінець васальної залежності Волощини та Молдавії", "bdd164b3"], "d": ["Через два тижні після оголошення війни 93-го року князівство Румунія проголосило незалежність і вступило у війну на боці Росії; його участь в облозі Плевни стала вирішальною в поразці османів. Так фактично припинилася понад чотирьохсотлітня васальна залежність Волощини та Молдавії; незалежність дістала міжнародне визнання на Берлінському конгресі (1878). Від цієї дати карта показує Румунію не як васала, а як незалежну державу власного кольору. Із проголошенням незалежності вся Волощина та Молдавія (Ясси, Галац, Браїла, Джурджу, Калафат, Ботошані та ін.) стали незалежною Румунією.", "9e037d13"]},
"OLAYLAR_EK10:1877-06-27:0":{"b": ["Перехід російської армії через Дунай — падіння Свіштова та Тирнова", "811367b1"], "d": ["Росіяни, які з початком війни увійшли на румунські землі й схилили це князівство на свій бік, наступали двома колонами: одна в напрямку Добруджі, друга — Бухареста. Дунай форсували між Русе та Нікополем, і 27 червня взяли Свіштов, а 1 липня — давню болгарську столицю Тирново. Нікополь, евакуацію якого було наказано, але належно не виконано, теж після певного опору капітулював. Прорив першої лінії оборони за тиждень викликав у Стамбулі велику паніку; поширювалися навіть чутки про перенесення осередку султанату в Бурсу, а управління війною передали військовій раді, створеній у столиці.", "f266b11c"]},
"OLAYLAR_EK10:1877-07-19:0":{"b": ["Залишення Шипкинського перевалу — прорив балканської лінії", "1f45e50a"], "d": ["Османські сили на Шипці, найстратегічнішому з перевалів через Балканські гори, затято відбивали російські атаки; проте переконавшись, що зазнають поразки, 19 липня таємно залишили перевал. Так відкрилася й друга лінія оборони, і 22 липня генерал Гурко взяв Ескі-Загру (Стару Загору). Сулейман-паша, який наспів із чорногорського боку, хоч і розбив Гурка та повернув окуповані місця на південь від Балкан, попри атаки, що тривали з 21 серпня місяцями, не зміг повернути Шипку. На карті це означає, що єдність оборони між північчю та півднем Балканського хребта вже не вдалося відновити: відтоді боротьба на дунайському фронті зав'язалася вузлом під Плевною.", "3463a17b"]},
"OLAYLAR_EK10:1877-08-23:0":{"b": ["Ловеч окупувала російська армія", "70e54611"], "d": ["Під час війни 93-го року 5 червня 1877 року росіяни окупували Ловеч, а 15 червня османські сили під командуванням Рифата-паші відкинули їх; 23 серпня османи залишили місто, і воно знову опинилося під російською окупацією. Від цього дня до Берлінського договору карта показує Ловеч під російською окупацією (штрихуванням); юридично він залишається османською землею.", "45e61a80"]},
"OLAYLAR_EK10:1877-11-18:0":{"b": ["Падіння Карса — розвал східного фронту та редути Азізіє", "53fc3bf5"], "d": ["У Східній Анатолії росіяни, наступаючи трьома колонами на Карс, Догубаязит і Ардаган, 30 квітня взяли Догубаязит і увійшли в Ардаган, але під час походу на Ерзурум 15 липня зазнали поразки й були відкинуті за кордон. Цей успіх, що приніс Ахмеду Мухтару-паші титул «Ґазі», у серпні обернувся на протилежне, коли генерал Лазарєв знову перейшов у наступ, і 18 листопада Карс упав. Османські сили, що задля вигіднішої оборони відступили в Ерзурум, на редутах Азізіє чинили великий опір, оскільки Нене Хатун підняла населення. Через вісім місяців у Берліні Карс, Ардаган і Батум відійшли Росії в рахунок частини воєнної контрибуції.", "07faf844"]},
"OLAYLAR_EK10:1912-10-08:0":{"b": ["Початок Першої Балканської війни — оголошення війни Чорногорією", "c0c2697e"], "d": ["Балканські держави після того, як комітет «Єднання і поступ» законом від 3 липня 1911 року розв'язав питання церков, усунули найбільшу перешкоду між собою і, під підбурюванням Росії, упродовж 1912 року уклали між собою союзні договори (13 березня — Сербія та Болгарія, 29 травня — Болгарія та Греція, у серпні — Чорногорія та Болгарія, 6 жовтня — Чорногорія та Сербія). Висока Порта цього не помітила; навіть більше, покладаючись на гарантії Росії, вона демобілізувала 120 вишколених батальйонів у Румелії. 3 жовтня чотири держави вручили спільну ноту з вимогою автономії для Македонії, Албанії та Криту; не отримавши відповіді, 8 жовтня 1912 року з оголошенням війни Чорногорією вони почали бойові дії. 13 жовтня послам Сербії та Болгарії вручили паспорти, а наступного дня ці дві держави, а потім і Греція, оголосили війну. Під час війни політичні розбіжності в армії відіграли велику роль у поразці.", "33b60249"]},
"OLAYLAR_EK10:1912-10-20:0":{"b": ["У Родопах розбито Кирджалійський загін, Кирджалі впало", "8cf59b7f"], "d": ["Після оголошення Болгарією війни болгарські сили, що спустилися з Родоп, розбили Кирджалійський загін Мехмеда Явера-паші та увійшли в Кирджалі. Розгромлений загін відступив у напрямку Комотіні (Ґюмюльджіни); східну частину Родоп було втрачено в перший тиждень війни.", "c675e240"]},
"OLAYLAR_EK10:1912-10-23:0":{"b": ["Розгром Східної армії та відхід на Чаталджинську лінію — втрата Куманового та Салонік", "cf95591a"], "d": ["Османська Східна армія 23 жовтня 1912 року зазнала поразки від утричі чисельнішої болгарської армії та відступила аж до Чаталджинської лінії за тридцять кілометрів на захід від Стамбула; вже в перший місяць війни столиця опинилася під прямою загрозою. У ті самі дні, 23-24 жовтня, Західна армія зазнала поразки від сербів під Кумановим, а Тахсін-паша зі своїм 35-тисячним військом капітулював у Салоніках перед греками. Через ці розгроми 29 жовтня кабінет Ґазі Ахмеда Мухтара-паші подав у відставку; Абдул-Гаміда II, який жив у Салоніках на засланні, 1 листопада перевезли до Стамбула. Чаталджинську лінію утримали до кінця війни — п'ятсотлітній османський простір Румелії за кілька тижнів стиснувся до цієї вузької смуги.", "376c6d31"]},
"OLAYLAR_EK10:1912-10-23:1":{"b": ["Принц Александар увійшов у центр санджаку Новий Пазар", "326d0616"], "d": ["Сербські сили в перший тиждень війни взяли Новий Пазар і з'єдналися з чорногорськими силами, що наступали з заходу. Так Новопазарський санджак, який сто років розділяв Сербію та Чорногорію, перетворився на міст між двома союзницями.", "afe8a034"]},
"OLAYLAR_EK10:1912-10-24:0":{"b": ["Після битви під Киркклісе втрачено Киркларелі", "eda4c759"], "d": ["Після поразки Східної армії в битві під Киркклісе у Східній Фракії місто, яке боронив Кьолемен Абдуллах-паша, залишили болгарським силам. Місто звільнили від окупації, що тривала дев'ять місяців, лише під час Другої Балканської війни, 21 липня 1913 року.", "ee5cf8d2"]},
"OLAYLAR_EK10:1912-10-26:0":{"b": ["Скоп'є, центр Косовського вілаєту, залишено без опору", "455d9b71"], "d": ["Після розгрому під Кумановим (23-24 жовтня) Скоп'є, центр Косовського вілаєту, залишилося беззахисним. Оскільки мешканці не хотіли боїв навколо міста, сербські сили під командуванням принца Александара, запрошені через консулів, увечері 26 жовтня увійшли в місто без опору.", "3992a650"]},
"OLAYLAR_EK10:1912-10-28:0":{"b": ["Втрачено Велес (Кьопрюлю) на Вардарі", "73d20b7d"], "d": ["Через два дні після падіння Скоп'є сербська армія, наступаючи вздовж Вардару на південь, взяла Велес. Так ворота долини Вардару, що відкривалися на Салоніки, перейшли до рук сербів.", "e762a0e1"]},
"OLAYLAR_EK10:1912-10-29:0":{"b": ["Басейн Брегалниці: генерал Стефанович увійшов в Штип", "70a84256"], "d": ["Сербські частини під командуванням генерала Стефановича взяли Штип без опору; спочатку в місто увійшли нерегулярні чети. Після Куманового басейн Брегалниці у Східній Македонії перейшов під сербський контроль.", "3b2e609b"]},
"OLAYLAR_EK10:1912-10-29:1":{"b": ["Після перевалу Сарандапоро Верія (Караферьє) перейшла під грецьку владу", "02a68e02"], "d": ["Грецька армія, яка наступала з Фессалії на північ, подолавши перевал Сарандапоро (Киркгечіт), опанувала Верію. Частина мусульманського населення міста тоді залишила область.", "a76cea57"]},
"OLAYLAR_EK10:1912-10-31:0":{"b": ["Втрачено Водену (Едессу) на залізниці Салоніки — Бітола", "fc15b917"], "d": ["Водена на залізниці Салоніки — Бітола перейшла до рук грецької армії. Через насильницький відхід слов'янського та турецького населення чисельність мешканців міста невдовзі серйозно зменшилася.", "e28f0a57"]},
"OLAYLAR_EK10:1912-11-02:0":{"b": ["Битва під Єнідже — Єнідже-Вардар переходить до греків", "8f6cb76e"], "d": ["8-й зведений корпус Гасана Тахсіна-паші зазнав поразки від грецької армії під Єнідже на захід від Салонік і відступив у район Салонік. Під час битви більша частина містечка згоріла; шлях на Салоніки відкрився грецькій армії.", "d0f12da4"]},
"OLAYLAR_EK10:1912-11-03:0":{"b": ["Прізрен на південному заході Косова капітулював", "bae6b1b9"], "d": ["Прізрен на південному заході Косова капітулював перед сербськими силами. Поведінку частин, що увійшли в місто, щодо мусульманського населення зафіксовано як одну з найтяжчих сторінок війни в Косові.", "8cf0b7ae"]},
"OLAYLAR_EK10:1912-11-05:0":{"b": ["Полковник Мітов оголосив воєнний стан в Струмиці", "bcad75cc"], "d": ["Болгарський полковник Мітов увійшов у Струмицю та оголосив воєнний стан; наступного дня, від'їжджаючи, залишив містечко болгарському каймакаму та сербському командирові. Під час війни Струмиця переходила з рук у руки між союзниками, а 1913 року її приєднали до Болгарії.", "acfc04ac"]},
"OLAYLAR_EK10:1912-11-08:0":{"b": ["Гасан Тахсін-паша залишив Салоніки грекам", "1738933c"], "d": ["Гасан Тахсін-паша, який після поразки під Єнідже відступив у Салоніки, залишив місто грекам, коли з півночі наближалася болгарська армія; 8 листопада близько полудня грецька армія увійшла в місто. Так було втрачено Салоніки — найбільше портове місто османської Румелії та місце народження комітету «Єднання і поступ».", "e65f92fc"]},
"OLAYLAR_EK10:1912-11-21:0":{"b": ["Комотіні, центр Західної Фракії, відкрилося болгарам", "96eec25f"], "d": ["Коли загін Явера-паші, що відступав із Кирджалі, відійшов у бік Фере, Комотіні капітулювало перед болгарськими силами. Центр Західної Фракії був одним із перших серед земель, які наприкінці війни мали відійти Болгарії.", "dab74d84"]},
"OLAYLAR_EK10:1912-11-28:0":{"b": ["Серби, що дісталися Ельбасана, того самого дня увійшли в Дебар", "16720246"], "d": ["Сербські сили, наступаючи з Бітоли на захід, того дня, коли дісталися Ельбасана, увійшли й у Дебар і спустилися в напрямку Адріатики. Того самого дня у Вльорі проголошували незалежність Албанії.", "6e52cff7"]},
"OLAYLAR_EK11:1401-01-01:0":{"b": ["Тимур удруге захопив Багдад — аббасидські квартали міста зруйновано", "04b68a24"], "d": ["Тимур двічі, з перервою у вісім років, брав Багдад. Під час першої окупації 1393 року місто не зазнало великої шкоди; друга, 1401 року, вважається другим тяжким ударом по культурному життю Багдада — населення вирубали, а більшість кварталів і споруд аббасидської доби зруйнували. Джалаїридський правитель Ахмед, повернувшись у місто 1405 року, хоч і намагався відбудувати зруйновані мури та базари, але не мав на це часу; 1410 року Багдад перейшов до рук туркменів Кара-Коюнлу. Ці дві окупації — один із найвідчутніших кроків, які показують, наскільки близько Тимур підійшов до османських і мамлюцьких кордонів на шляху до Ангорської битви.", "b24ba76b"]},
"OLAYLAR_EK11:1422-01-01:0":{"b": ["Джунейд-бей повернувся на чолі Айдин-елі — Айдиніди знову незалежні", "63281658"], "d": ["Челебі Мехмед, узявши 1414-1415 року Ізмір і відправивши Джунейд-бея санджакбеєм у Нікополь, підпорядкував Айдин-елі османському управлінню. Після смерті Челебі Мехмеда Джунейд знову з'явився на сцені при Мустафі Челебі, якого Візантія висунула претендентом на престол, і навіть був у нього візиром. Мурад II відірвав його від цього союзу, пообіцявши повернути колишній бейлік; Джунейд повернувся в Ізмір, захопив Аясулук і, вбивши Мустафу-бея з Айдинідів, став на чолі бейліку. Так Айдин-елі з кризи Мустафи-самозванця народився вже поза османським управлінням.", "c5020860"]},
"OLAYLAR_EK11:1426-01-01:0":{"b": ["Страта Джунейд-бея та його родини — кінець бейліку Айдинідів", "efa684ba"], "d": ["Через те що Джунейд-бей, знову запанувавши в Айдин-елі, підбурював анатолійських беїв і шукав контактів із Венецією, Мурад II послав проти нього бейлербея Анатолії Хамзу-бея. Коли його сина Курда Гасана розбили поблизу Акхісара й узяли в полон, Джунейд відступив в Іпсілі навпроти острова Самос; не дочекавшись очікуваної допомоги від караманського правителя та опинившись у морській блокаді генуезців, які діяли разом з османами, він змушений був здатися, і його знищили разом з усім родом. Так землі Айдинідів повністю перейшли під османське управління.", "662b578c"]},
"OLAYLAR_EK11:1502-01-01:0":{"b": ["Ерзурум і басейн Вану перейшли до Сефевідів — північний фланг Ак-Коюнлу обвалився", "b418875f"], "d": ["Шах Ісмаїл, який, розбивши Ельванд-бея під Шаруром, улітку 1501 року увійшов у Тебріз, наступного року, наступаючи на північний захід, підкорив смугу від Ерзурума до басейну озера Ван. Держава Ак-Коюнлу після смерті Узун-Хасана вже була розколота навпіл боротьбою за престол: Ельванд-бей тримав Азербайджан і Діярбекір, а його двоюрідний брат Мурад — Перський Ірак і Фарс. Цей розкол полегшив сефевідське просування; область за один рік змінила власника. Ерзурум відтоді шістнадцять років залишався в сефевідських руках і перейшов під османську владу лише після Чалдирана, 1518-1519 року. Цього року (1502) Ашкале та Пасінлер (Хасанкале) разом з областю Ерзурума перейшли від Ак-Коюнлу до Сефевідів (день не підтверджено).", "2f80b39d"]},
"OLAYLAR_EK11:1503-01-01:0":{"b": ["Поразка Мурад-бея під Хамаданом: Перський Ірак і Фарс перейшли до Сефевідів", "8de07a31"], "d": ["Другий претендент на ак-коюнлуський престол султан Мурад зазнав тяжкої поразки в битві проти шаха Ісмаїла поблизу Хамадана й утік у Багдад. Унаслідок цієї єдиної битви області Перського Іраку, Фарсу та Кермана перейшли під сефевідське управління; на карті ці області змінюють власника одночасно. Це найбільший окремий крок у розпаді держави Ак-Коюнлу — утрата Тебріза залишила династію без столиці, а поразка під Хамаданом — без землі.", "f9d2ba4d"]},
"OLAYLAR_EK11:1504-12-06:0":{"b": ["Шах Ісмаїл увійшов у Єзд: упав останній оплот залишків Ак-Коюнлу в центральному Ірані", "6f9835df"], "d": ["Хоча після поразки під Хамаданом 1503 року Перський Ірак і Фарс перейшли до Сефевідів, Єзд залишався окремо в руках Мурад-бея з байандуридської династії Ак-Коюнлу. Місто впало після місячної облоги, і останній ак-коюнлуський острів у центральному Ірані зник. Запис TDV: «Шах Ісмаїл увійшов у місто 28 джумада аль-ахіра 910 року (6 грудня 1504) після місячної облоги».", "577a0ec7"]},
"OLAYLAR_EK11:1507-01-01:0":{"b": ["Діярбекірський похід шаха Ісмаїла: упали останні центри Ак-Коюнлу", "b6d8504e"], "d": ["Шах Ісмаїл, захопивши Азербайджан та Іранське плато, 1507 року повернув на захід, в область Діярбекіра, де народилася династія Ак-Коюнлу. Смуга від Аміда до Мардіна та від Урфи до Харпута двома ударами перейшла під сефевідське управління, і Ак-Коюнлу фактично зникли. Цей похід також уперше впер сефевідський кордон в османський і мамлюцький; так склалася географічна основа напруги, що привела до Чалдирана.", "d0346bf4"]},
"OLAYLAR_EK11:1508-01-01:0":{"b": ["Перехід Багдада до Сефевідів — Арабський Ірак змінив власника", "39730186"], "d": ["Услід за ак-коюнлуським султаном Мурадом, який після поразки під Хамаданом сховався в Багдаді, шах Ісмаїл 1508 року увійшов в Арабський Ірак і взяв Багдад. Перехід усипалень у Кербелі та Неджефі під сефевідське управління був для конфесійних претензій руху настільки ж важливим, як і взяття Тебріза. На карті Арабський Ірак змінює власника того самого дня; це останній і найширший географічний крок розпаду. Багдад залишався в сефевідських руках до Походу на два Іраки Сулеймана Законодавця 1534 року.", "10e3e563"]},
"OLAYLAR_EK11:1510-12-02:0":{"b": ["Битва під Мервом: узбеки зазнали тяжкої поразки, взято Мерв і Герат", "f8e45aaf"], "d": ["Шах Ісмаїл, який на заході завершив освоєння спадщини Ак-Коюнлу, рушив на схід, у Хорасан, і під Мервом завдав узбекам тяжкої поразки; Шейбані-хан загинув на полі бою. Мерв і Герат перейшли під сефевідську владу, і держава Сефевідів дістала кордони від Євфрату до Амудар'ї. Так процес, що почався зі вступу в Тебріз улітку 1501 року, завершився за дев'ять років: спадщина Ак-Коюнлу цілком перейшла під сефевідське управління, а Османська держава на сході стала сусідом другої держави власного масштабу.", "ae88b613"]},
"OLAYLAR_EK11:1539-02-24:0":{"b": ["Остаточний перехід Забіда під османську владу", "ddd971c7"], "d": ["Флот, який 5 листопада 1538 року зняв облогу Діу, на зворотному шляху зайшов на єменське узбережжя, і Забід остаточно підпорядкували османському управлінню; Хадим Сулейман-паша залишив місто 10 березня 1539 року й 1 квітня прибув у Джидду. З 1517 року містом управляли колишні мамлюцькі беї від імені османів; від цієї дати воно перейшло під пряме управління.", "5718f027"]},
"OLAYLAR_EK11:1581-04-16:0":{"b": ["Іберійська унія: португальська корона перейшла до короля Іспанії", "1cc6dfdc"], "d": ["Боротьба за спадщину, що почалася після смерті бездітного короля-кардинала Енріке, закінчилася на користь Іспанії битвою при Алькантарі (25 серпня 1580), і португальські кортеси, зібрані в Томарі, 16 квітня 1581 року визнали Філіпа II королем Португалії. За Томарськими умовами Португалія мала зберегти власні інституції, гроші та мову, на управлінські посади призначали б лише португальців, а в Мадриді діяла б окрема португальська рада — тобто об'єднання було особистою унією, а не анексією.", "40bd79df"]},
"OLAYLAR_EK11:1640-12-01:0":{"b": ["Реставрація (Restauração): Португалія повернула незалежність", "64ec0738"], "d": ["У дні, коли Іспанію займало каталонське повстання, група вельмож у Лісабоні напала на палац, повалила іспанське управління та проголосила королем герцога Браганського під іменем Жуана IV. Так закінчилася шістдесятирічна Іберійська унія; проте Сеута вирішила залишитися в Іспанії, і це визнали Лісабонським договором 1668 року. Цей проміжок, коли Португалія була втягнута у війни Габсбургів, є також рамкою її втрат в Азії: Ормуз було втрачено 1622 року, Малакку — 1641 року, Коломбо — 1656 року; Танжер і Бомбей як ціну незалежності віддали Англії. Джерело: Britannica, History of Portugal — Restoration.", "bb04bea3"]},
"OLAYLAR_EK11:1662-01-30:0":{"b": ["Танжер передано Англії", "1f7cad6d"], "d": ["Друга стаття шлюбного договору (23 червня 1661), укладеного, щоб забезпечити англійську підтримку в португальській війні за незалежність, віддавала Танжер Англії як посаг Катерини Браганської. Ескадра графа Сендвіча стала на якір 29 січня 1662 року, а наступного дня під час церемонії графа Пітерборо відбулася офіційна передача. 1684 року англійці залишили місто.", "9328c723"]},
"OLAYLAR_EK11:1747-06-20:0":{"b": ["Убивство Надір-шаха — розпад влади Афшаридів", "19c218c0"], "d": ["Надір-шаха, який поклав край престолу Сефевідів і 1736 року проголосив султанат на власне ім'я, під час індійського походу дійшов до Делі та після трьох воєн з османами уклав мир за Керденським договором 1746 року, убили в наметі його власні охоронці. Після цього Іраном не вдавалося управляти з одних рук: залишки Афшаридів у Хорасані, Зенди на півдні та Каджари, які підіймалися на півночі, сорок дев'ять років ділили країну. Завдяки цій роздробленості східний кордон османів довго залишався спокійним. Надір-шаха вбили 20 червня 1747 року; за TDV, Реванське (Єреванське) ханство було засноване того самого року (1747), день не підтверджено.", "75fd6ab9"]},
"OLAYLAR_EK11:1796-01-01:0":{"b": ["Утвердження влади династії Каджарів в Ірані", "744b48c5"], "d": ["Вождь племені каджарів Ага Мухаммад-хан повалив владу Зендів, зламав і останній опір Афшаридів у Хорасані, знову зібрав Іран в одних руках і зробив Тегеран столицею. Так закінчилася сорокадев'ятирічна доба роздробленості; відтоді східним сусідом османів до 1923 року був каджарський Іран. За «Енциклопедією ісламу» TDV, 1796 року афшаридський правитель Шахрух вийшов назустріч Аге Мухаммад-шаху під Мешхедом, і місто перейшло під владу Каджарів (день у джерелі відсутній).", "755b544a"]},
"OLAYLAR_EK12:1527-09-23:0":{"b": ["Фердинанд захопив Буду — Запольяї вигнано зі столиці", "99f77c29"], "d": ["Після Мохача на угорський престол з'явилося два королі: частина знаті обрала Яноша Запольяї, частина — Фердинанда Габсбурга. 1527 року Фердинанд захопив Буду і вигнав Запольяї зі столиці; Запольяї попросив допомоги в султана Сулеймана. Саме тому першою ціллю віденського походу 1529 року була Буда.", "e45db1f0"]},
"OLAYLAR_EK12:1537-01-01:0":{"b": ["Похід Барбаросси на егейські острови — Наксоське герцогство опинилося під османським контролем", "722b2fea"], "d": ["Наксоське герцогство, яким від 1207 року під венеційським сюзеренітетом правили латинські герцоги, внаслідок острівного походу Барбаросси Хайреддіна-паші перейшло під османський контроль. Статус острова не змінили; герцогство проіснувало далі як васал Османської держави, а за османсько-венеційським договором 1540 року право верховенства офіційно передано османам.", "e20e29f9"]},
"OLAYLAR_EK12:1560-03-12:0":{"b": ["Хрестоносний флот захопив Джербу — базу Турґута-паші втрачено", "f41b3f2a"], "d": ["Хрестоносний флот, складений з іспанських, папських, мальтійських, генуезьких і флорентійських кораблів, обрав ціллю Джербу, яку Турґут-реїс від 1551 року використовував як базу для набігів. Через бурі та епідемію він зміг дістатися до острова лише на початку 1560 року; 12 березня 1560 року він захопив острів і збудував там фортецю. Отримавши звістку, Піяле-паша 28 березня вирушив зі Стамбула з флотом зі 120 галер. Окупація тривала недовго: у травні османський флот переміг союзників біля Джерби, а наприкінці липня було повернуто й фортецю. Цей похід став початком другої великої морської операції після Превези, яка зміцнила османську перевагу в Середземномор'ї.", "a420585e"]},
"OLAYLAR_EK12:1560-07-30:0":{"b": ["Падіння фортеці Джерба — перехід острова під османське управління", "f1efc0df"], "d": ["Після морської перемоги Піяле-паші 14 травня 1560 року хрестоносні сили замкнулися у фортеці, яку вони збудували на острові; війська бейлербея Триполі Турґута-паші взяли її в облогу з суходолу. Двомісячна облога завершилася 30 липня 1560 року падінням фортеці, і острів приєднали до Триполітанського бейлербейліку. Між морською перемогою та взяттям фортеці минуло сімдесят сім днів; фактично острів перейшов з рук у руки не 14 травня, а 30 липня.", "50b148da"]},
"OLAYLAR_EK12:1814-02-04:0":{"b": ["Російсько-прусське двовладдя в Данцигу завершилося — вільне місто Наполеона повернулося до Пруссії", "1ccda4d2"], "d": ["Данциг, який за Тільзітським миром (9 липня 1807) відокремили від Пруссії і зробили вільним містом під французьким протекторатом, наполеонівські війська залишили після облоги 1813 року. Від 2 січня до 4 лютого 1814 року в місті тривало російсько-прусське двовладдя; коли цар Олександр відмовився від плану захопити Данциг і гирло Вісли, місто перейшло під прусське управління.", "8d215059"]},
"OLAYLAR_EK12:1815-05-03:0":{"b": ["У Відні Краків проголошено вільним, незалежним і нейтральним містом", "19eea839"], "d": ["На Віденському конгресі Росія, Австрія та Пруссія зробили місто Краків разом з околицями вільною державою під опікою трьох держав; Заключний акт Віденського конгресу закріпив цей устрій.", "21a6fe2b"]},
"OLAYLAR_EK12:1893-01-01:0":{"b": ["Борну потрапило під владу Рабіха ібн Зубайра", "8be4ca96"], "d": ["Суданський воєначальник Рабіх ібн Зубайр, який уже похитнув Багірмі та Вадаї, захопив Борну; до 1896 року він оволодів усією країною і зробив своїм центром Дікву.", "466276f3"]},
"OLAYLAR_EK12:1900-04-22:0":{"b": ["Рабіх ібн Зубайр зазнав поразки від французів і загинув — його влада в Борну розпалася", "fb5a3ace"], "d": ["Переможеного французькою колоніальною армією Рабіха було вбито; хоча його син намагався зберегти владу, втриматися він не зміг, і 1902 року Борну поділили між Францією, Англією та Німеччиною.", "15789829"]},
"OLAYLAR_EK12:1913-08-31:0":{"b": ["Проголошено Тимчасовий уряд Західної Фракії з центром у Гюмюльджіне", "974b2e28"], "d": ["Коли Бухарестський мирний договір (10 серпня 1913) залишив Західну Фракію Болгарії, турецьке населення краю проголосило тимчасовий уряд з центром у Гюмюльджіне; після взяття Дедеагача уряд оголосив свою незалежність під назвою «Незалежний уряд Західної Фракії». Через втручання великих держав османський уряд його не підтримав; Константинопольський мирний договір 29 вересня 1913 року залишив Західну Фракію болгарам, і уряд проіснував лише п'ятдесят сім днів, до 25 жовтня 1913 року.", "86d3bfee"]},
"OLAYLAR_EK13:1362-03-01:0":{"b": ["Смерть Орхана Газі — кінець сорокаліття переходу від бейліку до держави", "62c59cfd"], "d": ["Орхан Газі, який очолив бейлік після смерті Османа Газі 1324 року, за тридцять вісім років правління перетворив османський прикордонний бейлік на державу, що утвердилася на обох берегах Мармурового моря: було взято Бурсу (1326), Ізнік (1331) та Ізміт (1337), приєднано бейлік Каресі, викарбувано перше акче (1327), засновано перше медресе в Ізніку (1331), а переправа в Румелію через Чимпе (1352) і Галліполі (1354) стала постійною. Свого старшого сина Сулеймана-пашу, який керував завоюваннями в Румелії, він втратив 1357 року через нещасний випадок на полюванні; сам він помер у Бурсі в березні 1362 року, а його наступником став син Мурад I.", "9208e381"]},
"OLAYLAR_EK13:1417-01-01:0":{"b": ["Перехід островів Бахрейну в руки Джабридів", "6a242b16"], "d": ["У статті TDV про Бахрейн зазначено, що острів «послідовно перебував під управлінням Уюнідів, Салгуридів, Табідів і Джабридів, а за доби Джабридів більшість населення перейшла з шиїзму в сунізм»; жодному з цих періодів дати не наведено. У загальній літературі династію Джабридів вважають заснованою на початку XV століття після повалення останнього джарванідського правителя в Катіфі; в пору найбільшого розквіту (Аджвад ібн Заміль, пом. 1496) вона контролювала все арабське узбережжя Перської затоки, аль-Хасу, Катіф і острови Бахрейну. Після Аджвада острови Аваль перейшли до Мукріна ібн Заміля — саме цей правитель зазнає поразки від португальців 1521 року.", "0c4cdac7"]},
"OLAYLAR_EK13:1471-08-24:0":{"b": ["Взяття Арзіли португальцями — другий плацдарм на марокканському узбережжі", "83444a11"], "d": ["Афонсу V особисто висадився на узбережжі Марокко з 30-тисячним військом і флотом із 400 суден та 24 серпня 1471 року взяв Арзілу, що перебувала під управлінням Ваттасидів. Падіння міста зламало опір Танжера; через чотири дні, 28 серпня, Танжер здався без бою. Так Португалія після Сеути (1415) і Ксар-ес-Сегіра (1458) закріпила свої третю та четверту позиції на атлантичному узбережжі Марокко; після цього походу король наказав додати до свого титулу слова «володар Африки».", "ec8d27f5"]},
"OLAYLAR_EK13:1488-01-01:0":{"b": ["Сафі потрапляє під португальський вплив", "765e703e"], "d": ["Сафі, найжвавіший зерновий і рибальський порт атлантичного узбережжя, 1488 року потрапив під португальський вплив; якийсь час містом керували місцеві правителі під португальським протекторатом, а 1508 року його було прямо окуповано. Оскільки джерела по-різному оцінюють ці два етапи, початкова дата коливається між 1488 і 1508 роками; обидві є крайніми точками того самого процесу. Сафі залишався в португальських руках п'ятдесят три роки і був евакуйований 1541 року після падіння Агадіра.", "51aa6746"]},
"OLAYLAR_EK13:1505-01-01:0":{"b": ["Заснування Санта-Круш-ду-Кабу-де-Ге — португальська фортеця в Агадірі", "cc22c433"], "d": ["Фортецю Санта-Круш-ду-Кабу-де-Ге, засновану приватним коштом на узбережжі Сусу в пункті, куди Португалія доти не доходила, збудували 1505 року, а 1513 року передали португальській короні. Контролюючи торгівлю цукром і золотом долини Сус, фортеця перекривала південно-західний вихід із Марракеша; тому вона стала першою великою ціллю саадитського руху. Облогу 1533 року відбили, а облога 1541 року виявилася успішною й поклала початок краху Португалії в Марокко.", "6d42d1d3"]},
"OLAYLAR_EK13:1513-09-03:0":{"b": ["Взяття Аземмура — контроль над гирлом Умм-ер-Рбія", "232acd4b"], "d": ["3 вересня 1513 року португальське військо під командуванням Жайме, герцога Браганси, без опору увійшло до Аземмура в гирлі річки Умм-ер-Рбія. Взяття міста дало контроль і над гирлом річки, і над хлібним шляхом, що вів у внутрішні землі, а наступного року відкрило шлях до заснування фортеці Мазаган за 12 км на південний захід. Аземмур залишався в португальських руках двадцять вісім років.", "8ac983da"]},
"OLAYLAR_EK13:1514-01-01:0":{"b": ["Заснування фортеці Мазаган — португальська позиція, що протримається в Марокко найдовше", "786cdb40"], "d": ["Наступного року після взяття Аземмура, влітку 1514 року, на узбережжі збудували фортецю Мазаган. Після загального краху 1541 року Португалія, залишаючи всі свої позиції в Марокко, Мазаган не залишила; навпаки, вона наново перебудувала фортецю з бастіонами італійського типу, і місто утримували двісті п'ятдесят п'ять років. Відбили й велику облогу 1562 року. Мазаган як остання португальська позиція в Марокко буде евакуйований 1769 року.", "fe42a1e2"]},
"OLAYLAR_EK13:1517-05-01:0":{"b": ["Здача фортеці Мардін — кінець сефевідського опору на південь від Діярбакира", "e6226de5"], "d": ["Коли Биїклі Мехмед-паша, який після Чалдирана виступив у край Діярбакира, взяв в облогу Мардін, сефевідські сили в жовтні 1515 року відійшли до фортеці; хоча місто перейшло в османські руки, фортеця чинила опір. Контрнаступ сефевідського намісника Кара-хана, який отримав підкріплення, завершився битвою при Кочхісарі (Кизилтепе) в травні 1516 року: у бою, що тривав увесь день на рівнині Деде-Гаркин, Кара-ханові відтяли голову, а його військо розсіялося. Фортеця ж, за словами TDV, здалася «лише через дев'ять місяців».", "791d1c1c"]},
"OLAYLAR_EK13:1521-01-01:0":{"b": ["Взяття Бахрейну Португалією — кінець влади Джабридів", "315a435a"], "d": ["Коли джабридський правитель Мукрін ібн Заміль відмовився платити данину Ормузу, на острові висадилися португальський флот і війська залежного від Португалії Ормузького королівства; Мукрін зазнав поразки в бою, і 1521 року Бахрейн перейшов під португальське управління. Відтоді вісімдесят років островом керували через Ормуз, здебільшого руками сунітських іранських намісників. Перли Бахрейну та його стратегічне розташування зроблять острів прямою ціллю османсько-португальського суперництва в затоці.", "34a37f50"]},
"OLAYLAR_EK13:1541-03-12:0":{"b": ["Падіння Агадіра — Саадити починають витісняти Португалію з Марокко", "bb1568f6"], "d": ["Саадитський султан Мухаммед аш-Шейх 16 лютого 1541 року взяв в облогу фортецю Санта-Круш і 12 березня захопив її; в полон потрапило близько шестисот португальців, зокрема губернатор Гутерре де Монрой.", "af3555a6"]},
"OLAYLAR_EK13:1541-10-01:0":{"b": ["Евакуація Сафі та Аземмура — Португалія відходить з атлантичного узбережжя", "4cb6099a"], "d": ["Після падіння Агадіра 12 березня 1541 року і невдачі з укладенням сподіваного союзу з марокканським султаном Жуан III наказав евакуювати дві великі позиції на атлантичному узбережжі; евакуацію Сафі та Аземмура завершили восени 1541 року, у вересні—жовтні. Таким чином, за один рік було втрачено три позиції, і п'ятдесятилітня португальська експансія на марокканському узбережжі повернула назад; залишилися Сеута, Танжер, Арзіла, Ксар-ес-Сегір і щойно укріплений Мазаган.", "e6d4728d"]},
"OLAYLAR_EK13:1549-01-01:0":{"b": ["Евакуація Арзіли — Португалія звужує своє північне узбережжя", "b5d18373"], "d": ["Під поєднаним тиском фінансової кризи та Саадитів Жуан III евакуював Арзілу, яку утримували від 1471 року. Так португальська присутність у Марокко звелася до Сеути, Танжера та Мазагана. Арзілу ненадовго знову займуть 1577 року, а 1589 року остаточно залишать.", "36c1d8e6"]},
"OLAYLAR_EK13:1559-01-01:0":{"b": ["Османський похід на Бахрейн — останній великий крок проти Португалії в затоці", "14501df3"], "d": ["Османська держава, яка після анексії Басри 1546 року та створення еялету Лахса (аль-Хаса) закріпилася на арабському узбережжі затоки, виступила на Бахрейн під командуванням бейлербея Лахси Мустафи-паші, маючи на меті торгівлю перлами острова та португальську ормузьку лінію. Щодо результату походу джерела розходяться: Ісламська енциклопедія TDV пише, що османи «1559 року захопили Бахрейн і створили там базу», а острови «згодом знову перейшли під португальське управління»; натомість західна література фіксує, що облога зазнала невдачі, португальські підкріплення, які прибули морем з Ормуза, відбили османські сили, а після епідемії чуми, що викосила обидві сторони, османи попросили умов капітуляції. Обидві версії розходяться в самому результаті; спільним є те, що Бахрейн не залишився надовго в османських руках.", "b35d131f"]},
"OLAYLAR_EK13:1569-01-01:0":{"b": ["Взяття Тунісу Улуджем Алі-пашею — кінець хафсидсько-іспанського порядку", "d4498698"], "d": ["Коли Карл V 1535 року взяв Туніс, він не правив містом сам, а повернув на престол хафсидського султана Мулая Хасана; за словами TDV, місто Туніс залишалося «під іспанською опікою та під управлінням Мулая Ахмада III аж до другого втручання османів 1569 року». Улудж Алі, призначений 27 червня 1568 року бейлербеєм Алжиру, виступив суходолом на Туніс, переміг хафсидського султана біля Беджі та увійшов до міста; Мулай Ахмад сховався в іспанському пресидіо Ла-Гулетта. Так затоку було поділено надвоє — місто османське, портова фортеця іспанська, — і цей поділ тривав чотири роки.", "32206b3e"]},
"OLAYLAR_EK13:1573-10-10:0":{"b": ["Повернення Тунісу доном Хуаном Австрійським — єдиний сухопутний відгук Лепанто", "a6f044ee"], "d": ["Хоча після Лепанто (1571) Священна ліга розпалася, Іспанія самотужки натиснула на Північну Африку: за словами TDV, «10 жовтня 1573 року іспанці розпочали нову операцію з метою встановити контроль над Тунісом. Вони взяли Туніс і залишили там 8000 солдатів». Ця операція під командуванням дона Хуана Австрійського — єдине місце, де перемога при Лепанто мала відгук на суходолі; проте вона виявилася нетривкою, і через одинадцять місяців місто було повернуто. Окупація повалила вже налагоджене османське управління: 2 зу-ль-хіджа 980 року (5 квітня 1573) командувачем Тунісу був Килич Алі-паша, його каймакамом — Рамазан-паша, а бейлербеєм — Хайдар-паша.", "f7f9ab56"]},
"OLAYLAR_EK13:1602-01-01:0":{"b": ["Сефевіди забирають Бахрейн у Португалії", "c37d982c"], "d": ["Сили, надіслані шахом Аббасом I, об'єдналися з повстанцями на острові та вибили португальський гарнізон із фортеці; за словами TDV, острови відібрали в португальців «1602 року сили, залежні від Ірану». Так Бахрейн після вісімдесяти одного року португальського управління перейшов під владу Сефевідів і сто п'ятнадцять років залишався залежним від Ірану. Це перша ланка в розпаді португальських позицій у затоці; через двадцять років і сам Ормуз паде внаслідок спільної англо-іранської операції.", "19e58d88"]},
"OLAYLAR_EK13:1717-01-01:0":{"b": ["Вторгнення оманців на Бахрейн — кінець сефевідської влади", "c9be5820"], "d": ["Під час розпаду в останні роки держави Сефевідів на острів вторгся оманський флот під управлінням династії Яаруба, і сефевідській владі настав кінець. Наступні тридцять п'ять років — найбурхливіший період в історії затоки: острів кілька разів переходив з рук у руки між Оманом, Іраном та місцевими арабськими силами.", "b0c7f671"]},
"OLAYLAR_EK13:1753-01-01:0":{"b": ["Бахрейн переходить під управління бушерського роду Аль Мазкур", "610e2f9d"], "d": ["Родина Аль Мазкур, родом з Оману, що оселилася в Бушері та належала до хувалів, 1753 року, діючи зі своїх баз у Бушері, підпорядкувала Бахрейн своєму управлінню. Родина очолювала арабські громади на іранському узбережжі затоки та керувала островом від імені Ірану; її останній представник, Наср Аль Мазкур, був призначений намісником Бахрейну урядом Зендів. Це останнє управління островом перед Аль Халіфа.", "7cc5fed2"]},
"OLAYLAR_EK13:1769-03-11:0":{"b": ["Евакуація Мазагана — пала остання португальська позиція в Марокко", "f9e9749d"], "d": ["Гарнізон із 592 осіб не зміг встояти перед облогою, яку на початку 1769 року розпочав алавітський султан Мухаммед III ібн Абдаллах; евакуаційна флотилія, що вийшла з Лісабона 1 лютого, 11 березня 1769 року прийняла на борт останніх солдатів, а останнім місто залишив губернатор Дініш Грегоріу. Так португальська присутність у Марокко, розпочата взяттям Сеути 1415 року, закінчилася через три з половиною століття. Мазаган був єдиною позицією на атлантичному узбережжі, яку утримали після загального краху 1541 року, і з двомастами п'ятдесятьма п'ятьма роками став місцем, яке Португалія втримувала в Марокко найдовше.", "c0ad57bc"]},
"OLAYLAR_EK13:1783-01-01:0":{"b": ["Завоювання Бахрейну родом Аль Халіфа — заснування династії, що править донині", "8773b011"], "d": ["Наср Аль Мазкур, намісник Зендів у Бахрейні, взяв в облогу Зубару на півострові Катар; сили утубів під командуванням Ахмада ібн Мухаммада ібн Халіфи прорвали облогу, перейшли в контрнаступ і того ж року взяли Бахрейн. Запис TDV стислий: «1783 року Бахрейн перейшов під владу Аль Халіфа з племені утуб». Після цієї перемоги Ахмада ібн Мухаммада прозвали «аль-Фатіх» (Завойовник), а заснована ним династія править островом донині.", "470bd22f"]},
"OLAYLAR_EK13:1861-05-21:0":{"b": ["Договір Бахрейну з Англією — вступ у систему протекторату в затоці", "576796b2"], "d": ["За записом TDV, «21 травня 1861 року Англія та Алі, брат шейха Мухаммада, який представляв Бахрейн, підписали угоду, що забороняла в регіоні работоргівлю та піратство»; в англійських документах той самий договір (Perpetual Truce of Friendship and Peace) датовано 31 травня 1861 року. Договір є першою ланкою системи протекторату, яка підпорядкувала зовнішні відносини Бахрейну Англії, і острів залишався поза цим порядком і після того, як 1871 року османи знову закріпилися в аль-Хасі та Катіфі.", "ab2ad5ff"]},
"OLAYLAR_EK14:1281-01-01:0":{"b": ["Ахі Евран — засновник-покровитель організації ахі", "3392e100"], "d": ["Ахі Еврана вважають одним із засновників організації ахі в Анатолії та святим покровителем чинбарів (шкіряників). Його завія в Киршехірі як духовний центр османської ремісничо-цехової організації проіснувала до початку XX століття; держава офіційно підтверджувала цей статус 1780, 1782, 1822—1823 та 1842 року.", "caa063df"]},
"OLAYLAR_EK14:1326-01-01:0":{"b": ["Шейх Едебалі — засновницький зв'язок між ахі та османською династією", "c1186059"], "d": ["Едебалі, який заснував завію в Біледжіку і був також шейхом організації ахі, за переказом витлумачив знаменитий сон Османа Газі; після цього Осман Газі одружився з донькою Едебалі Мальхун-хатун. Едебалі також вважають першим османським кадієм і муфтієм.", "60c970e5"]},
"OLAYLAR_EK14:1330-06-01:0":{"b": ["Орхан Газі після завоювання Бурси дарує вакуфом поле для гри в джирид", "da1becbd"], "d": ["За статтею TDV «Джирид», Орхан Газі після завоювання Бурси передав як вакуф поле в околицях для кінних перегонів та гри в джирид; це один із перших задокументованих прикладів інституціалізації гри в джирид в османів.", "f099d0d8"]},
"OLAYLAR_EK14:1357-06-01:0":{"b": ["Початок борцівських змагань у Киркпинарі за переказом", "2d93fa65"], "d": ["За переказом, традиція киркпинарської боротьби почалася зі змагань між сорока газі, які переправилися разом із завойовником Румелії Сулейманом-пашею. Статті TDV «Боротьба» та «Киркпинар» наводять цей переказ, але точної дати заснування не подають.", "a7dedab7"]},
"OLAYLAR_EK14:1362-06-01:0":{"b": ["Заснування корпусу яничарів", "f4206dce"], "d": ["Систему, яка за порадою Чандарли Кара Халіла та мулли Рустема почалася з вишколу юнаків-немусульман, узятих з-поміж військовополонених за законом пенчик, за правління Мурада I було інституційно оформлено через корпус аджемі-огланів, заснований у Галліполі.", "4842eade"]},
"OLAYLAR_EK14:1402-01-01:0":{"b": ["Початок будівництва Старої мечеті (Великої мечеті) в Едірне", "da7a22ac"], "d": ["Будівництво Старої мечеті (Ескіджамі), відомої в народі також як Улуджамі (Джамі-і Атік), розпочав емір Сулейман Челебі 1402—1403 року.", "0f5a6b9d"]},
"OLAYLAR_EK14:1414-01-01:0":{"b": ["Початок будівництва комплексу Зеленої мечеті в Бурсі", "280b8a21"], "d": ["Мехмед I, який після міжцарів'я знову об'єднав престол, 1414 року почав будівництво комплексу і розмістив його в центральній частині Бурси так, щоб він вирізнявся серед комплексів його діда та батька. Головним архітектором був Хаджі Іваз-паша.", "b820a0dd"]},
"OLAYLAR_EK14:1419-12-01:0":{"b": ["Завершення комплексу Зеленої мечеті в Бурсі", "bc82821f"], "d": ["Комплекс Зеленої мечеті, відомий програмою кахляного декору та оздоблення, до якої долучилися й майстри з Тебріза, був завершений у грудні 1419 року. Комплекс складається з мечеті, усипальниці (Зеленого тюрбе), медресе, імарету та лазні; це один із найбагатших зразків ранньої османської архітектури.", "b3e76f7c"]},
"OLAYLAR_EK14:1421-06-01:0":{"b": ["Система девширме починає фактично застосовуватися", "fa835172"], "d": ["Метод девширме, невідомий у попередніх ісламських державах, спершу почався як використання юнаків-немусульман з-поміж військовополонених за законом пенчик. За TDV, «стає зрозуміло, що його застосовували за часів Челебі Мехмеда, але законом він став за правління його сина Мурада II».", "be8c415b"]},
"OLAYLAR_EK14:1425-01-01:0":{"b": ["Запровадження посади шейх-уль-іслама — призначення мулли Фенарі муфтієм Бурси", "2a8ee2b9"], "d": ["Призначення 1425 року вченого мулли Фенарі, який багато років був кадієм Бурси, муфтієм Бурси, за словами TDV, вважають «початком муфтійства та посади шейх-уль-іслама в османів». Проте TDV зазначає, що це не тотожне повністю інституціалізованій посаді шейх-уль-іслама XVI століття, яка представляла всю організацію ільміє.", "3c8f9c61"]},
"OLAYLAR_EK14:1432-06-01:0":{"b": ["Інституціалізація тімарної системи", "dc267780"], "d": ["Перші документальні згадки про тімари сягають часів Орхан-бея; систематичну ж кодифікацію здійснено за Мурада II. Складені в цей час зведені (іджмаль) реєстри тімарів свідчать, що всі основні засади системи вже сформувалися; документи близько 1432 року доводять, що закони повною мірою діяли.", "6494e2c1"]},
"OLAYLAR_EK14:1447-01-01:0":{"b": ["Завершення мечеті та комплексу Юч Шерефелі", "cde6993e"], "d": ["Мечеть Юч Шерефелі, яку на замовлення Мурада II майстри Мусліхуддін і Шехабеддін будували десять років (1437—1447), вважають першим зразком мечетей центрального плану в османській архітектурі та однією з поворотних віх перехідної архітектури перед класичним періодом.", "daf1585b"]},
"OLAYLAR_EK14:1451-06-01:0":{"b": ["Інституціалізація Імператорського дивану (Диван-і Хюмаюн) законом Фатіха", "e8443e77"], "d": ["За Мурада II в Едірне диван, підпорядкований сталим правилам, почав набувати статусу «Диван-і Хюмаюн». Справжня ж трансформація прийшла із законом султана Мехмеда Фатіха: найбільшим нововведенням було те, що головування падишаха в дивані повністю скасували й передали великому візирові.", "e776b01d"]},
"OLAYLAR_EK14:1453-06-01:0":{"b": ["Султан Мехмед Фатіх відводить Окмейдани лучникам", "342a9fd5"], "d": ["Султан Мехмед Фатіх, який під час завоювання Стамбула розташував свою ставку на пагорбах Касимпаші, користувався цією місцевістю також як вишкільним полем для лучників; узявши місто, він назавжди відвів цю ділянку лучникам. Це стало початком перетворення Окмейдани на центр багатовікової османської традиції стрільби з лука.", "0c85baff"]},
"OLAYLAR_EK14:1502-06-01:0":{"b": ["Бурса досягає вершини в торгівлі іранським шовком", "f1324cdf"], "d": ["Каравани з Тебріза доправляли до Бурси шовк із Гіляну, Астерабада та Сарі, а тут його навперебій купували генуезькі, венеційські, флорентійські та єврейські купці. 1479 року вартість шовку, ввезеного з Ірану, досягла 150 000 венеційських золотих дукатів; 1502 року в місті працювало понад 1000 ткацьких верстатів.", "0f47c417"]},
"OLAYLAR_EK14:1504-01-01:0":{"b": ["Баязид II дає щедрі нагороди борцям Киркпинара", "d745b882"], "d": ["За статтею TDV «Боротьба», 1504 року Баязид II дав борцям нагороди в 3000 та 1500 курушів; це один із ранніх задокументованих прикладів покровительства османського двору борцівському спорту.", "cc00554e"]},
"OLAYLAR_EK14:1505-10-13:0":{"b": ["Завершення мечеті та комплексу Баязида", "eb9ab65b"], "d": ["Будівництво мечеті та комплексу Баязида, зведених для Баязида II, за одним архівним документом, почалося 906 (1500) року і завершилося 14 джумада-ль-уля 911 року (13 жовтня 1505). Питання про архітектора дискусійне: тривалий час, спираючись на запис Айвансараї, комплекс вважали твором архітектора Хайреддіна, потім його пов'язували з архітектором Кемаледдіном, а дехто вважає, що вони працювали разом; той самий документ, однак, свідчить, що майстром був Якуб-шах ібн Султан-шах. Мечеть належить до важливих пам'яток переходу від докласичної османської архітектури до класичного періоду.", "9b7591c4"]},
"OLAYLAR_EK14:1515-01-01:0":{"b": ["Перенесення Імператорського арсеналу (Терсане-і Аміре) до Стамбула (Касимпаша, Золотий Ріг)", "f36e3675"], "d": ["Нову верф, будівництво якої за правління султана Селіма Явуза почали в бухті на захід від мурів Галати, 1515 року завершили зі 160 елінгами; так арсенальну діяльність, зосереджену в Галліполі, перенесли до Стамбула. Пізніше, за часів Барбаросси Хайреддіна-паші, установа офіційно отримала назву «Терсане-і Аміре».", "baedf596"]},
"OLAYLAR_EK14:1520-01-01:0":{"b": ["Смерть шейха Хамдуллаха і спадщина його школи каліграфії", "f5ed4d09"], "d": ["Шейх Хамдуллах з Амасьї, учитель каліграфії Баязида II, довів школу «аклям-і сітте» (шести почерків) до зрілості й став засновником османського каліграфічного стилю, який запанував у всьому ісламському світі. Коли він помер 1520 року, після нього залишилося широке коло учнів.", "26c5c5fc"]},
"OLAYLAR_EK14:1521-01-01:0":{"b": ["Пірі-реїс завершує першу версію «Кітаб-і Бахріє»", "fd6cc1ff"], "d": ["1521 року Пірі-реїс завершив першу (прозову) версію «Кітаб-і Бахріє», де зібрано відомості про узбережжя Середземного моря, гавані та навігацію. Ця перша версія ще не була подана падишахові й мала характер чернетки, яку в наступні роки розширять.", "72e9151d"]},
"OLAYLAR_EK14:1526-01-01:0":{"b": ["Пірі-реїс розширює «Кітаб-і Бахріє» і підносить її Сулейманові Законодавцю", "d4abf0b7"], "d": ["Пірі-реїс розширив «Кітаб-і Бахріє», частково у віршованій формі, і 1526 року підніс її султанові Сулейману Законодавцю. У такому вигляді твір поширився як найповніший навігаційний посібник османського мореплавства.", "7209606f"]},
"OLAYLAR_EK14:1534-01-01:0":{"b": ["Матракчи Насух зображує маршрут походу на два Іраки в «Беян-і Меназіль»", "aa012278"], "d": ["Матракчи Насух, учасник першого іранського походу (походу на два Іраки) султана Сулеймана Законодавця 1534 року, технікою мініатюри-карти зобразив кожну стоянку на шляху війська зі Стамбула до Тебріза, а звідти до Багдада. Ця праця була зібрана у творі «Беян-і Меназіль-і Сефер-і Іракейн» і є найоригінальнішим зразком жанру меназільнаме в османів.", "9ea08eae"]},
"OLAYLAR_EK14:1534-12-04:0":{"b": ["Фузулі підносить Законодавцю касиду після завоювання Багдада", "1ef0653f"]},
"OLAYLAR_EK14:1535-01-01:0":{"b": ["Фузулі завершує месневі «Лейла і Меджнун»", "e3ef4085"], "d": ["«Лейлу і Меджнуна», яку вважають одним із найпрекрасніших месневі класичної турецької літератури, Фузулі написав і завершив 1535 року на прохання стамбульських поетів, які брали участь у багдадському поході Законодавця.", "bdb0a098"]},
"OLAYLAR_EK14:1538-01-01:0":{"b": ["Призначення Мімара Сінана головним придворним архітектором", "7a753f0e"], "d": ["За статтею про Сінана в Ісламській енциклопедії TDV, після смерті 1537 року головного придворного архітектора Аджема Алісі на цю посаду за поданням великого візира Лютфі-паші призначили Сінана, який привернув увагу мостом, збудованим ним через річку Прут під час молдавського походу. Так почався період Сінана на посаді головного архітектора, що триватиме понад п'ятдесят років.", "e99864c8"]},
"OLAYLAR_EK14:1543-06-01:0":{"b": ["Початок будівництва мечеті та комплексу Шехзаде", "1a70ddfd"], "d": ["Султан Сулейман Законодавець наказав звести комплекс на честь свого сина шехзаде Мехмеда, якого він втратив 1543 року під час епідемії чуми; будівництво почалося в червні 1543 року, спершу завершили усипальницю, а потім перейшли до зведення мечеті. За власним висловом Мімара Сінана, ця споруда — «мій учнівський твір».", "3f3d7e67"]},
"OLAYLAR_EK14:1547-01-01:0":{"b": ["Завершення комплексу Іскеле (Міхрімах-султан) в Ускюдарі", "3769007f"], "d": ["Будівництво комплексу на пристанській площі (Іскеле) в Ускюдарі почалося на самому початку 1540-х років і завершилося 1547 року. З двох великих мечетей, які Міхрімах-султан доручила збудувати Мімарові Сінану, ця є хронологічно першою; другу (в Едірнекапи) завершать приблизно через двадцять років.", "01e5c0ad"]},
"OLAYLAR_EK14:1548-06-01:0":{"b": ["Венеція відкриває консульство в Алеппо", "3aad8b9e"], "d": ["У XVI столітті центр ваги європейської торгівлі перемістився з Дамаска до Алеппо. Наочним показником цієї зміни стало те, що Венеція 1548 року відкрила консульство в Алеппо; за нею пішли Франція 1557 року та Англія 1586 року. Місто стало головним ринком, де європейські вовняні тканини та срібло обмінювали на індійські прянощі, а наприкінці століття — на іранський шовк.", "1c077dea"]},
"OLAYLAR_EK14:1548-08-01:0":{"b": ["Мечеть Шехзаде відкрито для богослужіння", "2bb3f4b2"], "d": ["Після будівництва, що тривало близько п'яти років, у серпні 1548 року мечеть Шехзаде відкрили для богослужіння. Її план із двома мінаретами та центральним куполом вважають провісником пізніших великих творів Мімара Сінана; комплекс складається з мечеті, усипальниці, медресе, імарету, табхане та караван-сараю.", "591f4ecf"]},
"OLAYLAR_EK14:1554-01-01:0":{"b": ["Початок будівництва водогону Киркчешме", "14124b59"], "d": ["Мімар Сінан за наказом Сулеймана Законодавця вивчив можливість провести воду до Стамбула з Белградських лісів і повідомив, що це здійсненно; будівництво великої водопровідної споруди почалося 1554 року й було завершене до 1563 року. TDV характеризує цю споруду як «найважливіший з інженерного погляду і водночас найбільший за обсягом твір» Сінана.", "dc29aa04"]},
"OLAYLAR_EK14:1554-06-01:0":{"b": ["Відкриття перших кав'ярень у Стамбулі", "85c12f9f"], "d": ["Кава увійшла в міське життя Османської держави разом із кав'ярнями, які відкрили в Тахтакале купець із Алеппо Хакем і людина на ім'я Шемс із Дамаска. Невдовзі виник новий публічний простір, де сходилися люди всіх верств суспільства; в останній період правління Законодавця в Стамбулі було п'ятдесят кав'ярень.", "e1289ca2"]},
"OLAYLAR_EK14:1555-06-01:0":{"b": ["Ебуссууд-ефенді з правового погляду досліджує питання гедіка (монопольного права ремісника)", "5d4e2930"], "d": ["Питання «гедіка» — монопольного права та привілею, що надавалися обмеженій кількості осіб у ремеслі, — за доби Законодавця знову постало на порядку денному; шейх-уль-іслам Ебуссууд-ефенді 1555—1556 року глибоко дослідив цю тему й виклав падишахові питання про законність такої практики.", "a4bf6dee"]},
"OLAYLAR_EK14:1557-01-01:0":{"b": ["Сейді Алі-реїс завершує в Стамбулі «Мірат-уль-мемалік»", "ee8640e1"], "d": ["Сейді Алі-реїс у січні 1557 року завершив у Стамбулі твір про подорож під назвою «Мірат-уль-мемалік», який писав протягом дороги назад, що почалася з Багдада. Твір є джерелом з перших рук, яке розповідає про повернення османського моряка на батьківщину суходолом з Індійського океану через Середню Азію.", "3affe91e"]},
"OLAYLAR_EK14:1561-01-01:0":{"b": ["Будівництво комплексу (мечеті) Рустема-паші", "02e30725"], "d": ["Комплекс, який Рустем-паша, зять і великий візир Сулеймана Законодавця, доручив збудувати Мімарові Сінану, зводили у 1555—1561 роках. Споруда відома оригінальною архітектурою — вона стоїть на піднятій платформі, під якою розташовані склепінчасті крамниці, — та багатими ізнікськими кахлями.", "3a9a7e0b"]},
"OLAYLAR_EK14:1566-01-01:0":{"b": ["Завершення Мостарського мосту", "e7f434af"], "d": ["Знаменитий Мостарський міст через річку Неретву збудував архітектор Хайреддін близько 1566—1567 року; згадка про міст в офіційному документі 1568 року підтверджує, що на той час його вже було завершено. Споруда є одним із найвідоміших зразків класичної османської мостової архітектури з однією стрілчастою аркою.", "62de5c2a"]},
"OLAYLAR_EK14:1566-01-01:1":{"b": ["Завершення мечеті Едірнекапи (Міхрімах-султан)", "f2d21a82"], "d": ["Будівництво мечеті, яке почалося після підтвердженого 1563 року дозволу на зведення для Міхрімах-султан, доньки Сулеймана Законодавця, завершили 1566 року; вакуфну грамоту комплексу було складено 1570—1571 року. Споруда є одним із великих творів Мімара Сінана, розташованих найближче до стамбульських мурів.", "0f9e5ecd"]},
"OLAYLAR_EK14:1566-09-08:0":{"b": ["Бакі пише елегію на смерть султана Сулеймана Законодавця", "7aa6665f"], "d": ["Коли надійшла звістка про смерть султана Сулеймана Законодавця під Сігетваром, тодішній «султан поетів» Бакі написав одну з найславетніших елегій османської літератури.", "1328fbfd"]},
"OLAYLAR_EK14:1566-09-30:0":{"b": ["Бакі підносить Селімові II оду на сходження на престол", "6027f034"], "d": ["Одразу після сходження Селіма II на престол Бакі підніс новому падишахові «джюлюсіє» (вірш на сходження на престол) — за TDV, відразу слідом за елегією, написаною на смерть Законодавця.", "1417fae7"]},
"OLAYLAR_EK14:1567-01-01:0":{"b": ["Завершення Бююкчекмеджеського мосту", "5f49b3c5"], "d": ["Міст, розпочатий за наказом султана Сулеймана Законодавця, після смерті падишаха під час Сігетварського походу добудував його син Селім II 1567—1568 року. Мімар Сінан, який збудував міст там, де озеро Бююкчекмедже сполучається з морем, власноруч відремонтував і ділянки, пошкоджені повінню.", "4478b56a"]},
"OLAYLAR_EK14:1568-01-01:0":{"b": ["Початок будівництва мечеті Селіміє (Едірне)", "07e18c9e"], "d": ["Будівництво Селіміє, яку Мімар Сінан називав «моїм твором майстра», почалося 1568 року на ім'я Селіма II і після шести років завершилося 1574 року (її завершення вже зазначене в хронології). Західні крамниці арасти та початкову школу добудував уже після смерті Селіма II, за правління Мурада III, Давуд-ага.", "a3d4551b"]},
"OLAYLAR_EK14:1572-01-22:0":{"b": ["Смерть Кинализаде Алі Челебі — автора «Ахляк-і Аляї», класичного тексту османської етичної філософії", "dd921873"], "d": ["Кинализаде Алі Челебі, автор найвідомішого класичного тексту османської етичної філософії «Ахляк-і Аляї», помер 22 січня 1572 року, обіймаючи посаду казаскера Анатолії. У стамбульських бібліотеках зберігається понад сімдесят списків його твору.", "8aa682b5"]},
"OLAYLAR_EK14:1573-01-01:0":{"b": ["Зведення комплексу Піяле-паші", "75411278"], "d": ["Капудан-паша Піяле-паша, один із зятів Селіма II, 1573 року купив ділянку під комплекс і доручив його будівництво Мімарові Сінану. Комплекс задумали як широкий ансамбль із мечеті, медресе, текке, усипальниці, кладовища, початкової школи, фонтана, ринку та лазні.", "91e37e16"]},
"OLAYLAR_EK14:1577-01-01:0":{"b": ["Завершення мосту через Дрину (мосту Соколлу Мехмеда-паші)", "1d668c73"], "d": ["Міст, збудований Мімаром Сінаном під покровительством великого візира Соколлу Мехмеда-паші, за датою в його написі був завершений 1577—1578 року; деякі дослідники припускають, що будівництво почалося 1571—1572 року. Міст є символом прив'язаності Соколлу до Вишеграда, де він народився.", "cbbd4b7e"]},
"OLAYLAR_EK14:1577-01-01:1":{"b": ["Зведення мечеті Азапкапи (Соколлу Мехмеда-паші)", "f7b57feb"], "d": ["Мечеть біля опори Ункапанського мосту з боку Шішхане великий візир Соколлу Мехмед-паша доручив збудувати Мімарові Сінану. Це одна з двох мечетей Сінана, зведених на ім'я Соколлу (інша — мечеть у Кадирзі).", "badb6241"]},
"OLAYLAR_EK14:1578-01-02:0":{"b": ["Мурад III видає фірман про написання «Хюнернаме»", "b125710d"], "d": ["Фірманом від 2 січня 1578 року Мурад III наказав Сейїдові Локману написати «Хюнернаме», присвячену життю падишахів від Османа Газі до його власного часу; мініатюри до твору виконали Наккаш Осман і його майстри.", "5b7078bd"]},
"OLAYLAR_EK14:1580-01-01:0":{"b": ["Завершення мечеті Зала Махмуда-паші", "732f75bc"], "d": ["Під час будівництва комплексу, розпочатого після одруження Зала Махмуда-паші та Шах-султан 1574 року, мечеть завершили 1580 року; зведення медресе тривало до 1582 року, а фонтана — до 1590 року. Комплекс на схилах Еюпа привертає увагу оригінальним планом із двома симетричними мінаретами.", "9cf44e2d"]},
"OLAYLAR_EK14:1588-01-01:0":{"b": ["Завершення другого тому «Хюнернаме»", "70a1e741"], "d": ["Другий том «Хюнернаме» завершили в січні 1588 року; з 65 мініатюрами він став одним із найцінніших у документальному відношенні творів османської історіографії. Обидва томи ілюстрували в майстерні Наккаша Османа.", "148989eb"]},
"OLAYLAR_EK14:1592-01-01:0":{"b": ["Давуд-ага стає головним придворним архітектором", "8cdc7f53"], "d": ["Після короткої перерви, що настала по смерті Мімара Сінана 1588 року, від 1592 року Давуда-агу почали називати в офіційних документах головним придворним архітектором. Давуд-ага, який взяв на себе деякі доповнювальні елементи комплексу Селіміє та перший етап будівництва Нової мечеті, є одним із найважливіших архітекторів того часу.", "cca50071"]},
"OLAYLAR_EK14:1598-04-09:0":{"b": ["Закладення фундаменту Нової мечеті (Емінйоню)", "d3cddc01"], "d": ["За фундаторства Сафіє-султан, матері Мехмеда III, фундамент мечеті заклали кам'яними блоками після того, як ґрунт укріпили палями. Дві окремі статті TDV наводять для цієї події різні дати (стаття про комплекс Єніджамі — 9 квітня 1598, стаття про Давуда-агу — 23 серпня 1597); тут за основу взято дату зі статті, присвяченої самій споруді.", "744933c0"]},
"OLAYLAR_EK14:1598-09-01:0":{"b": ["Смерть Давуда-аги від чуми та призупинення будівництва Нової мечеті", "81f2cd04"], "d": ["Замість Давуда-аги, який помер під час епідемії чуми у вересні 1598 року, коли підняв Нову мечеть над землею лише на один лікоть (зіра), головним архітектором призначили Далгича Ахмеда-чавуша. TDV зазначає, що в альтернативній версії, яка спирається на вірш-хронограму, дату смерті подано також як 1599—1600 рік і що точну дату встановити не вдалося.", "02ee24e4"]},
"OLAYLAR_EK14:1599-06-01:0":{"b": ["Інтенсивний експорт анкарського ангорського сукна (соф) до Європи", "3f37018d"], "d": ["Соф і шалі (тканини з ангорської вовни), виткані в Анкарі, вивозили не лише на внутрішні ринки, такі як Стамбул, Бурса, Дамаск і Алеппо, а й до Венеції, Польщі, Англії та Франції. У прикладі, наведеному TDV, 1599 року вісімнадцять купців купили 162 в'юки софу вартістю 5 700 000 акче та відправили їх до Алеппо й Венеції.", "966119b2"]},
"OLAYLAR_EK14:1603-12-20:0":{"b": ["Будівництво Нової мечеті зупиняється після смерті Мехмеда III", "5acef053"], "d": ["Після смерті 1603 року Мехмеда III, сина фундаторки Сафіє-султан, її відіслали до Старого палацу, і будівництво Нової мечеті залишилося незавершеним; у такому стані споруда чекала на добудову близько шістдесяти років.", "6d8a4c2b"]},
"OLAYLAR_EK14:1633-01-01:0":{"b": ["Катіб Челебі починає в Алеппо дослідження для «Кешф аз-зунун»", "094e6870"], "d": ["1633 року в Алеппо Катіб Челебі почав збирати матеріал для «Кешф аз-зунун», яка згодом стане його бібліографічним шедевром. Упродовж цієї праці, що тривала двадцять років, він одну за одною перевіряв бібліотеки та книгарні в містах, де бував.", "92278c89"]},
"OLAYLAR_EK14:1635-01-01:0":{"b": ["Неф'ї страчено за сатири", "5e459c60"], "d": ["Диванного поета Неф'ї, відомого своїми сатирами, 1635 року стратили за наказом Мурада IV через його збірку сатир «Сихам-і Каза». Великий візир Байрам-паша видав його; Неф'ї задушили в дров'яному сараї палацу, а тіло кинули в море.", "e3b52153"]},
"OLAYLAR_EK14:1640-06-01:0":{"b": ["Укладення всеохопного реєстру нарху", "6c1e231b"], "d": ["Хоча практика нарху (граничних цін) сягає в османів глибокої давнини, найповніший реєстр нарху, що дійшов до нас, датований 1640 роком; цей реєстр, який охоплює продукти харчування, одяг, послуги, стандарти та гігієнічні умови, за словами TDV, «функціонував як справжній закон про регулювання ринку».", "3f704851"]},
"OLAYLAR_EK14:1648-01-01:0":{"b": ["Катіб Челебі вперше починає писати «Джиханнюму»", "554c6734"], "d": ["Катіб Челебі, прагнучи заповнити прогалину в османських географічних знаннях перед лицем географічних відкриттів Заходу, 1648 року розпочав перший варіант «Джиханнюми». Ця перша версія залишилася незавершеною, оскільки не вдалося знайти достатніх джерел про деякі європейські країни.", "aa7d5e31"]},
"OLAYLAR_EK14:1650-01-01:0":{"b": ["Система ільтізаму дозріває, перейшовши в монополію військового стану", "2c587934"], "d": ["Метод ільтізаму (передання збору податків приватним особам на відкуп за певну плату) застосовувався з другої половини XV століття, але з початку XVI століття швидко поширювався. За TDV, процес повного переходу цієї сфери в монополію представників військового стану завершився 1650 року; так ільтізам став головним фіскальним методом, що замінив тімарну систему.", "d50f2237"]},
"OLAYLAR_EK14:1654-12-01:0":{"b": ["Катіб Челебі береться переписати «Джиханнюму» заново", "e9c68110"], "d": ["Катіб Челебі, залишивши перший варіант незавершеним, наприкінці 1654 року взявся писати «Джиханнюму» заново. Цю другу версію теж не вдалося закінчити: коли твір дійшов до Вана, смерть автора 1657 року перервала роботу, і в такому вигляді його надрукував лише 1732 року Ібрагім Мютеферрика.", "5a96db0a"]},
"OLAYLAR_EK14:1665-10-30:0":{"b": ["Нову мечеть завершено й відкрито для богослужіння", "d6d86c82"], "d": ["Будівництво Нової мечеті, яке понад шістдесят років залишалося незавершеним, закінчили під керівництвом головного архітектора Мереметчі Мустафи-аги, призначеного 1661 року валіде-султан Хатідже Турхан; мечеть відкрили для богослужіння п'ятничною молитвою 30 жовтня 1665 року.", "0ec54cd6"]},
"OLAYLAR_EK14:1675-01-01:0":{"b": ["Мехмед IV на святі обрізання в Едірне кілька днів влаштовує джирид", "3638a5b6"], "d": ["На святі обрізання своїх синів, яке Мехмед IV влаштував 1675 року в Едірне, він організував багатоденні змагання з джириду; у статті TDV «Джирид» це особливо згадано як один із найпишніших прикладів підтримки османським двором цього спорту.", "57c8c183"]},
"OLAYLAR_EK14:1679-01-01:0":{"b": ["Хафиз Осман виробляє власний каліграфічний стиль", "93081cb3"], "d": ["Хафиз Осман, який належав до лінії шейха Хамдуллаха, 1679 року виробив у «аклям-і сітте» власний новий стиль, який згодом назвуть «школою Хафиза Османа». Цей стиль у двох окремих відгалуженнях дійшов до наших днів.", "8d00a956"]},
"OLAYLAR_EK14:1695-01-01:0":{"b": ["Хафиза Османа призначено вчителем каліграфії Мустафи II", "d976cda4"], "d": ["Хафиза Османа, якого вважали найвправнішим каліграфом свого часу, 1695 року призначили вчителем каліграфії щойно зійшлого на престол Мустафи II. За своє життя він виховав близько п'ятдесяти каліграфів і переписав 25 примірників Корану.", "c70668d5"]},
"OLAYLAR_EK14:1711-01-01:0":{"b": ["Смерть Итрі", "62750526"], "d": ["Бухурізаде Мустафа Итрі-ефенді, один із найбільших композиторів турецької музики, за близькими до тієї доби джерелами помер 1711 року. Такими творами, як такбір у ладі сегях і наат у ладі раст, він залишив шедеври мечетної та суфійської (текке) музики.", "a2ccc3ba"]},
"OLAYLAR_EK14:1718-01-01:0":{"b": ["Недім висувається як провісник поезії доби Тюльпанів", "d3c40dbb"], "d": ["Упродовж доби Тюльпанів (1718—1730) Недім виробив новий поетичний стиль, що вирізнявся досконалістю вислову, прагненням простоти й дотепною манерою. Цей стиль, який розвинувся в колі Невшехірлі Дамада Ібрагіма-паші, вважають найяскравішим виявом течії зближення диванної поезії з місцевим ґрунтом.", "0521666a"]},
"OLAYLAR_EK14:1720-01-01:0":{"b": ["Левні ілюструє «Сурнаме-і Вехбі»", "8c127866"], "d": ["Придворний художник Левні ілюстрував 137 мініатюрами «Сурнаме-і Вехбі», яка розповідає про свято обрізання синів Ахмеда III 1720 року. На відміну від попередніх зразків, він не обмежив святкування самим Ат-мейданом, а зобразив їх у різних куточках міста, започаткувавши нове бачення в османському мистецтві мініатюри.", "bd655b91"]},
"OLAYLAR_EK14:1727-06-01:0":{"b": ["Система гедіка офіційно утверджується як монопольний цеховий устрій", "cd0f79a7"], "d": ["За TDV, системну трансформацію, під час якої право гедіка набуло значення «монополії, привілею та своєрідного патенту», простежують з 1727 року; цей устрій, що надавав право працювати в ремеслі обмеженій кількості осіб, під назвою «право гедіка» закріпився в крамницях, більшість яких були вакуфним майном.", "18446662"]},
"OLAYLAR_EK14:1730-09-25:0":{"b": ["Знищення Саадабада під час повстання Патрони Халіла", "8a30f9a0"], "d": ["Під час повстання Патрони Халіла, яке спалахнуло 25 вересня 1730 року, в Саадабаді зруйнували сотні павільйонів і споруд; цей ансамбль, символ доби Тюльпанів, так і не повернув собі колишньої пишноти.", "a26b72e6"]},
"OLAYLAR_EK14:1730-10-28:0":{"b": ["Смерть Недіма під час повстання Патрони Халіла", "06bf909e"], "d": ["Коли спалахнуло повстання Патрони Халіла, Недім був мюдеррісом у медресе Секбана Алі-паші; він помер у дні, що настали після повстання. День його смерті невідомий; однак оскільки кассамський акт (худжет) про його спадщину складено 15 рабі-ль-ахіра 1143 року (28 жовтня 1730), він помер до цієї дати. Щодо причини смерті є різні перекази: частина джерел пише, що він помер від хвороби страху (іллет-і вехіме) або від тремтіння, яке напало на нього через пияцтво та опіум, а Мюстакімзаде пише, що під час перевороту він зі страху виліз на дах свого будинку і загинув, упавши звідти. З його смертю фактично згас і культурний блиск доби Тюльпанів.", "49085a6c"]},
"OLAYLAR_EK14:1732-01-01:0":{"b": ["Смерть Левні", "dd48b56e"], "d": ["Левні, якого вважають останнім великим представником османського мистецтва мініатюри, помер 1732 року. Більшість його творів сьогодні зберігається в Музеї палацу Топкапи.", "25f589a6"]},
"OLAYLAR_EK14:1749-01-19:0":{"b": ["Закладення фундаменту мечеті та комплексу Нуруосманіє", "397ec798"], "d": ["Фундамент комплексу Нуруосманіє заклав Махмуд I 19 січня 1749 року. Цю споруду вважають першим великим застосуванням європейського стилю бароко в османській архітектурі; вона помітно відходить від класичної схеми комплексу.", "c1e0698f"]},
"OLAYLAR_EK14:1755-12-05:0":{"b": ["Відкриття мечеті та комплексу Нуруосманіє", "15d83731"], "d": ["Комплекс, який розпочав Махмуд I, але не побачив завершеним, відкрили 5 грудня 1755 року за правління його брата Османа III. Мечеть отримала назву зі значенням «світло Османа» — на честь Османа III, який здійснив відкриття.", "4722cd6a"]},
"OLAYLAR_EK14:1775-04-29:0":{"b": ["Відкриття Імператорської морської інженерної школи (Мюхендісхане-і Бахрі-і Хюмаюн)", "a2fab1cd"], "d": ["Перша сучасна османська морська інженерна школа — Мюхендісхане-і Бахрі-і Хюмаюн — за французькими архівними документами відкрилася 29 квітня 1775 року, за правління Абдул-Гаміда I, коли великим візиром був Дервіш Мехмед-паша.", "cafb2bf9"]},
"OLAYLAR_EK14:1775-06-01:0":{"b": ["Запровадження системи есхам", "eabd8ece"], "d": ["Зіткнувшись із тягарем контрибуції в 7,5 мільйона курушів, накладеної Кючук-Кайнарджійським миром, 1775 року запровадили систему есхам. За цим методом, задуманим, щоб подолати обмеження системи малікяне, дохід від мукатаа поділяли на частки, і, на відміну від малікяне, власниками часток могли бути також жінки, немусульмани та прості люди.", "01a12eaa"]},
"OLAYLAR_EK14:1778-01-09:0":{"b": ["Народження Хаммамізаде Ісмаїла Деде-ефенді", "c033f039"], "d": ["Хаммамізаде Ісмаїл Деде-ефенді, один із найплідніших композиторів турецької музики, народився 9 січня 1778 року в стамбульському кварталі Шехзадебаші. За своє життя він написав понад 500 творів; близько 294 з них дійшли до наших днів.", "0b7fc673"]},
"OLAYLAR_EK14:1793-07-14:0":{"b": ["Початок будівництва Імператорської сухопутної інженерної школи (Мюхендісхане-і Беррі-і Хюмаюн)", "4f5d521a"], "d": ["14 липня 1793 року почалося будівництво Мюхендісхане-і Беррі-і Хюмаюн — однієї з найважливіших установ реформ Нізам-і Джедід Селіма III. Будівлю завершили у вересні 1795 року й відкрили для навчання; ця установа була другою османською військовою інженерною школою, створеною за зразком європейських військових академій.", "79c0131c"]},
"OLAYLAR_EK14:1794-06-01:0":{"b": ["Селім III починає скасовувати монополії деяких ремісничих цехів", "008f4a7d"], "d": ["За статтею TDV «Реміснича спільнота», в османському цеховому устрої, який від самого заснування переплітався з організацією ахі, такі посадовці, як «ахі баба» та «шейх», аж до початку XIX століття очолювали цехи; коли у XVIII столітті цехи, користуючись монополією, піднімали ціни вище встановленого нарху й створювали економічний тиск, Селім III з 1794 року почав скасовувати монополії цехів основних продуктів харчування.", "35d33c12"]},
"OLAYLAR_EK14:1812-01-01:0":{"b": ["Деде-ефенді беруть до двору як «мусахіб-і шехріярі»", "0cb99ac3"], "d": ["Деде-ефенді, який за часів Селіма III привернув увагу падишаха композицією в макамі буселік, 1812 року Махмуд II включив до числа «мусахіб-і шехріярі» (особистих наближених співрозмовників падишаха), а невдовзі він піднявся до посади головного муедзина.", "15b3c49d"]},
"OLAYLAR_EK14:1830-12-01:0":{"b": ["Проведення першого регулярного перепису населення в Османській державі", "4f004c6c"], "d": ["Щоб визначити кількість населення, яке підлягало призову, наприкінці 1830 року Махмуд II уперше провів регулярний перепис; фіксували лише чоловіче населення, і в Анатолії та Румелії нарахували близько 7,5 мільйона осіб. У деяких регіонах, таких як Ерзурум і Ван, перепис вдалося завершити лише 1836 року.", "af4a7bcf"]},
"OLAYLAR_EK14:1833-06-01:0":{"b": ["Заснування фабрики Фесхане-і Аміре", "971ab85a"], "d": ["Щоб забезпечити фесами армію «Асакір-і Мансуре-і Мухаммедіє», створену після скасування корпусу яничарів 1826 року, 1833 року на площі Джюнді в Кадирзі з капіталом 1,5 мільйона курушів почали виробництво фесів. 1839 року підприємство перевели до палацу Хатідже-султан в Еюпі; Фесхане стала основою османської текстильної промисловості.", "c8481f41"]},
"OLAYLAR_EK14:1839-05-14:0":{"b": ["Медична школа отримує назву «Мектеб-і Тибіє-і Адліє-і Шахане»", "187d60f3"], "d": ["Медична школа, переведена до будівлі школи аг Ендеруну в Галатасараї, 14 травня 1839 року під час візиту Махмуда II отримала назву «Мектеб-і Тибіє-і Адліє-і Шахане»; так установу офіційно закріпили як військово-адміністративну школу.", "6a65292b"]},
"OLAYLAR_EK14:1846-11-29:0":{"b": ["Смерть Деде-ефенді в Міні під час хаджу", "c3e613a2"], "d": ["Хаммамізаде Ісмаїл Деде-ефенді, який захворів на холеру в Міні, куди вирушив виконати обов'язок хаджу, помер 29 листопада 1846 року. Зі смертю митця, який у 1824—1839 роках написав сім окремих мевлевійських айїнів, завершилася ціла доба класичної османської музики.", "fea95526"]},
"OLAYLAR_EK14:1850-06-01:0":{"b": ["Ухвалення Торговельного кодексу 1850 року", "8ac085fd"], "d": ["У межах правових реформ доби Танзімату нові закони переймали в західних держав шляхом перекладу та запозичення: кримінальний кодекс набув чинності 1840 року, торговельний — 1850 року, земельний — 1857 року. Торговельний кодекс був першою сучасною кодифікацією османського торговельного права.", "2f7aeb1b"]},
"OLAYLAR_EK14:1859-06-01:0":{"b": ["Початок великої хвилі переселення кримських татар і кавказьких народів на османські землі", "8832c06d"], "d": ["Після того як 1859 року шейх Шаміль потрапив у російський полон, разом із кримськими татарами на османські землі почали переселятися з Кавказу численні черкеські та ногайські мухаджири. Ця хвиля переселення з різною інтенсивністю тривала аж до часів після османсько-російської війни 1877—1878 років.", "580ce507"]},
"OLAYLAR_EK14:1860-01-16:0":{"b": ["Створення Комісії у справах переселенців (Мухаджирської комісії)", "9717e77e"], "d": ["Щоб упоратися зі зростанням хвилі переселення з Кавказу, 16 січня 1860 року османський уряд створив Комісію у справах переселенців. Комісія координувала роботу з поселення в Анатолії, на Балканах і в Сирії та діяла до 1875 року.", "404d989d"]},
"OLAYLAR_EK14:1863-06-01:0":{"b": ["Реорганізація Османського банку (Банк-і Османі) в Імператорський Османський банк (Банк-і Османі-і Шахане)", "c3530456"], "d": ["1856 року, після Кримської війни, для управління виплатами зовнішнього боргу було засновано Банк-і Османі з центром у Лондоні та англійським капіталом. 1863 року спільній франко-англійській групі дозволили заснувати новий банк під назвою Банк-і Османі-і Шахане (Османський банк); згодом установа отримала й право випускати банкноти.", "72227299"]},
"OLAYLAR_EK14:1864-03-30:0":{"b": ["Заснування Ісламського освітнього товариства (Джеміет-і Тедрісіє-і Ісламіє)", "77ad553a"], "d": ["30 березня 1864 року було засновано Джеміет-і Тедрісіє-і Ісламіє, щоб узяти на себе освіту бідних учнів-мусульман, які навчалися ремесла; ця ініціатива громадського товариства є одним із перших прикладів перетворення благодійницької традиції на проєкт сучасної школи. Через дев'ять років товариство відкриє «Дарюшшафаку».", "2ea443d2"]},
"OLAYLAR_EK14:1864-06-01:0":{"b": ["Вілаєтський статут 1864 року впорядковує систему мухтарів і рад старійшин", "1a2e8cf2"], "d": ["Вілаєтський статут 1864 року реорганізував сільське управління: було встановлено, що в селах, де разом жили мусульмани та немусульмани, кожна громада обирає власного мухтара та раду старійшин. Так рада старійшин уперше здобула офіційне місце в управлінні селом і кварталом.", "eee4df7d"]},
"OLAYLAR_EK14:1864-07-01:0":{"b": ["Апогей Великого черкеського вигнання", "b2ab1874"], "d": ["Унаслідок російської окупації Кавказу в 1858—1878 роках, найінтенсивніше — в 1861—1864 роках, 1,2—1,5 мільйона черкесів були примусово переселені на османські землі. За TDV, багато дослідників характеризують цю подію як «перший акт етнічної чистки в новій історії».", "d1bb6d70"]},
"OLAYLAR_EK14:1869-09-01:0":{"b": ["Опублікування Загального освітнього статуту (Маариф-і Умуміє) 1869 року", "787f6022"], "d": ["Загальний освітній статут, опублікований 1 вересня 1869 року, став першим всеохопним документом, що впорядковував загальну освіту в провінції та центрі. Статутом було створено Велику раду з освіти (Меджліс-і Кебір-і Маариф); із цієї постанови почалася реорганізація початкових шкіл (сибьян мектебі): їх перестали вважати лише етапом релігійної освіти й переорієнтували на навчання читання та письма.", "51087b3c"]},
"OLAYLAR_EK14:1873-06-28:0":{"b": ["Школа «Дарюшшафака» починає навчання", "525c457c"], "d": ["«Дарюшшафака», заснована Джеміет-і Тедрісіє-і Ісламіє, фактично почала навчання 28 червня 1873 року, щоб безкоштовно, з пансіоном, навчати осиротілих і бідних дітей-мусульман; граничний вік вступу визначили в десять років.", "c4f863b5"]},
"OLAYLAR_EK14:1894-07-10:0":{"b": ["Стамбульський землетрус 1894 року", "7ae7f648"], "d": ["10 липня 1894 року землетрус, що стався у водах Ізмітської затоки, завдав Стамбулу тяжкої шкоди; постраждало багато мечетей та історичних споруд, зокрема стамбульські мури. Стаття TDV про землетруси відносить цей землетрус разом із землетрусами 1509, 1719 та 1766 років до тих, що спричинили в регіоні Мармурового моря великі людські та майнові втрати.", "61236a0f"]},
"OLAYLAR_EK14:1896-02-02:0":{"b": ["Відкриття притулку «Дарюладжезе»", "a30baf31"], "d": ["«Дарюладжезе», створений за наказами, які Абдул-Гамід II віддавав починаючи з 1890 року, 2 лютого 1896 року відкрив великий візир Халіл Ріфат-паша. Установа, що давала прихисток безпритульним дітям, літнім людям і нужденним, із лікарнею на 200 ліжок, майстернями та окремими місцями богослужіння — мечеттю, церквою та синагогою — була найбільшим комплексом соціальної допомоги свого часу.", "9cf12efa"]},
"OLAYLAR_EK14:1900-08-31:0":{"b": ["Дар-уль-фюнун-і Шахане знову засновано як постійну установу", "7d6d8fc4"], "d": ["Після двох попередніх невдалих спроб (1863 та 1870) 31 серпня 1900 року Дар-уль-фюнун було знову засновано як постійну установу під назвою Дар-уль-фюнун-і Шахане; TDV називає цю дату безпосереднім підґрунтям сучасної турецької університетської системи.", "7d7fd7ca"]},
"OLAYLAR_EK15:1337-09-09:0":{"b": ["Сербедари взяли Себзевар — перша держава в Хорасані після Хулагуїдів", "af997fec"], "d": ["Коли зі смертю Абу Саїда (30 листопада 1335) центральна влада Ільханату розпалася, накопичене в Хорасані обурення проти збирачів податків вибухнуло в Баштіні: Абд ар-Раззак повстав 13 березня 1337 року і 9 вересня 1337 року (12 сафара 738) захопив Себзевар. Назва «сербедар» — «голова на шибениці» — це їхні власні слова, які означають, що в разі поразки вони готові бути повішеними.", "c0abed9c"]},
"OLAYLAR_EK15:1359-01-01:0":{"b": ["Сейїди Мараші взяли Амоль — влада сейїдів у Мазандарані", "c0e03266"], "d": ["Сейїд Ківам ад-Дін Мараші, ідучи шляхом, прокладеним у Хорасані сербедарами, 760 (1359) року захопив Амоль і заснував на південному узбережжі Каспію державу сейїдів. Влада династії поширилася на Сарі, Барфуруш та їхні околиці; її похитнули походи Тимура, а за сефевідського шаха Аббаса I вона була ліквідована.", "d93ea1fd"]},
"OLAYLAR_EK15:1371-01-01:0":{"b": ["У Гіляні засновано династію Кар-Кія — останні незалежні володарі каспійського узбережжя", "6e5f9db7"], "d": ["Алі Кія, повернувшись із родиною до Гіляну, 773 (1371—1372) року встановив владу Кар-Кія з центром у Лахіджані; династія понад два століття утримувала південно-західне узбережжя Каспію і проіснувала до приєднання краю сефевідським шахом Аббасом I 1592 року.", "670fc7fd"]},
"OLAYLAR_EK15:1400-01-01:0":{"b": ["Влада даджу в Дарфурі переходить до тунджурів", "6eb22a2a"], "d": ["За статтею «Дарфур» Ісламської енциклопедії TDV, першими в цьому краї оселилися й заснували першу державу плем'я даджу; даджу, які панували тут протягом XIII та XIV століть, поступилися торговельним пануванням тунджурам, а в XV столітті становище, особливо в центральній частині, повністю повернулося на користь тунджурів.", "2709880c"]},
"OLAYLAR_EK15:1564-01-01:0":{"b": ["Іспанія повертає собі скелю Бадіс (Пеньйон-де-Велес)", "0dc52728"], "d": ["Стаття TDV «Саадити» фіксує, що захоплення іспанцями Бадіса стало тяжким ударом по мореплавству Магрибу (1564). Ця скельна позиція на північному узбережжі Марокко слугувала опорою для піратства в Західному Середземномор'ї та для османсько-іспанського суперництва.", "110ee39e"]},
"OLAYLAR_EK15:1610-01-01:0":{"b": ["Передача аль-Араїша (Лараша) Іспанії", "7b8f6e27"], "d": ["У роки громадянської війни, коли династія Саадитів розпалася на частини, порт аль-Араїш на атлантичному узбережжі віддали Іспанії. Стаття TDV «Саадити» фіксує, що в цей час країна поділилася надвоє — на емірати Марракеша (південь) та Феса (північ), — а сторони боротьби за престол шукали допомоги ззовні. Порт залишатиметься в іспанських руках майже вісімдесят років, і 1689 року його поверне мулай Ісмаїл.", "597cc620"]},
"OLAYLAR_EK15:1614-01-01:0":{"b": ["Мамура (Мехдія) переходить у руки іспанців", "c8fd494e"], "d": ["Порт Мамура (Маамура, Мехдія) в гирлі річки Себу іспанці взяли 1614 року й укріпили під назвою Сан-Мігель-де-Ультрамар. Стаття TDV «Мулай Ісмаїл» фіксує, що порт відібрали в іспанців раптовим нападом 1092 (1681) року — тобто іспанське панування тривало шістдесят сім років.", "3f87063c"]},
"OLAYLAR_EK15:1659-01-01:0":{"b": ["Кінець династії Саадитів — початок доби Алавітів (Філалі) в Марокко", "b1afa579"], "d": ["Ісламська енциклопедія TDV визначає Саадитів як «ісламську династію, що правила в Марокко (1511—1659)». Династія, яка 1549 року поклала край владі Ваттасидів і об'єднала все Марокко, 1578 року знищила португальську армію при Ваді-ль-Махазін і ніколи не підкорялася османам, після тривалих усобиць за престол припинила існування 1659 року. Її місце посіли алавітські (філалійські) шерифи з Тафілалета; мулай Рашид, увійшовши 1666 року до міста Фес, зміцнив нову династію, а його брат мулай Ісмаїл очистив атлантичне узбережжя від європейських позицій.", "1e7caacc"]},
"OLAYLAR_EK15:1673-01-01:0":{"b": ["Іспанія окуповує острови Ель-Хосейма (Алусемас)", "954ca998"], "d": ["Острови Ель-Хосейма біля середземноморського узбережжя 1673 року окупував іспанський флот. Разом із Бадісом і Сеутою вони належать до позицій, які Іспанія утримувала на північному узбережжі Марокко і які залишаються в її руках донині. Того ж року мулай Рашид, старший брат мулая Ісмаїла, увійшов до Марракеша та прийняв присягу населення, і влада Філалі зміцнилася на півдні — ця втрата на узбережжі свідчить, що внутрішнє об'єднання ще не мало відповідника на зовнішньому фронті.", "b67d415f"]},
"OLAYLAR_EK15:1689-01-01:0":{"b": ["Мулай Ісмаїл повертає аль-Араїш від іспанців", "a54bc6ee"], "d": ["Стаття TDV «Мулай Ісмаїл» висловлюється чітко: «1100 (1689) року вони відібрали Араїш в іспанців, захопивши 200 гармат, а через два роки повернули й Асілу». Це одна з ланок очищення узбережжя, яке здійснював султан із роду Філалі: Танжер повернули від англійців 1678 року, Мамуру — 1681, аль-Араїш — 1689, Асілу — 1691 року. Порт, залишений за вісімдесят років перед тим під час саадитської міжусобиці, таким чином повернувся до Марокко.", "cd2b390d"]},
"OLAYLAR_EK15:1695-01-01:0":{"b": ["Заснування Дарфурського султанату — династія Кейра та Сулейман Солонг", "0fc1c112"], "d": ["За TDV, заснування Дарфурського султанату припадає на час після смути, що настала по вторгненню в край Бумо аль-Касіра наприкінці XVII століття. Фури під проводом роду Кіра (Кейра), на чолі якого стояв Сулейман Солонг, відібрали владу в даджу й тунджурів і встановили міцне управління. Сулейман Солонг правив у 1695—1715 роках. У наступні століття дарфурські султани листувалися з Високою Портою; Абдул-Меджид і Абдул-Азіз затверджували їхнє правління.", "58155fc4"]},
"OLAYLAR_EK15:1792-09-22:0":{"b": ["Проголошення Першої республіки у Франції — кінець монархії", "d53d49b0"], "d": ["На першому засіданні Національного конвенту монархію скасували, а наступного дня проголосили Першу республіку; від цього дня почали рахувати перший рік нового календаря. Для Османської держави співрозмовник не змінився, але змінився тип співрозмовника: у роки Нізам-і Джедід Селіма III Франція була вже не династією, а режимом, і саме армія цього режиму 1798 року висадиться в Єгипті.", "a16f5b39"]},
"OLAYLAR_EK15:1857-07-11:0":{"b": ["Падіння Великої Кабілії — полон Лалли Фатьми Н'Сумер", "0f61ff08"], "d": ["Стаття TDV «Алжир» фіксує, що з окупацією гірського краю Кабілії (Білад аль-Кабаїль) унаслідок походів 1853, 1854 та 1857 років французьке завоювання Алжиру було значною мірою завершене. Похід 1857 року зламав лінію Тізі-Узу — Акбу; символ опору, Лалла Фатьма Н'Сумер, потрапила в полон. Так згас останній великий осередок опору, що тримався після капітуляції еміра Абд аль-Кадіра 1847 року.", "6d14160e"]},
"OLAYLAR_EK15:1899-12-29:0":{"b": ["Французи окуповують Ін-Салах (Тідікельт)", "1e28d1d0"], "d": ["Ін-Салах, центр групи оаз Тідікельт посеред Сахари, французькі сили взяли 29 грудня 1899 року. Це перший великий крок французької експансії від алжирського узбережжя на південь углиб пустелі; протягом двох років Туат і Гурара підуть тим самим шляхом.", "99e7ecb6"]},
"OLAYLAR_EK15:1901-02-21:0":{"b": ["Приєднання оаз Туат · Гурара · Тідікельт до Франції", "d412838b"], "d": ["Пояс оаз Туат, Гурара та Тідікельт на південному заході Алжиру 21 лютого 1901 року офіційно приєднали до Франції. Цей вузол караванних шляхів, на який марокканський султан номінально претендував, — зокрема Адрар, Тімімун, Регган і Бені-Аббес — таким чином увійшов до Алжиру; з цього почалася прикордонна суперечка між Марокко та французьким Алжиром.", "c50f9569"]},
"OLAYLAR_EK15:1903-11-11:0":{"b": ["Створення французького посту в Бешарі (Коломб-Бешар)", "4d44d252"], "d": ["Оазу Бешар на марокканському кордоні французькі сили взяли 11 листопада 1903 року й перетворили на передовий пост під назвою Коломб-Бешар. Цей крок, зроблений через два роки після приєднання поясу Туат, належить до останніх ланок просування Франції з Алжиру в бік Марокко; він відкрив шлях до встановлення протекторату над Марокко 1912 року.", "bd1a7ae2"]},
"OLAYLAR_EK16:1283-01-01:0":{"b": ["Заснування Московського князівства — Даниїл I", "49549309"], "d": ["Даниїл, наймолодший син Олександра Невського, почав правити Москвою як незалежним князівством. На той час Москва була невеликим і незначним центром Володимиро-Суздальської землі; російська історіографія вважає цю дату відправною точкою її подальшого піднесення.", "10cf92d1"]},
"OLAYLAR_EK16:1297-01-01:0":{"b": ["Заснування бейліків Каресі та Гамідидів", "3905da93"], "d": ["За статтею TDV «Каресиди», Каресі-бей, проголосивши незалежність у сельджуцькій прикордонній організації, яка розпалася зі смертю його батька Калем-бея, з 696 (1296—1297) року зробив своїм центром Баликесір і невдовзі відібрав у Візантії всю Місію, зокрема Ердек, Бігу, Едреміт і Бергаму. Того ж року (1297) Хамід-бей, зробивши Улуборлу осідком свого уряду, заснував бейлік Гамідидів; Іспарта, Бурдур, Егірдір і Ялвач з розпаданого сельджуцького прикордоння увійшли в перші межі бейліку. Обидва бейліки є породженням того самого краху в Західній Анатолії — розпаду центральної влади Сельджуків.", "7d297343"]},
"OLAYLAR_EK16:1301-01-01:0":{"b": ["Московський князь Даниїл приєднав до Москви Коломну та Серпухов", "6d82dccd"], "d": ["Даниїл відібрав у Рязанського князівства Коломну (полонений рязанський князь передав фортецю, щоб вийти на волю) та Серпухов; Москва вийшла до річки Оки, і це стало першим територіальним розширенням Московського князівства.", "f6b7a96c"]},
"OLAYLAR_EK16:1304-01-01:0":{"b": ["Можайськ відібрано в Смоленського князівства й приєднано до Москви", "462055a0"], "d": ["Московське князівство, відібравши в Смоленська Можайськ у верхів'ях річки Москви, наблизило свій західний кордон до Литви.", "3002aa5d"]},
"OLAYLAR_EK16:1307-01-01:0":{"b": ["Полоцьке князівство перейшло до Великого князівства Литовського", "04a26a6f"], "d": ["Полоцьк, Вітебськ та їхні околиці до 1307 року залишалися під владою руської князівської династії; з цим переходом чітко проявилася експансія Литви на схід іще до Гедиміна (дата в атласному записі — 1307; фактичний перехід Вітебська близько 1320 року дискусійний).", "52bf8042"]},
"OLAYLAR_EK16:1308-01-01:0":{"b": ["Заснування бейліку Айдиногулларів — взяття Ізміра, Аясолука і Тіре", "69a021ae"], "d": ["За статтею TDV «Айдиніди», Мубаріз ад-Дін Гази Мехмед-бей, відібравши цей край у Саса-бея, прикордонного бея Ґерміянідів, 1308 року став володарем Айдин-ілі; він завоював мусульманську частину Ізміра разом з Аясолуком (Сельчуком), Тіре та Бодем'є. Аясолук він зробив військово-морською базою, а захоплені землі розділив між п'ятьма синами; у наступні десятиліття, особливо за його сина Умур-бея, бейлік стане вирішальною силою в егейському мореплавстві.", "9c871e7d"]},
"OLAYLAR_EK16:1308-01-01:1":{"b": ["Фактичний кінець анатолійської Сельджуцької держави — пряме управління Ільханату", "00f85ecb"], "d": ["За статтею TDV «Масуд II», Гіяс ад-Дін Масуд II, який помер у Кайсері 708 (1308) року після тривалої хвороби, за загальноприйнятою думкою був останнім правителем анатолійської Сельджуцької держави — претендентів, яких саджали на престол після його смерті, не визнали ні внутрішні інстанції, ні Хулагуїди. Краєм і так протягом усього правління Масуда фактично керували ільханські урядовці; з його смертю це пряме управління в таких центрах, як Конья, Нігде та Аксарай, втратило й формальне прикриття.", "80f4e444"]},
"OLAYLAR_EK16:1309-01-01:0":{"b": ["Поширення бейліку Джандаридів на Кастамону — Чанкири — Бартин — Сафранболу", "64e39ad0"], "d": ["За статтею TDV «Джандариди», бейлік заснував на початку XIV століття в околицях Кастамону та Синопа Шемседдін Яман Джандар, якому ільхан Гайхату надав як ікту Ефлані з околицями; через брак джерел точна дата заснування невідома. Наступника Джандара Сулейман-бея згадують як правителя, що заступив бейлік Чобаногулларів, — тобто околиці Кастамону та Чанкири перейшли до Джандаридів від Чобаногулларів, а лінія Бартин — Сафранболу — Ефлані — з-під прямого ільханського управління.", "72e44d66"]},
"OLAYLAR_EK16:1310-08-15:0":{"b": ["Завоювання Родосу та островів Додеканесу лицарями-іоаннітами (госпітальєрами)", "67885b4b"], "d": ["Стаття TDV «Родос» фіксує, що 1309 року острів перейшов у руки лицарів-іоаннітів (госпітальєрів, ісбітарійє); стандартна історія госпітальєрів (див. J. Riley-Smith, The Knights Hospitaller) уточнює, що облога почалася влітку 1306 року, а місто Родос, яке довго трималося завдяки візантійським підкріпленням, пало перед силами великого магістра Фулька де Вілларе лише 15 серпня 1310 року. Від цієї дати до османського завоювання 1522 року острів буде осідком лицарів, а навколишні острови Додеканесу в тому самому процесі перейшли від Візантії під владу госпітальєрів.", "c1422e2c"]},
"OLAYLAR_EK16:1313-01-01:0":{"b": ["Лівонські лицарі повертають від Литви замок Дюнабург", "92119516"], "d": ["Близько 1281 року литовці взяли Єрсіку та обміняли її на орденський замок Дюнабург. 1313 року замок знову перейшов у руки лівонських лицарів і залишався осідком орденського комтурства.", "0cdd86e0"]},
"OLAYLAR_EK16:1315-01-01:0":{"b": ["Лицарі-іоанніти беруть Кос (Істанкьой)", "445666f7"], "d": ["За статтею TDV «Кос», лицарі-іоанніти, оселившись на Родосі, взяли й Кос (1315) та збудували нові фортеці. Так острів перейшов під лицарське панування, що тривало до 1523 року; під чиєю владою був Кос після падіння міста Родос 1310 року, у TDV докладно не пояснено.", "145d1bad"]},
"OLAYLAR_EK16:1325-01-01:0":{"b": ["Митрополичу кафедру перенесено до Москви", "d20099f8"], "d": ["Глава Руської православної церкви митрополит Петро переніс свій релігійний центр до Москви. Це стало початком піднесення Москви як не лише політичного, а й релігійного центру та зміцнило легітимність князівства.", "4e31c42f"]},
"OLAYLAR_EK16:1330-01-01:0":{"b": ["Лівонський орден став сюзереном міста Риги", "21453047"], "d": ["Ризьке архієпископство та місто, які за підтримки великих князів литовських Вітеня та Гедиміна воювали проти Ордену, 1330 року зазнали поразки; Лівонський орден став сюзереном міста. За Саласпілським договором 1452 року Рига перейшла під спільний сюзеренітет Ордену та архієпископа.", "28788282"]},
"OLAYLAR_EK16:1335-01-01:0":{"b": ["Заснування бейліку Еретни — Центральна Анатолія після Ільханату", "a67bacd9"], "d": ["За статтею TDV «Еретніди», Алаеддін Еретна, ільханський урядовець уйгурського походження, після смерті ільхана Абу Саїда Бахадур-хана 1335 року перетворив ільханське намісництво в Анатолії на фактично незалежне управління; спершу він виступав як намісник мамлюцького султана, 1340 року вилучив ім'я мамлюків із хутби, а близько 1341 року проголосив повну незалежність. Бейлік із центром спершу в Сівасі, а потім у Кайсері аж до смерті Еретни (1352) встановив широке панування в Центральній Анатолії, яке охоплювало Амасью, Токат, Чорум, Нігде, Аксарай та Ерзінджан; 1381 року йому поклав край Каді Бурханеддін.", "04978a80"]},
"OLAYLAR_EK16:1335-05-01:0":{"b": ["Габсбурги захоплюють Крайну та Карінтію (Любляну)", "039918d3"], "d": ["Після того як 2 квітня 1335 року в замку Тіроль помер без спадкоємців герцог Карінтії та граф Тіролю Генріх VI, брати Габсбурги Альбрехт II і Отто IV відповідно до таємної угоди, укладеної 23 листопада 1330 року з Людовіком Баварським, отримали за імператорською інвеститурою герцогство Карінтію та залежну від нього Крайну (край, що охоплює й нинішню Любляну); Тіроль же залишився окремо через доньку Генріха. Це був один із перших великих кроків габсбурзької експансії в Альпах, і Крайна залишатиметься (з перервами) в руках Габсбургів / Австрії до 1918 року.", "4dbed85a"]},
"OLAYLAR_EK16:1340-01-01:0":{"b": ["Заснування держави Джалаїридів — Азербайджан після Ільханату", "a13ada90"], "d": ["За статтею TDV «Джалаїриди», Хасан Бузург, онук ільханського еміра Нояна, скориставшись боротьбою за престол, що спалахнула після смерті ільхана Абу Саїда Бахадур-хана, 1340 року заснував незалежну державу з центром у Тебрізі. Так Джалаїриди стали першою великою династією, яка заповнила післяільханський вакуум в Азербайджані та його околицях; за наступника Увайса (1356—1374) їхні володіння сягнуть Мосула та Діярбакира.", "224cbb81"]},
"OLAYLAR_EK16:1341-01-01:0":{"b": ["Утворено Нижегородсько-Суздальське велике князівство — хан видав ярлик Костянтинові Васильовичу", "c69f5198"], "d": ["Хан Золотої Орди Узбек (у записі — Узбек/Джанібек) віддав суздальському князеві Костянтину Васильовичу Нижегородсько-Городецьке князівство; князівство стало суперником Москви, а 1392 року Василь I приєднав його до Москви.", "4b281b04"]},
"OLAYLAR_EK16:1346-01-01:0":{"b": ["Данія продала Північну Естонію (Ревель і Нарву) Лівонському ордену", "6861ba55"], "d": ["Данське королівство продало свої землі в Північній Естонії разом із Ревелем і Нарвою Лівонському ордену. Край залишався в руках Ордену до Лівонської війни.", "0723514c"]},
"OLAYLAR_EK16:1348-01-01:0":{"b": ["Болотовський договір — Новгород визнав незалежність Пскова", "08eca44d"], "d": ["Новгород визнав Псков «молодшим братом»; Псков зі своїм вічем і посадником жив як незалежна міська республіка, доки 1510 року його не приєднали до Москви.", "12f9ce2f"]},
"OLAYLAR_EK16:1392-01-01:0":{"b": ["Василь I приєднав Нижегородсько-Суздальське князівство до Москви", "5ecf441b"], "d": ["За ярликом, отриманим від хана Тохтамиша, Василь I приєднав до Москви Нижній Новгород, Городець і Суздаль; почався вихід Москви до басейнів Волги та Оки.", "ac83ac55"]}
});
